def _enumerate_descendants_winapi(root_pid):
    """Return a list of descendant PIDs of ``root_pid`` using Toolhelp32.

    Used by the shutdown path INSTEAD of spawning ``powershell.exe`` to walk
    the process tree. Spawning powershell during app shutdown was triggering
    ``0xc0000142`` (STATUS_DLL_INIT_FAILED) popups on some Windows 10/11
    boxes — likely a race between us tearing down DLLs and the new shell
    trying to load them. Toolhelp32Snapshot is in-process, kernel32-only,
    and has none of those startup costs.

    Returns ``[]`` on non-Windows or on any failure (callers already handle
    that gracefully).
    """
    if os.name != "nt":
        return []
    try:
        import ctypes
        from ctypes import wintypes
    except Exception:
        return []

    TH32CS_SNAPPROCESS = 0x00000002
    INVALID_HANDLE_VALUE = ctypes.c_void_p(-1).value

    class PROCESSENTRY32(ctypes.Structure):
        _fields_ = [
            ("dwSize", wintypes.DWORD),
            ("cntUsage", wintypes.DWORD),
            ("th32ProcessID", wintypes.DWORD),
            ("th32DefaultHeapID", ctypes.c_void_p),
            ("th32ModuleID", wintypes.DWORD),
            ("cntThreads", wintypes.DWORD),
            ("th32ParentProcessID", wintypes.DWORD),
            ("pcPriClassBase", wintypes.LONG),
            ("dwFlags", wintypes.DWORD),
            ("szExeFile", ctypes.c_char * 260),
        ]

    try:
        kernel32 = ctypes.windll.kernel32
        kernel32.CreateToolhelp32Snapshot.restype = wintypes.HANDLE
        kernel32.Process32First.argtypes = [wintypes.HANDLE, ctypes.POINTER(PROCESSENTRY32)]
        kernel32.Process32Next.argtypes = [wintypes.HANDLE, ctypes.POINTER(PROCESSENTRY32)]
        kernel32.CloseHandle.argtypes = [wintypes.HANDLE]

        snap = kernel32.CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0)
        if not snap or snap == INVALID_HANDLE_VALUE:
            return []

        try:
            entry = PROCESSENTRY32()
            entry.dwSize = ctypes.sizeof(PROCESSENTRY32)
            parent_of = {}
            if not kernel32.Process32First(snap, ctypes.byref(entry)):
                return []
            while True:
                parent_of[int(entry.th32ProcessID)] = int(entry.th32ParentProcessID)
                if not kernel32.Process32Next(snap, ctypes.byref(entry)):
                    break
        finally:
            kernel32.CloseHandle(snap)

        # BFS from root_pid through parent_of inverted lookup.
        children_of = {}
        for pid, ppid in parent_of.items():
            children_of.setdefault(ppid, []).append(pid)

        seen = set()
        result = []
        todo = [int(root_pid)]
        while todo:
            cur = todo.pop(0)
            if cur in seen:
                continue
            seen.add(cur)
            for kid in children_of.get(cur, ()):
                if kid != int(root_pid) and kid not in seen:
                    result.append(kid)
                    todo.append(kid)
        return result
    except Exception:
        return []


class InstallerThread(QThread):
    """Thread for running smart installer without freezing UI"""
    log_output = Signal(str)
    finished_signal = Signal(bool)  # True if successful
    
    def __init__(self, install_type: str):  # "pytorch", "dependencies", or "all"
        super().__init__()
        self.install_type = install_type
    
    def run(self):
        try:
            # For repair, use InstallerV2 for targeted repair
            if self.install_type == "repair":
                self.log_output.emit("Starting targeted repair process...")
                self.log_output.emit("This will only fix broken/missing packages without reinstalling everything")
                
                # Import and run InstallerV2 repair
                from installer_v2 import InstallerV2
                from pathlib import Path
                
                # Explicitly target LLM/.venv (not bootstrap/.venv)
                llm_root = Path(__file__).parent.parent
                target_venv = llm_root / ".venv"
                
                self.log_output.emit(f"Target environment: {target_venv}")
                
                installer_v2 = InstallerV2(root_dir=llm_root)
                
                # Redirect logs
                original_log = installer_v2.log
                def gui_log(message):
                    # Ensure message is safe for the log output
                    try:
                        self.log_output.emit(message)
                    except Exception:
                        pass
                    
                    # Original log already has safety for print() now
                    original_log(message)
                
                installer_v2.log = gui_log

                success = installer_v2.repair()
                self.log_output.emit(f"Main repair completed with result: {success}")

                # Post-install: hand off to EnvRepairer for the unified
                # diff/install/verify pass. This catches:
                #   * any base-profile package installer_v2 thought it
                #     installed but is actually still wrong (uses
                #     PipExecutor.freeze + PinResolver.required_for to
                #     compute the truth instead of trusting installer_v2's
                #     internal accounting);
                #   * training extras (unsloth/trl/triton-windows/...) so
                #     the user doesn't discover a broken training stack
                #     on first 'Start Training' click;
                #   * torch ABI mismatches that survive installer_v2 —
                #     EnvRepairer's torch trio coherence step rebuilds
                #     the matched cu* trio when torchvision._C.pyd or
                #     libtorchaudio fails to load.
                # Soft dependency: a non-OK outcome here doesn't fail the
                # whole repair (training/extras are opt-in), it logs the
                # detail and lets installer_v2's success stand.
                if success:
                    try:
                        self.log_output.emit("")
                        self.log_output.emit("=" * 60)
                        self.log_output.emit("Unified post-install verify (EnvRepairer)")
                        self.log_output.emit("=" * 60)
                        from core.install import EnvRepairer, RepairOutcome, resolve_profile_id
                        from core.runtime.owllm_python import get_owllm_env
                        env = get_owllm_env(llm_root)
                        pid = resolve_profile_id(env.env_key, project_root=llm_root)
                        repairer = EnvRepairer(project_root=llm_root)
                        result = repairer.repair(
                            env_python=env.python_exe,
                            env_id=pid,
                            extras=["training"],
                            log=lambda m: self.log_output.emit(f"  {m}"),
                        )
                        if result.outcome == RepairOutcome.SUCCESS:
                            self.log_output.emit(f"✓ {result.summary}")
                        elif result.outcome == RepairOutcome.SUCCESS_WITH_WARNINGS:
                            self.log_output.emit(f"⚠ {result.summary}")
                        else:
                            self.log_output.emit(f"✗ Post-install verify: {result.summary}")
                            for r in result.pip_results:
                                if not r.ok:
                                    self.log_output.emit(f"  Failed pip log: {r.log_path}")
                    except Exception as post_exc:
                        import traceback as _tb
                        self.log_output.emit(
                            f"⚠ Post-install verify raised "
                            f"{type(post_exc).__name__}: {post_exc}"
                        )
                        self.log_output.emit(_tb.format_exc())
                        self.log_output.emit(
                            "Main repair still SUCCEEDED. The training tab will "
                            "retry the install on demand and surface any actual error."
                        )

                self.log_output.emit(f"Repair completed with result: {success}")
                self.finished_signal.emit(success)
                return

            # For rebuild, use InstallerV2 for destructive rebuild
            if self.install_type == "rebuild":
                self.log_output.emit("Starting rebuild process...")
                self.log_output.emit("WARNING: This will delete the existing environment and wheelhouse")
                self.log_output.emit("All packages will be re-downloaded and reinstalled")
                
                # Import and run InstallerV2 rebuild
                from installer_v2 import InstallerV2
                from pathlib import Path
                
                # Explicitly target LLM/.venv (not bootstrap/.venv)
                llm_root = Path(__file__).parent.parent
                target_venv = llm_root / ".venv"
                
                self.log_output.emit(f"Target environment: {target_venv}")
                
                installer_v2 = InstallerV2(root_dir=llm_root)
                
                # Redirect logs
                original_log = installer_v2.log
                def gui_log(message):
                    # Ensure message is safe for the log output
                    try:
                        self.log_output.emit(message)
                    except Exception:
                        pass
                    
                    # Original log already has safety for print() now
                    original_log(message)
                
                installer_v2.log = gui_log
                
                success = installer_v2.rebuild()
                self.log_output.emit(f"Rebuild completed with result: {success}")
                self.finished_signal.emit(success)
                return
            
            # For all other operations, use SmartInstaller
            installer = SmartInstaller()
            
            # Redirect installer logs to GUI
            original_log = installer.log
            def gui_log(message):
                self.log_output.emit(message)
                original_log(message)
            installer.log = gui_log
            
            # Run detection
            self.log_output.emit("Detecting system configuration...")
            installer.run_detection()
            
            # Install based on type
            if self.install_type == "pytorch":
                success = installer.install_pytorch()
            elif self.install_type == "dependencies":
                success = installer.install_dependencies()
            elif self.install_type == "uninstall":
                self.log_output.emit("Starting uninstallation process...")
                python_exe = sys.executable
                self.log_output.emit(f"Using Python: {python_exe}")
                success = installer.uninstall_all(python_executable=python_exe)
                self.log_output.emit(f"Uninstallation completed with result: {success}")
            else:  # "all"
                success = installer.install()
            
            self.finished_signal.emit(success)
        except Exception as e:
            import traceback
            error_details = traceback.format_exc()
            self.log_output.emit(f"\n[ERROR] Installation failed with exception:")
            self.log_output.emit(str(e))
            self.log_output.emit("\nFull traceback:")
            self.log_output.emit(error_details)
            self.finished_signal.emit(False)


class PipPackageThread(QThread):
    """Thread for running a single pip install/uninstall without freezing UI.

    Migration 4/6: replaced the bespoke pip-runner (regex-based +cuXXX
    index detection, hand-rolled subprocess.Popen, no log persistence)
    with the unified ``core.install.PipExecutor``. PipMode is selected
    automatically based on the package spec — torch+cuXXX specs get
    PYPI_PLUS_CU121/124, everything else uses PYPI.

    Same Qt signal contract (``log_output`` / ``finished_signal``) so
    the UI doesn't change.
    """
    log_output = Signal(str)
    finished_signal = Signal(bool)

    def __init__(self, action: str, package_spec: str, python_exe: str | None = None):
        super().__init__()
        self.action = action  # "install" | "uninstall"
        self.package_spec = package_spec
        self.python_exe = python_exe or sys.executable

    def _pick_mode(self):
        """Mode selection: cu121/cu124 for torch wheels, PyPI otherwise."""
        from core.install import PipMode
        spec = self.package_spec or ""
        if "+cu121" in spec:
            return PipMode.PYPI_PLUS_CU121
        if "+cu124" in spec:
            return PipMode.PYPI_PLUS_CU124
        return PipMode.PYPI

    def run(self):
        try:
            from core.install import PipExecutor
            from pathlib import Path
            project_root = Path(__file__).parent.parent
            executor = PipExecutor(project_root=project_root)
            stream = lambda line: self.log_output.emit(line)

            if self.action == "uninstall":
                result = executor.uninstall(
                    env_python=Path(self.python_exe),
                    packages=[self.package_spec],
                    log=stream,
                )
            else:
                result = executor.install(
                    env_python=Path(self.python_exe),
                    specs=[self.package_spec],
                    mode=self._pick_mode(),
                    no_deps=True,  # single-package repair: don't cascade
                    log=stream,
                    label=f"pkg-{self.action}",
                )
            if not result.ok:
                self.log_output.emit(f"\n[FAIL] {result.summary}")
                self.log_output.emit(f"Detailed log: {result.log_path}")
            self.finished_signal.emit(result.ok)
        except Exception as e:
            import traceback
            self.log_output.emit(f"[ERROR] pip task failed: {e}")
            self.log_output.emit(traceback.format_exc())
            self.finished_signal.emit(False)


class EnvironmentSetupDialog(QDialog):
    """Progress dialog for per-model environment creation/installation"""
    
    def __init__(self, parent=None, model_name: str = ""):
        super().__init__(parent)
        self.setWindowTitle("Setting Up Model Environment")
        self.setMinimumWidth(500)
        self.setModal(False)  # Non-modal so it doesn't block other UI
        
        # Dark theme styling
        self.setStyleSheet("""
            QDialog {
                background-color: #1e1e1e;
                color: white;
            }
            QLabel {
                color: white;
                background: transparent;
            }
        """)
        
        layout = QVBoxLayout(self)
        layout.setSpacing(15)
        layout.setContentsMargins(20, 20, 20, 20)
        
        # Title
        title = QLabel(f"<h3>Preparing environment for: {model_name or 'model'}</h3>")
        title.setStyleSheet("color: white; font-weight: bold; background: transparent;")
        layout.addWidget(title)
        
        # Status label
        self.status_label = QLabel("Initializing...")
        self.status_label.setStyleSheet("color: #cccccc; font-size: 11pt; background: transparent;")
        self.status_label.setWordWrap(True)
        layout.addWidget(self.status_label)
        
        # Progress bar (indeterminate until we know steps)
        self.progress_bar = QProgressBar()
        self.progress_bar.setMinimum(0)
        self.progress_bar.setMaximum(0)  # Indeterminate
        self.progress_bar.setTextVisible(True)
        self.progress_bar.setFormat("Working...")
        self.progress_bar.setStyleSheet("""
            QProgressBar {
                border: 2px solid #444;
                border-radius: 6px;
                text-align: center;
                background-color: #1e1e1e;
                color: white;
                font-weight: bold;
                height: 30px;
            }
            QProgressBar::chunk {
                background: qlineargradient(x1:0, y1:0, x2:1, y2:0, 
                    stop:0 #667eea, stop:1 #764ba2);
                border-radius: 4px;
            }
        """)
        layout.addWidget(self.progress_bar)
        
        # Info text
        info = QLabel(
            "This may take several minutes on first run.\n"
            "The environment is being created and dependencies installed.\n"
            "Please wait..."
        )
        info.setStyleSheet("color: #888; font-size: 9pt; background: transparent;")
        info.setWordWrap(True)
        layout.addWidget(info)
        
        # Track installation phases for progress
        self.phase = 0
        self.phases = [
            "Creating virtual environment...",
            "Installing server framework...",
            "Installing CUDA PyTorch...",
            "Installing ML dependencies...",
            "Verifying installation...",
        ]
    
    def update_status(self, message: str):
        """Update status text and progress based on message content"""
        self.status_label.setText(message)
        
        # Detect phase from message keywords
        msg_lower = message.lower()
        if "creating virtual environment" in msg_lower or "environment for" in msg_lower:
            self.phase = 0
        elif "server framework" in msg_lower or "uvicorn" in msg_lower:
            self.phase = 1
            self.progress_bar.setMaximum(len(self.phases))
            self.progress_bar.setValue(1)
        elif "torch" in msg_lower and ("installing" in msg_lower or "ensuring" in msg_lower):
            self.phase = 2
            self.progress_bar.setValue(2)
        elif "installing" in msg_lower and ("transformers" in msg_lower or "minimal inference" in msg_lower):
            self.phase = 3
            self.progress_bar.setValue(3)
        elif "verifying" in msg_lower or "dependencies installed" in msg_lower:
            self.phase = 4
            self.progress_bar.setValue(4)
        
        if self.progress_bar.maximum() > 0:
            self.progress_bar.setFormat(f"{self.phases[self.phase]} ({self.phase + 1}/{len(self.phases)})")
        else:
            self.progress_bar.setFormat(message[:50] + "..." if len(message) > 50 else message)
    
    def set_complete(self):
        """Mark installation as complete"""
        self.progress_bar.setMaximum(100)
        self.progress_bar.setValue(100)
        self.progress_bar.setFormat("Complete!")
        self.status_label.setText("Environment setup complete. Starting server...")


class ToolInferenceWorker(QThread):
    """Thread for running tool-enabled inference without blocking UI"""
    progress_update = Signal(str)  # Progress messages
    tool_call_detected = Signal(str, dict, str)  # tool_name, args, model_column
    tool_result_received = Signal(str, object, bool, str)  # tool_name, result, success, model_column
    inference_finished = Signal(str, list, str)  # final_output, tool_log, model_column
    inference_failed = Signal(str, str)  # error_message, model_column
    
    def __init__(
        self,
        prompt: str,
        model_id: str,
        model_column: str,
        base_model: str = "",
        system_prompt: str = "",
        max_new_tokens: int = 1024,
        temperature: float = 0.7,
        images: Optional[List[str]] = None,
        enable_tools: bool = True,
    ):
        super().__init__()
        self.prompt = prompt
        self.model_id = model_id
        self.model_column = model_column
        self.base_model = str(base_model or "").strip()
        self.system_prompt = system_prompt
        self.max_new_tokens = max_new_tokens
        self.temperature = temperature
        self.images = list(images) if images else []
        # Whether to run the multi-pass tool-calling loop. When False,
        # we go through the lean ``run_inference`` path — same as agent
        # backends use — instead of ``run_inference_with_tools`` which
        # iterates up to 5 times, sniffing tool-call patterns in every
        # output. Regular Test Chat (where the user just wants
        # back-and-forth replies, no tools) used to be forced through
        # the iterative loop, which made it 3-5x slower than agents
        # for the same model. The Tool Chat sub-tab still passes True.
        self.enable_tools = bool(enable_tools)
    
    def run(self):
        """Run tool-enabled inference in background"""
        try:
            from core.inference import (
                ToolEnabledInferenceConfig,
                InferenceConfig,
                run_inference_with_tools,
                run_inference,
            )
            from desktop_app.config.config_manager import ConfigManager
            import urllib.request

            # FAST PATH: tools disabled -> run a single forward pass
            # via run_inference and emit the result. Skips the
            # tool-server health probe, the up-to-5-iteration tool
            # loop, and the ToolCallDetector overhead. Regular Test
            # Chat hits this path; Tool Chat sub-tab keeps the full
            # iterative path below.
            #
            # Note: ``InferenceConfig`` (the base) does NOT accept a
            # ``system_prompt`` field — only the tool subclass does.
            # The Test Chat path bakes the system prompt into the
            # already-rendered ``self.prompt`` (see
            # ``_build_test_prompt_for_model``), so we just pass it
            # through without a separate system_prompt argument.
            if not self.enable_tools:
                self.progress_update.emit("[INFO] Initializing inference (tools disabled)...")
                ic = InferenceConfig(
                    prompt=self.prompt,
                    model_id=self.model_id,
                    base_model=self.base_model or None,
                    max_new_tokens=self.max_new_tokens,
                    temperature=self.temperature,
                    images=self.images,
                )
                final_output = run_inference(
                    ic,
                    log_callback=lambda m: self.progress_update.emit(str(m)),
                )
                self.inference_finished.emit(final_output, [], self.model_column)
                return

            self.progress_update.emit("[INFO] Initializing tool-enabled inference...")

            # Load tool server config (single source of truth)
            cfg_mgr = ConfigManager()
            tool_cfg = cfg_mgr.load()
            execution_mode = tool_cfg.get("execution_mode", "http")  # Default to HTTP for backward compatibility
            workspace_root = Path(tool_cfg.get("workspace_root", "."))

            native_executor = None
            tool_server_url = None
            tool_server_token = None

            if execution_mode == "native":
                # Native mode - execute tools directly
                self.progress_update.emit("[INFO] Using native tool execution (no HTTP server needed)")
                from core.tool_calling_native import NativeToolExecutor
                native_executor = NativeToolExecutor(workspace_root, tool_cfg)
            else:
                # HTTP mode - use tool server
                port = int(tool_cfg.get("port", 8763))
                host = str(tool_cfg.get("host", "127.0.0.1")).strip() or "127.0.0.1"
                token = str(tool_cfg.get("token", "")).strip()

                # Always connect locally (even if server binds 0.0.0.0)
                if host in ("0.0.0.0", "::", "[::]"):
                    host = "127.0.0.1"
                tool_server_url = f"http://{host}:{port}"
                tool_server_token = token

                # Quick reachability check (gives a clear error instead of "nothing happens")
                try:
                    with urllib.request.urlopen(f"{tool_server_url}/health", timeout=1) as resp:
                        _ = resp.read()
                except Exception as e:
                    raise RuntimeError(
                        f"Tool Server is not reachable at {tool_server_url}.\n"
                        f"Open the Servers tab and start 'Tool Server (MCP)'.\n"
                        f"Details: {e}"
                    )
            
            # Create config
            cfg = ToolEnabledInferenceConfig(
                prompt=self.prompt,
                model_id=self.model_id,
                base_model=self.base_model or None,
                enable_tools=True,
                tool_server_url=tool_server_url or "",  # Empty string if native mode
                tool_server_token=tool_server_token or "",  # Empty string if native mode
                auto_execute_safe_tools=True,
                max_tool_iterations=5,
                system_prompt=self.system_prompt,
                max_new_tokens=self.max_new_tokens,
                temperature=self.temperature,
                images=self.images,
                native_executor=native_executor  # Pass native executor if in native mode
            )
            
            # Tool callback to emit signals
            def tool_callback(tool_name: str, args: dict, result):
                self.tool_call_detected.emit(tool_name, args, self.model_column)
                success = bool(isinstance(result, dict) and result.get("success"))
                if isinstance(result, dict):
                    payload = result.get("result") if success else result.get("error")
                    if payload is None and "result" in result:
                        payload = result.get("result")
                else:
                    payload = result
                self.tool_result_received.emit(tool_name, payload, success, self.model_column)
            
            self.progress_update.emit("[INFO] Preparing inference...")
            
            # Run inference
            final_output, tool_log = run_inference_with_tools(
                cfg=cfg,
                tool_callback=tool_callback,
                approval_callback=None,  # Auto-approve in test mode
                log_callback=lambda m: self.progress_update.emit(str(m))
            )
            
            # Emit success
            self.inference_finished.emit(final_output, tool_log, self.model_column)
            
        except Exception as e:
            import traceback
            error_msg = f"[ERROR] Tool-enabled inference failed: {e}\n\nTraceback:\n{traceback.format_exc()}"
            self.inference_failed.emit(error_msg, self.model_column)


class CudaBootstrapThread(QThread):
    """Thread to run SmartInstaller CUDA linker bootstrap without freezing UI."""
    log_output = Signal(str)
    finished_signal = Signal(bool)

    def __init__(self, python_exe: str, llm_dir: str):
        super().__init__()
        self.python_exe = python_exe or sys.executable
        self.llm_dir = llm_dir

    def run(self):
        import subprocess
        try:
            # Run inside the TARGET venv python so sysconfig paths match that environment.
            code = f"""
import sys
from pathlib import Path
llm_dir = Path(r\"{self.llm_dir}\")
if str(llm_dir) not in sys.path:
    sys.path.insert(0, str(llm_dir))
from smart_installer import SmartInstaller
installer = SmartInstaller()
ok1 = installer._bootstrap_cuda_libs(sys.executable)
ok2 = installer._patch_triton_runtime_build(sys.executable)
ok3 = installer._patch_triton_windows_utils(sys.executable)
print(f\"BOOTSTRAP_CUDA_LIBS: {{ok1}}\")
print(f\"PATCH_TRITON_RUNTIME_BUILD: {{ok2}}\")
print(f\"PATCH_TRITON_WINDOWS_UTILS: {{ok3}}\")
print(\"OK\")
"""
            cmd = [self.python_exe, "-c", code]
            self.log_output.emit("Running: " + " ".join(cmd[:3]) + " ...")
            proc = subprocess.Popen(
                cmd,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                text=True,
                bufsize=1,
                universal_newlines=True,
                **SUBPROCESS_FLAGS,
            )
            assert proc.stdout is not None
            for line in proc.stdout:
                line = line.rstrip()
                if line:
                    self.log_output.emit(line)
            rc = proc.wait()
            self.finished_signal.emit(rc == 0)
        except Exception as e:
            import traceback
            self.log_output.emit(f"[ERROR] CUDA bootstrap task failed: {e}")
            self.log_output.emit(traceback.format_exc())
            self.finished_signal.emit(False)


class SystemDetectThread(QThread):
    """Thread for running system detection without freezing UI."""
    detected = Signal(dict)        # system_info dict
    error = Signal(str)            # error string

    def run(self):
        try:
            detector = SystemDetector()
            # Single pass to avoid duplicate CUDA/GPU probing at startup.
            system_info = detector.detect_all()
            # Cache normalized hardware profile for downstream UI checks.
            try:
                system_info["hardware_profile"] = detector.get_hardware_profile()
            except Exception:
                pass
            self.detected.emit(system_info)
        except Exception as e:
            import traceback
            self.error.emit(traceback.format_exc())


class OnboardingThread(QThread):
    """Thread for running model onboarding without freezing UI"""
    progress = Signal(str)  # log message
    finished = Signal(dict)  # onboarding result
    error = Signal(str)  # error message
    
    def __init__(self, model_id: str, base_model_path: str, adapter_dir: Optional[str] = None):
        super().__init__()
        self.model_id = model_id
        self.base_model_path = base_model_path
        self.adapter_dir = adapter_dir
    
    def run(self):
        try:
            from core.model_onboarding import get_onboarding_service
            
            def log_callback(msg):
                self.progress.emit(msg)
            
            onboarding = get_onboarding_service()
            result = onboarding.ensure_model_onboarded(
                model_id=self.model_id,
                base_model_path=self.base_model_path,
                adapter_dir=self.adapter_dir,
                profile_data=None,  # Auto-detect
                log_callback=log_callback,
                allow_repair=True
            )
            
            self.finished.emit(result)
        except Exception as e:
            self.error.emit(str(e))


class RepairThread(QThread):
    """Thread for repairing/resuming incomplete model downloads"""
    progress = Signal(int)  # 0-100
    finished = Signal(str)  # destination path
    error = Signal(str)     # error message
    status = Signal(str)    # current status message (e.g., "Downloading model-00035-of-00061.bin (35/61)")
    
    def __init__(self, model_id: str, existing_dir: Path, force_fresh_only: bool = False, cache_dir: Optional[Path] = None, token: Optional[str] = None, allow_patterns: Optional[List[str]] = None):
        super().__init__()
        self.model_id = model_id
        self.existing_dir = existing_dir
        self.force_fresh_only = force_fresh_only
        self.cache_dir = cache_dir
        self.token = token
        self.allow_patterns = allow_patterns  # When set, repair only these files (e.g. single GGUF)
        import threading
        self._stop_requested = threading.Event()
    
    def request_stop(self) -> None:
        """Request cooperative stop (best-effort)."""
        try:
            self.requestInterruption()
        except Exception:
            pass
        try:
            self._stop_requested.set()
        except Exception:
            pass
    
    def run(self):
        try:
            import os
            import logging
            import threading
            import time
            from core.model_file_utils import download_repo_files
            
            # Initialize logger and watchdog variables
            logger = logging.getLogger(__name__)
            stall_detected = threading.Event()
            watchdog_stop = threading.Event()
            
            # Use token passed from main thread (env + QSettings + cached), else env fallback
            token = self.token
            if not token:
                token = (
                    os.getenv("HF_TOKEN")
                    or os.getenv("HUGGINGFACE_HUB_TOKEN")
                    or os.getenv("HUGGINGFACEHUB_API_TOKEN")
                )
            
            # Stall watchdog: monitor .incomplete file growth
            def stall_watchdog():
                """Monitor download cache for stalled .incomplete files"""
                last_size = 0
                last_check_time = time.time()
                stall_timeout = 15 * 60  # 15 minutes without growth = stalled
                
                while not watchdog_stop.is_set() and not stall_detected.is_set():
                    try:
                        # Check cache directory for .incomplete files
                        cache_dirs = []
                        if self.cache_dir and self.cache_dir.exists():
                            cache_dirs.append(self.cache_dir)
                        # Also check model-local cache
                        model_cache = self.existing_dir / ".cache" / "huggingface" / "download"
                        if model_cache.exists():
                            cache_dirs.append(model_cache)
                        
                        current_size = 0
                        newest_incomplete = None
                        newest_mtime = 0
                        
                        for cache_dir in cache_dirs:
                            try:
                                for incomplete_file in cache_dir.rglob("*.incomplete"):
                                    try:
                                        stat = incomplete_file.stat()
                                        if stat.st_mtime > newest_mtime:
                                            newest_mtime = stat.st_mtime
                                            newest_incomplete = incomplete_file
                                            current_size = stat.st_size
                                    except Exception:
                                        continue
                            except Exception:
                                continue
                        
                        if newest_incomplete and newest_incomplete.exists():
                            if current_size > last_size:
                                # File is growing - reset timer
                                last_size = current_size
                                last_check_time = time.time()
                            else:
                                # File not growing - check if timeout exceeded
                                elapsed = time.time() - last_check_time
                                if elapsed > stall_timeout:
                                    logger.warning(f"Stall detected: {newest_incomplete.name} hasn't grown in {elapsed/60:.1f} minutes")
                                    stall_detected.set()
                                    return
                        else:
                            # No incomplete files - reset
                            last_size = 0
                            last_check_time = time.time()
                        
                        time.sleep(30)  # Check every 30 seconds
                    except Exception as e:
                        logger.debug(f"Watchdog error: {e}")
                        time.sleep(30)
            
            # Start watchdog thread
            watchdog_thread = threading.Thread(target=stall_watchdog, daemon=True)
            watchdog_thread.start()
            
            # Progress callback for real-time updates
            current_file_status = "Preparing download..."
            last_progress_bytes = 0
            last_progress_ts = 0.0
            def progress_callback(bytes_done: int, bytes_total: int):
                nonlocal last_progress_bytes, last_progress_ts
                now_ts = time.time()
                speed_suffix = ""
                if last_progress_ts > 0 and bytes_done >= last_progress_bytes:
                    dt = max(1e-6, now_ts - last_progress_ts)
                    bps = (bytes_done - last_progress_bytes) / dt
                    if bps > 0:
                        speed_suffix = f" | {bps / (1024 * 1024):.1f} MB/s"
                last_progress_bytes = max(last_progress_bytes, bytes_done)
                last_progress_ts = now_ts
                if bytes_total > 0 and bytes_total >= bytes_done:
                    percent = int((bytes_done / bytes_total) * 100)
                    # Allow 100% when bytes_done >= bytes_total (download complete)
                    if bytes_done >= bytes_total:
                        percent = 100
                    elif bytes_done > 0:
                        percent = max(1, min(percent, 99))  # Clamp 1-99% during download (allow 0% for start)
                    else:
                        percent = 0
                    self.progress.emit(percent)
                    # Emit rich status text with live byte progress for GUI label.
                    done_gb = bytes_done / (1024 ** 3)
                    total_gb = bytes_total / (1024 ** 3)
                    self.status.emit(f"{current_file_status}  |  {done_gb:.2f}/{total_gb:.2f} GB ({percent}%)")
                else:
                    # Unknown total - emit based on bytes downloaded (rough estimate)
                    # ~1% per 50MB, but start from 0%
                    if bytes_done > 0:
                        estimated_percent = min(int(bytes_done / (50 * 1024 * 1024)), 99)
                        self.progress.emit(max(1, estimated_percent))  # At least 1% if we have bytes
                        done_gb = bytes_done / (1024 ** 3)
                        self.status.emit(f"{current_file_status}  |  {done_gb:.2f} GB downloaded")
                    else:
                        self.progress.emit(0)
            
            should_cancel = lambda: self._stop_requested.is_set() or self.isInterruptionRequested()
            
            # Status callback to show current file being downloaded
            def status_callback(filename: str, file_idx: int, total_files: int, attempt: int):
                import logging
                logger = logging.getLogger(__name__)
                status_msg = f"Downloading {filename} ({file_idx}/{total_files})"
                if attempt > 1:
                    status_msg += f" - attempt {attempt}"
                logger.info(status_msg)
                nonlocal current_file_status
                current_file_status = status_msg
                # Emit status signal for UI display
                self.status.emit(status_msg)
            
            # Start with metadata-only preflight (if missing)
            self.progress.emit(1)
            metadata_patterns = [
                "*.json", "*.txt", "*.md", "*.model", "*.tiktoken",
                "tokenizer.*", "vocab.*", "merges.txt", "special_tokens_map.json",
                "config.json", "generation_config.json", "tokenizer.json"
            ]
            
            # Purge HF cache entry for this model so corrupted same-size shards are not reused
            self.status.emit(f"Purging HF cache for {self.model_id}...")
            from core.model_file_utils import purge_hf_repo_cache
            purge_hf_repo_cache(self.model_id, cache_dir=self.cache_dir)
            
            if self.force_fresh_only:
                # DELETE model directory using same robust strategy as Delete button
                
                self.progress.emit(5)
                logger.info(f"Deleting model directory: {self.existing_dir}")
                
                # Use the same robust deletion as Delete button
                from core.model_file_utils import kill_processes_locking_directory
                import time
                import subprocess
                
                if self.existing_dir.exists():
                    # Step 1: Kill processes
                    kill_processes_locking_directory(self.existing_dir)
                    time.sleep(2)
                    
                    # Step 2: Remove .incomplete files
                    cache_dir = self.existing_dir / ".cache" / "huggingface" / "download"
                    if cache_dir.exists():
                        try:
                            for incomplete_file in cache_dir.rglob("*.incomplete"):
                                try:
                                    incomplete_file.unlink()
                                except Exception:
                                    pass
                            shutil.rmtree(cache_dir, ignore_errors=True)
                        except Exception:
                            pass
                    
                    # Step 3: Robust deletion with retries (same as Delete button)
                    success = False
                    for attempt in range(1, 5):
                        self.progress.emit(5 + (attempt * 3))  # 8, 11, 14, 17%
                        try:
                            if sys.platform == 'win32':
                                # Force delete on Windows using cmd
                                result = subprocess.run(
                                    ['cmd', '/c', 'rmdir', '/S', '/Q', str(self.existing_dir)], 
                                    capture_output=True, 
                                    timeout=30,
                                    **SUBPROCESS_FLAGS
                                )
                                # PowerShell fallback
                                if self.existing_dir.exists() and attempt >= 2:
                                    ps_cmd = f'Remove-Item -Path "{self.existing_dir}" -Recurse -Force -ErrorAction SilentlyContinue'
                                    subprocess.run(
                                        ['powershell', '-Command', ps_cmd],
                                        capture_output=True,
                                        timeout=30,
                                        **SUBPROCESS_FLAGS
                                    )
                            else:
                                shutil.rmtree(self.existing_dir, ignore_errors=True)
                            
                            if not self.existing_dir.exists():
                                success = True
                                logger.info(f"✓ Successfully deleted {self.existing_dir.name}")
                                break
                        except Exception as e:
                            logger.warning(f"Deletion attempt {attempt} failed: {e}")
                        
                        if attempt < 4:
                            time.sleep(2)
                            kill_processes_locking_directory(self.existing_dir)
                    
                    if not success:
                        # Final attempt
                        try:
                            shutil.rmtree(self.existing_dir, ignore_errors=True)
                        except Exception:
                            pass
                        
                        if self.existing_dir.exists():
                            raise RuntimeError(
                                f"Cannot delete {self.existing_dir} - files are locked by another process. "
                                "Please close other applications and try again."
                            )
                
                # Directory deleted - now download fresh (metadata first, then weights/selected)
                self.progress.emit(25)
                logger.info(f"Starting FRESH download for {self.model_id}")
                fresh_metadata = [
                    "*.json", "*.txt", "*.md", "*.model", "*.tiktoken",
                    "tokenizer.*", "vocab.*", "merges.txt", "special_tokens_map.json",
                    "config.json", "generation_config.json", "tokenizer.json"
                ]
                try:
                    download_repo_files(
                        repo_id=self.model_id,
                        dest_dir=self.existing_dir,
                        token=token,
                        allow_patterns=fresh_metadata,
                        resume=False,
                        timeout_s=120,
                        max_retries=2,
                        progress_callback=progress_callback,
                        status_callback=status_callback,
                        should_cancel=lambda: should_cancel() or stall_detected.is_set(),
                        clean_locks=True,
                        force_fresh=False,
                        cache_dir=self.cache_dir
                    )
                    download_repo_files(
                        repo_id=self.model_id,
                        dest_dir=self.existing_dir,
                        token=token,
                        allow_patterns=self.allow_patterns,
                        resume=True,
                        timeout_s=900,
                        max_retries=2,
                        progress_callback=progress_callback,
                        status_callback=status_callback,
                        should_cancel=lambda: should_cancel() or stall_detected.is_set(),
                        clean_locks=True,
                        force_fresh=False,
                        cache_dir=self.cache_dir
                    )
                except Exception as download_error:
                    if stall_detected.is_set():
                        # Stall detected - propagate as error so UI can prompt for fallback
                        watchdog_stop.set()
                        raise RuntimeError(f"Download stalled: no progress for 15+ minutes. The download may be stuck due to network issues or server problems.") from download_error
                    else:
                        raise
                finally:
                    watchdog_stop.set()
            else:
                # Try repair with existing files first
                try:
                    # Check if metadata exists, download if missing
                    has_metadata = False
                    try:
                        for pattern in metadata_patterns:
                            import fnmatch
                            for file in self.existing_dir.rglob("*"):
                                if fnmatch.fnmatch(file.name, pattern):
                                    has_metadata = True
                                    break
                            if has_metadata:
                                break
                    except Exception:
                        pass
                    
                    if not has_metadata:
                        # Preflight: download metadata first
                        download_repo_files(
                            repo_id=self.model_id,
                            dest_dir=self.existing_dir,
                            token=token,
                            allow_patterns=metadata_patterns,
                            resume=False,
                            timeout_s=120,
                            max_retries=2,
                            progress_callback=progress_callback,
                            status_callback=status_callback,
                            should_cancel=should_cancel,
                            clean_locks=True,
                            cache_dir=self.cache_dir
                        )
                    
                    # Download remaining files in resume mode (or only allow_patterns if set).
                    try:
                        download_repo_files(
                            repo_id=self.model_id,
                            dest_dir=self.existing_dir,
                            token=token,
                            allow_patterns=self.allow_patterns,  # None = everything; else e.g. single GGUF
                            resume=True,  # Keep completed files and continue partial downloads
                            timeout_s=900,  # 15 min per file max for responsiveness
                            max_retries=2,
                            progress_callback=progress_callback,
                            status_callback=status_callback,
                            should_cancel=lambda: should_cancel() or stall_detected.is_set(),
                            clean_locks=True,  # Clean lock files while preserving resumable data
                            cache_dir=self.cache_dir
                        )
                    except Exception as download_error:
                        if stall_detected.is_set():
                            # Stall detected - propagate as error so UI can prompt for fallback
                            watchdog_stop.set()
                            raise RuntimeError(f"Download stalled: no progress for 15+ minutes. The download may be stuck due to network issues or server problems.") from download_error
                        else:
                            raise
                    finally:
                        watchdog_stop.set()
                    
                except Exception as first_error:
                    # Resume failed - propagate error to UI so it can ask user
                    import logging
                    logging.warning(f"Resume repair failed: {first_error}")
                    raise  # Let UI handle the fallback decision
            
            # Ensure watchdog is stopped
            watchdog_stop.set()
            
            self.progress.emit(100)
            self.finished.emit(str(self.existing_dir))
            
        except Exception as e:
            # Ensure watchdog is stopped even on error
            try:
                watchdog_stop.set()
            except Exception:
                pass
            self.error.emit(str(e))


class DownloadThread(QThread):
    """Thread for downloading models without freezing UI"""
    progress = Signal(int)  # 0-100
    finished = Signal(str)  # destination path
    error = Signal(str)     # error message
    status = Signal(str)    # current status message (e.g., "Downloading model-00035-of-00061.bin (35/61)")
    
    def __init__(
        self,
        model_id: str,
        target_dir: Path,
        cache_dir: Optional[Path] = None,
        token: Optional[str] = None,
        allow_patterns: Optional[List[str]] = None,
    ):
        super().__init__()
        self.model_id = model_id
        self.target_dir = target_dir
        self.cache_dir = cache_dir
        self.token = token
        self.allow_patterns = allow_patterns
        import threading
        self._stop_requested = threading.Event()
    
    def request_stop(self) -> None:
        """Request cooperative stop (best-effort)."""
        try:
            self.requestInterruption()
        except Exception:
            pass
        try:
            self._stop_requested.set()
        except Exception:
            pass
    
    def run(self):
        try:
            import os
            import time
            from core.model_file_utils import download_repo_files
            import logging
            logger = logging.getLogger(__name__)
            
            # Use token passed from main thread (env + QSettings + cached), else env fallback
            token = self.token
            if not token:
                token = (
                    os.getenv("HF_TOKEN")
                    or os.getenv("HUGGINGFACE_HUB_TOKEN")
                    or os.getenv("HUGGINGFACEHUB_API_TOKEN")
                )
            
            # Convert model ID to directory name (e.g., unsloth/model -> unsloth__model)
            model_slug = self.model_id.replace("/", "__")
            dest = self.target_dir / model_slug
            
            # Progress callback for real-time updates
            current_file_status = "Preparing download..."
            last_progress_bytes = 0
            last_progress_ts = 0.0
            def progress_callback(bytes_done: int, bytes_total: int):
                nonlocal last_progress_bytes, last_progress_ts
                now_ts = time.time()
                speed_suffix = ""
                if last_progress_ts > 0 and bytes_done >= last_progress_bytes:
                    dt = max(1e-6, now_ts - last_progress_ts)
                    bps = (bytes_done - last_progress_bytes) / dt
                    if bps > 0:
                        speed_suffix = f" | {bps / (1024 * 1024):.1f} MB/s"
                last_progress_bytes = max(last_progress_bytes, bytes_done)
                last_progress_ts = now_ts
                if bytes_total > 0 and bytes_total >= bytes_done:
                    percent = int((bytes_done / bytes_total) * 100)
                    # Allow 100% when bytes_done >= bytes_total (download complete)
                    if bytes_done >= bytes_total:
                        percent = 100
                    elif bytes_done > 0:
                        percent = max(1, min(percent, 99))  # Clamp 1-99% during download (allow 0% at start)
                    else:
                        percent = 0
                    self.progress.emit(percent)
                    done_gb = bytes_done / (1024 ** 3)
                    total_gb = bytes_total / (1024 ** 3)
                    self.status.emit(f"{current_file_status}  |  {done_gb:.2f}/{total_gb:.2f} GB ({percent}%){speed_suffix}")
                else:
                    # Unknown total - emit based on bytes downloaded (rough estimate)
                    # ~1% per 50MB, start from 0%
                    if bytes_done > 0:
                        estimated_percent = min(int(bytes_done / (50 * 1024 * 1024)), 99)
                        self.progress.emit(max(1, estimated_percent))
                        done_gb = bytes_done / (1024 ** 3)
                        self.status.emit(f"{current_file_status}  |  {done_gb:.2f} GB downloaded{speed_suffix}")
                    else:
                        self.progress.emit(0)
            
            should_cancel = lambda: self._stop_requested.is_set() or self.isInterruptionRequested()
            
            # Status callback to show current file being downloaded
            def status_callback(filename: str, file_idx: int, total_files: int, attempt: int):
                import logging
                logger = logging.getLogger(__name__)
                status_msg = f"Downloading {filename} ({file_idx}/{total_files})"
                if attempt > 1:
                    status_msg += f" - attempt {attempt}"
                logger.info(status_msg)
                nonlocal current_file_status
                current_file_status = status_msg
                # Emit status signal for UI display
                self.status.emit(status_msg)
            
            # Start with metadata-only preflight
            self.progress.emit(1)
            self.status.emit("Phase 1: downloading metadata (config, tokenizer, etc.)...")
            metadata_patterns = [
                "*.json", "*.txt", "*.md", "*.model", "*.tiktoken",
                "tokenizer.*", "vocab.*", "merges.txt", "special_tokens_map.json",
                "config.json", "generation_config.json", "tokenizer.json"
            ]
            
            # Preflight: download metadata first
            download_repo_files(
                repo_id=self.model_id,
                dest_dir=dest,
                token=token,
                allow_patterns=metadata_patterns,
                resume=False,
                timeout_s=120,
                max_retries=2,
                progress_callback=progress_callback,
                status_callback=status_callback,
                should_cancel=should_cancel,
                cache_dir=self.cache_dir
            )
            
            def _has_real_files(root: Path) -> bool:
                # Fast early-exit scan (avoid rglob on huge models)
                try:
                    stack = [root]
                    while stack:
                        d = stack.pop()
                        try:
                            with os.scandir(d) as it:
                                for entry in it:
                                    name = entry.name
                                    if name.startswith(".") or name == "__pycache__":
                                        continue
                                    if entry.is_file():
                                        if name.endswith(".lock") or name.endswith(".incomplete") or name == ".download_in_progress":
                                            continue
                                        return True
                                    if entry.is_dir():
                                        stack.append(Path(entry.path))
                        except Exception:
                            continue
                except Exception:
                    return False
                return False

            # Verify preflight created files (fast)
            any_files = _has_real_files(dest)
            if not any_files:
                raise RuntimeError(
                    f"Download produced no files after metadata preflight in {dest}. "
                    "This usually indicates a stalled connection, blocked download, or authentication issue."
                )
            
            # Download all remaining files (or selected GGUF variants only)
            if self.allow_patterns:
                self.status.emit(f"Phase 2: downloading selected weights ({len(self.allow_patterns)} file(s))...")
            else:
                self.status.emit("Phase 2: downloading weights and remaining files...")
            download_repo_files(
                repo_id=self.model_id,
                dest_dir=dest,
                token=token,
                allow_patterns=self.allow_patterns,  # None = everything
                resume=True,  # Skip files that already exist
                timeout_s=900,  # 15 min per file max for responsiveness
                max_retries=2,
                progress_callback=progress_callback,
                status_callback=status_callback,
                should_cancel=should_cancel,
                cache_dir=self.cache_dir
            )
            
            # Final verification (fast)
            if not _has_real_files(dest):
                raise RuntimeError(
                    f"Download completed but no files found in {dest}. "
                    "The download may have failed silently or files were saved to a different location."
                )
            logger.info(f"✓ Download complete: files present in {dest}")
            
            self.progress.emit(100)
            self.finished.emit(str(dest))
            
        except Exception as e:
            self.error.emit(str(e))


class PackageCard(QFrame):
    """Modern, polished card widget for displaying a package with version info and status."""
    clicked = Signal(str)  # Emits package name when clicked
    checkbox_toggled = Signal(str, bool)  # Emits (package_name, checked) when checkbox toggled
    
    def __init__(self, pkg_name, required_version, installed_version, is_installed, status, status_color, status_text, description, needs_attention=False, parent=None, is_loading=False):
        super().__init__(parent)
        self.pkg_name = pkg_name
        self.required_version = required_version
        self.installed_version = installed_version
        self.is_installed = is_installed
        self.status_text = status_text
        self.status_color = status_color
        self.description = description
        self.needs_attention = needs_attention
        self.is_loading = is_loading
        
        self.setFrameShape(QFrame.NoFrame)
        self.setMinimumHeight(140)
        self.setMaximumHeight(250)
        self.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Minimum)
        self.setCursor(Qt.PointingHandCursor)
        self._setup_style(False, needs_attention)
        
        layout = QVBoxLayout(self)
        layout.setSpacing(8)
        layout.setContentsMargins(18, 16, 18, 16)
        
        # Header: Checkbox + Name + Status badge
        header = QHBoxLayout()
        header.setSpacing(12)
        
        # Checkbox for selection (show for all packages so user can select any)
        self.checkbox = QCheckBox(self)
        # Auto-check packages that need attention
        if needs_attention:
            self.checkbox.setChecked(True)
        
        # Create a custom checkbox with green background
        self.checkbox.setStyleSheet("""
            QCheckBox {
                spacing: 8px;
            }
            QCheckBox::indicator {
                width: 22px;
                height: 22px;
                border: 2px solid #667eea;
                border-radius: 4px;
                background: transparent;
            }
            QCheckBox::indicator:checked {
                background: #4caf50;
                border: 2px solid #4caf50;
            }
            QCheckBox::indicator:hover {
                border: 2px solid #8b9aff;
            }
            QCheckBox::indicator:checked:hover {
                background: #66bb6a;
                border: 2px solid #66bb6a;
            }
        """)
        
        # Override paintEvent to draw the checkmark directly on the indicator
        original_paint = self.checkbox.paintEvent
        
        def paint_with_checkmark(event):
            # Call original paint to draw the checkbox and indicator background
            original_paint(event)
            
            if self.checkbox.isChecked():
                # Get the style option to find indicator position
                opt = QStyleOptionButton()
                self.checkbox.initStyleOption(opt)
                
                # Get indicator rectangle from style
                indicator_rect = self.checkbox.style().subElementRect(
                    QStyle.SubElement.SE_CheckBoxIndicator,
                    opt,
                    self.checkbox
                )
                
                if indicator_rect.isValid():
                    painter = QPainter(self.checkbox)
                    painter.setRenderHint(QPainter.Antialiasing)
                    
                    # Draw white checkmark
                    pen = QPen(QColor("white"))
                    pen.setWidth(2)
                    pen.setCapStyle(Qt.PenCapStyle.RoundCap)
                    pen.setJoinStyle(Qt.PenJoinStyle.RoundJoin)
                    painter.setPen(pen)
                    
                    # Draw checkmark: two lines forming a check
                    x, y, w, h = indicator_rect.x(), indicator_rect.y(), indicator_rect.width(), indicator_rect.height()
                    center_x, center_y = x + w // 2, y + h // 2
                    painter.drawLine(
                        QPointF(center_x - 5, center_y),
                        QPointF(center_x - 1, center_y + 4)
                    )
                    painter.drawLine(
                        QPointF(center_x - 1, center_y + 4),
                        QPointF(center_x + 5, center_y - 4)
                    )
                    
                    painter.end()
        
        self.checkbox.paintEvent = paint_with_checkmark
        
        def on_checkbox_changed(state):
            checked = (state == Qt.CheckState.Checked)
            self.checkbox_toggled.emit(self.pkg_name, checked)
            self.clicked.emit(self.pkg_name)
            self.checkbox.update()
        
        self.checkbox.stateChanged.connect(on_checkbox_changed)
        self.checkbox.mousePressEvent = lambda e: QCheckBox.mousePressEvent(self.checkbox, e)
        header.addWidget(self.checkbox)
        
        name_label = QLabel(pkg_name, self)
        name_label.setWordWrap(True)
        name_label.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Preferred)
        name_label.setStyleSheet("""
            font-size: 15pt;
            font-weight: 700;
            color: #ffffff;
            background: transparent;
            letter-spacing: 0.5px;
        """)
        header.addWidget(name_label, 1)
        header.addStretch()

        # Status badge with rounded background
        self.status_badge = QLabel(status_text, self)
        if is_loading:
            self.status_badge.setText("CHECKING...")
            self.status_badge.setStyleSheet("""
                background: rgba(102, 126, 234, 0.1);
                color: #667eea;
                padding: 4px 12px;
                border-radius: 12px;
                font-size: 9pt;
                font-weight: 600;
                border: 1px solid rgba(102, 126, 234, 0.3);
            """)
        else:
            self.status_badge.setStyleSheet(f"""
                background: {status_color}33;
                color: {status_color};
                padding: 4px 12px;
                border-radius: 12px;
                font-size: 9pt;
                font-weight: 600;
                border: 1px solid {status_color}66;
            """)
        header.addWidget(self.status_badge)
        layout.addLayout(header)
        
        # Version info - vertical layout for proper wrapping
        self.inst_label = QLabel(self)
        self.inst_label.setWordWrap(True)
        if is_loading:
            self.inst_label.setText("Checking installation...")
            self.inst_label.setStyleSheet("color: #667eea; font-size: 10pt; font-style: italic; background: transparent;")
        elif installed_version:
            self.inst_label.setText(f"Installed: {installed_version}")
            self.inst_label.setStyleSheet(f"color: {status_color}; font-size: 10pt; font-weight: 500; background: transparent;")
        else:
            self.inst_label.setText("Not installed")
            self.inst_label.setStyleSheet("color: #888; font-size: 10pt; background: transparent;")
        layout.addWidget(self.inst_label)
        
        if required_version:
            self.req_label = QLabel(f"Required: {required_version}", self)
            self.req_label.setWordWrap(True)
            self.req_label.setStyleSheet("color: #aaa; font-size: 9pt; background: transparent;")
            layout.addWidget(self.req_label)

        # Description
        if description:
            desc = QLabel(description, self)
            desc.setWordWrap(True)
            desc.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Preferred)
            desc.setStyleSheet("""
                color: #b0b0b0; 
                font-size: 10pt; 
                background: transparent;
                line-height: 1.4;
                margin-top: 4px;
            """)
            layout.addWidget(desc)
        
        layout.addStretch()

    def update_status(self, inst_ver, is_installed, is_functional, version_mismatch, status_text, status_color, needs_attention):
        """Update the card with fresh status info from background thread."""
        self.installed_version = inst_ver
        self.is_installed = is_installed
        self.status_text = status_text
        self.status_color = status_color
        self.needs_attention = needs_attention
        self.is_loading = False
        
        # Update badge
        self.status_badge.setText(status_text)
        self.status_badge.setStyleSheet(f"""
            background: {status_color}33;
            color: {status_color};
            padding: 4px 12px;
            border-radius: 12px;
            font-size: 9pt;
            font-weight: 600;
            border: 1px solid {status_color}66;
        """)
        
        # Update installed label
        if inst_ver:
            self.inst_label.setText(f"Installed: {inst_ver}")
            self.inst_label.setStyleSheet(f"color: {status_color}; font-size: 10pt; font-weight: 500; background: transparent;")
        else:
            self.inst_label.setText("Not installed")
            self.inst_label.setStyleSheet("color: #f44336; font-size: 10pt; background: transparent;")
        
        # Update checkbox (auto-check if attention needed)
        if needs_attention:
            self.checkbox.setChecked(True)
            
        # Update overall style
        self._setup_style(False, needs_attention)
        self.update()

    def _setup_style(self, selected=False, needs_attention=False):
        if selected:
            border_color = "#f44336" if needs_attention else self.status_color
            self.setStyleSheet(f"""
                PackageCard {{
                    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
                        stop:0 rgba(102, 126, 234, 0.15), stop:1 rgba(118, 75, 162, 0.15));
                    border: 2px solid {border_color};
                    border-radius: 12px;
                    padding: 0px;
                }}
            """)
        else:
            if needs_attention:
                # Red border for packages needing attention
                self.setStyleSheet(f"""
                    PackageCard {{
                        background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
                            stop:0 rgba(40, 40, 55, 0.6), stop:1 rgba(25, 25, 35, 0.6));
                        border: 3px solid #f44336;
                        border-radius: 12px;
                        padding: 0px;
                    }}
                    PackageCard:hover {{
                        background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
                            stop:0 rgba(60, 60, 80, 0.8), stop:1 rgba(40, 40, 55, 0.8));
                        border: 3px solid #f44336;
                    }}
                """)
            else:
                self.setStyleSheet(f"""
                    PackageCard {{
                        background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
                            stop:0 rgba(40, 40, 55, 0.6), stop:1 rgba(25, 25, 35, 0.6));
                        border: 1px solid rgba(102, 126, 234, 0.2);
                        border-radius: 12px;
                        padding: 0px;
                    }}
                    PackageCard:hover {{
                        background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
                            stop:0 rgba(60, 60, 80, 0.8), stop:1 rgba(40, 40, 55, 0.8));
                        border: 1px solid rgba(102, 126, 234, 0.5);
                    }}
                """)

    def mousePressEvent(self, event: QMouseEvent):
        if event.button() == Qt.LeftButton:
            # Don't trigger card click if clicking on checkbox
            if self.checkbox.geometry().contains(event.pos()):
                return
            self.clicked.emit(self.pkg_name)
        super().mousePressEvent(event)

    def set_selected(self, selected: bool):
        self._setup_style(selected, self.needs_attention)
    
    def is_checked(self) -> bool:
        """Check if the package checkbox is checked"""
        return self.checkbox.isChecked()
    
    def set_checked(self, checked: bool):
        """Set the checkbox state"""
        self.checkbox.setChecked(checked)


