class RequirementCheckThread(QThread):
    """Background thread to check all package versions at once without freezing UI."""
    # signal: (pkg_name, inst_ver, is_installed, is_functional, version_mismatch, status_text, status_color, needs_attention)
    package_checked = Signal(str, str, bool, bool, bool, str, str, bool)
    all_finished = Signal()
    
    def __init__(self, target_python, required_packages, check_functional_func, check_version_mismatch_func):
        super().__init__()
        self.target_python = target_python
        self.required_packages = required_packages
        self.check_functional_func = check_functional_func
        self.check_version_mismatch_func = check_version_mismatch_func
        self._is_running = True

    def run(self):
        if not self.target_python:
            self.all_finished.emit()
            return

        import subprocess
        import json
        
        # 1. Get all installed versions in one bulk call
        installed_versions = {}
        try:
            result = subprocess.run(
                [self.target_python, "-m", "pip", "list", "--format", "json"],
                capture_output=True,
                text=True,
                timeout=15,
                **SUBPROCESS_FLAGS
            )
            if result.returncode == 0:
                pkgs = json.loads(result.stdout)
                installed_versions = {pkg['name'].lower(): pkg['version'] for pkg in pkgs}
        except Exception as e:
            print(f"[RequirementCheckThread] Bulk check failed: {e}")

        # 2. Process each required package
        for pkg_name, req_ver in self.required_packages.items():
            if not self._is_running:
                break
                
            # Get installed version from our bulk dict
            inst_ver = None
            search_names = [pkg_name.lower()]
            if pkg_name in ["triton", "triton-windows"]:
                search_names = ["triton-windows", "triton"]
            elif "_" in pkg_name or "-" in pkg_name:
                search_names.append(pkg_name.lower().replace("_", "-"))
                search_names.append(pkg_name.lower().replace("-", "_"))
            
            for name in search_names:
                if name in installed_versions:
                    inst_ver = installed_versions[name]
                    break
            
            is_installed = bool(inst_ver)
            
            # Use provided funcs for functional/mismatch checks
            # Note: functional check might still run a small subprocess for some pkgs
            is_functional = self.check_functional_func(pkg_name, python_exe=self.target_python) if is_installed else True
            version_mismatch = False
            if is_installed and req_ver and req_ver != "Binary (wheel)":
                version_mismatch = self.check_version_mismatch_func(pkg_name, inst_ver, req_ver)
            
            # Determine status
            needs_attention = False
            if is_installed:
                if not is_functional:
                    status_text = "BROKEN"
                    status_color = "#f44336"
                    needs_attention = True
                elif version_mismatch:
                    status_text = "WRONG VERSION"
                    status_color = "#ff9800"
                    needs_attention = True
                else:
                    status_text = "OK"
                    status_color = "#4CAF50"
            else:
                if pkg_name in ["causal_conv1d", "mamba_ssm"]:
                    status_text = "MISSING"
                    status_color = "#ff9800"
                    needs_attention = True
                elif pkg_name in ["triton", "triton-windows"] and sys.platform == "win32":
                    status_text = "OPTIONAL"
                    status_color = "#9e9e9e"
                else:
                    status_text = "MISSING"
                    status_color = "#f44336"
                    needs_attention = True
            
            self.package_checked.emit(
                pkg_name, 
                inst_ver or "", 
                is_installed, 
                is_functional, 
                version_mismatch, 
                status_text, 
                status_color, 
                needs_attention
            )
            
        self.all_finished.emit()

    def stop(self):
        self._is_running = False


class ModelStatsWorker(QThread):
    """Background worker to fetch model stats (downloads/likes) without blocking UI"""
    stats_ready = Signal(dict)  # Emits {model_id: {downloads: int|None, likes: int|None}}
    
    def __init__(self, model_ids):
        super().__init__()
        self.model_ids = model_ids
    
    def run(self):
        """Fetch stats for all model IDs (only fetch stale/missing, cache already applied in UI)"""
        results = {}
        from core.models import fetch_model_stats, get_cached_model_stats
        
        for model_id in self.model_ids:
            # Only fetch if cache is stale or missing
            cached = get_cached_model_stats(model_id)
            if cached:
                # Cache is fresh, skip (already shown in UI)
                continue
            
            # Fetch from API
            stats = fetch_model_stats(model_id)
            if stats:
                results[model_id] = stats
            else:
                # Even on failure, store None to avoid repeated requests
                results[model_id] = {"downloads": None, "likes": None}
        
        # Only emit if we have new results
        if results:
            self.stats_ready.emit(results)


class ModelDetailsWorker(QObject):
    """Worker class for fetching model details in background thread with thread-safe signals"""
    details_ready = Signal(dict)  # Emits model details dict
    error_occurred = Signal(str)  # Emits error message
    retrying = Signal(int, int)  # Emits (current_attempt, max_attempts) for retry feedback
    
    def __init__(self, model_id: str, max_retries: int = 2, token: Optional[str] = None):
        super().__init__()
        self.model_id = model_id
        self.max_retries = max_retries
        self.token = token
    
    def fetch(self):
        """Fetch model details with retry logic - runs in background thread"""
        import time
        
        for attempt in range(1, self.max_retries + 1):
            try:
                from core.models import get_model_details
                details = get_model_details(self.model_id, token=self.token)
                self.details_ready.emit(details)
                return  # Success, exit retry loop
            except Exception as e:
                error_msg = str(e)
                
                # Don't retry on certain errors (e.g., model not found, authentication)
                if any(skip in error_msg.lower() for skip in ["not found", "unauthorized", "forbidden", "not available"]):
                    self.error_occurred.emit(error_msg)
                    return
                
                # If this is the last attempt, emit error
                if attempt >= self.max_retries:
                    self.error_occurred.emit(error_msg)
                    return
                
                # Otherwise, retry with exponential backoff
                self.retrying.emit(attempt, self.max_retries)
                wait_time = min(2 ** attempt, 5)  # 2s, 4s, max 5s
                time.sleep(wait_time)


class MainWindow(QMainWindow):
    def __init__(self, splash: SplashScreen = None) -> None:
        super().__init__()
        # Remove native Windows title bar but keep window resizable
        self.setWindowFlags(Qt.FramelessWindowHint | Qt.Window | Qt.WindowMinMaxButtonsHint)
        self.setWindowTitle(APP_TITLE)
        self.resize(1400, 900)
        self.setMinimumSize(800, 600)  # Allow resizing with reasonable minimum

        self.root = get_app_root()
        # Central HF cache directory (keeps locks out of model folders)
        self.hf_cache_dir = self.root / "hf_cache"
        self.hf_cache_dir.mkdir(exist_ok=True)
        self.dark_mode = True  # Start in dark mode
        self.color_theme = "purple"  # Default color theme
        
        # Store references to widgets with hardcoded colors for theme updates
        self.themed_widgets = {
            "frames": [],
            "labels": [],
            "buttons": [],
            "containers": []
        }
        
        # Window dragging and resizing support
        self.drag_position = None
        self.resize_edge = None  # Track which edge is being resized
        self.resize_start_pos = None
        self.resize_start_geometry = None
        self.edge_margin = 8  # Pixels from edge to trigger resize (increased for easier detection)
        self.cursor_override_active = False  # Track if we have an override cursor active
        self.current_cursor_shape = None  # Track current cursor shape to avoid unnecessary changes
        self._drag_disabled = False  # Flag to disable drag when wrapped in HybridFrameWindow
        
        # Model integrity checker
        if splash:
            splash.update_progress(5, "Initializing model checker", "")
        self.model_checker = ModelIntegrityChecker()
        
        # State store for runtime state (onboarding, models, servers)
        from core.state_store import get_state_store
        self.state_store = get_state_store()
        
        # Environment manager for per-model isolated environments
        self.env_manager = EnvironmentManager(self.root)
        self.python_runtime_manager = PythonRuntimeManager(self.root)

        # App shutdown coordination (stop server first, then exit)
        self._shutdown_in_progress = False
        self._shutdown_force_timer = None

        # IMPORTANT:
        # - If splash is provided (slow path): do full detection synchronously with UI updates.
        # - If splash is None (fast path): do NOT run detection here (it can take minutes and freeze at 50%).
        #   Instead, use lightweight placeholders and refresh after `_background_system_check()` completes.
        if splash:
            splash.update_progress(10, "Detecting system", "")
            splash.set_checking("Python")

            detector = SystemDetector()
            self.system_info = {}

            # Detect Python
            splash.set_checking("Python")
            python_info = detector.detect_python()
            self.system_info["python"] = python_info
            ver = python_info.get("version", "Unknown")
            splash.set_result("Python", f"{ver}", python_info.get("found", False))
            splash.update_progress(20, "Python detected", "")

            # Detect CUDA/GPUs
            splash.set_checking("CUDA & GPUs")
            cuda_info = detector.detect_cuda()
            self.system_info["cuda"] = cuda_info
            if cuda_info.get("found"):
                gpus = cuda_info.get("gpus", [])
                for idx, gpu in enumerate(gpus):
                    gpu_name = gpu.get("name", f"GPU {idx}")
                    gpu_mem = gpu.get("memory", "N/A")
                    splash.set_result(f"GPU {idx}", f"{gpu_name} ({gpu_mem})", True)
                splash.update_progress(40, f"CUDA v{cuda_info.get('version', 'N/A')}", "")
            else:
                splash.set_result("CUDA & GPUs", "Not detected (CPU mode)", False)
                splash.update_progress(40, "No CUDA", "")

            # Detect PyTorch
            splash.set_checking("PyTorch")
            pytorch_info = detector.detect_pytorch()
            self.system_info["pytorch"] = pytorch_info
            if pytorch_info.get("found"):
                ver = pytorch_info.get("version", "Unknown")
                cuda = " + CUDA" if pytorch_info.get("cuda_available") else " (CPU only)"
                splash.set_result("PyTorch", f"v{ver}{cuda}", True)
            else:
                splash.set_result("PyTorch", "Not installed", False)
            splash.update_progress(60, "PyTorch detected", "")

            # Detect Hardware
            splash.set_checking("Hardware (CPU/RAM)")
            hardware_info = detector.detect_hardware()
            self.system_info["hardware"] = hardware_info
            cpu_name = hardware_info.get("cpu_name", "Unknown CPU")
            if len(cpu_name) > 40:
                cpu_name = cpu_name[:37] + "..."
            cpu_cores = hardware_info.get("cpu", {}).get("cores", "?")
            ram = hardware_info.get("ram_gb", 0)
            splash.set_result("CPU", f"{cpu_name} ({cpu_cores} cores)", True)
            splash.set_result("RAM", f"{ram:.1f} GB", True)
            splash.update_progress(80, "Hardware detected", "")

            # Store SmartInstaller instance for reuse
            splash.set_checking("Installer state")
            self.installer = SmartInstaller()
            splash.set_result("Installer", "Ready", True)
            splash.update_progress(90, "Building UI", "")
        else:
            # Fast init: placeholders only (real detection happens in `_background_system_check`)
            pyver = ".".join(map(str, sys.version_info[:3]))
            self.system_info = {
                "python": {"found": True, "version": pyver},
                "cuda": {"found": False, "gpus": [], "driver_version": None, "version": None},
                "pytorch": {"found": False, "cuda_available": False, "version": None, "cuda_version": None},
                "hardware": {"cpu_name": "Unknown", "cpu": {"cores": 0}, "ram_gb": 0},
            }
            self.installer = SmartInstaller()

        # Background detection state (fast path uses this to populate real values)
        self._bg_detect_thread: SystemDetectThread | None = None
        self._bg_detect_started: bool = False
        self._home_tab_needs_update: bool = False
        self._rebuilding_home_tab: bool = False

        # Environment issue flag (option C: startup scan + model-load-triggered banner)
        self._forced_env_attention_msg: str | None = None
        self._startup_env_popup_shown: bool = False
        self._model_env_popup_shown: bool = False
        self._last_env_error_details: str | None = None
        
        # GPU VRAM detection and storage
        self.user_vram_gb = self._detect_gpu_vram()

        # Create a beautiful unified header
        header_widget = QFrame()
        header_widget.setFrameShape(QFrame.StyledPanel)
        header_widget.setMinimumHeight(80)
        # Header styling will be applied by theme system
        # Store header reference for dragging
        self.header_widget = header_widget
        # Make header draggable
        header_widget.mousePressEvent = lambda e: self._header_mouse_press(e)
        header_widget.mouseMoveEvent = lambda e: self._header_mouse_move(e)
        # Install event filter on header to catch top edge resize events
        header_widget.installEventFilter(self)
        
        # Use a 3-column grid so the title can be truly centered in the window.
        # We'll keep the left and right columns the same width at runtime.
        header_layout = QGridLayout(header_widget)
        # Increased right margin to 50px to account for frame extension (75px) + padding
        header_layout.setContentsMargins(20, 10, 50, 10)
        header_layout.setHorizontalSpacing(6)
        header_layout.setVerticalSpacing(0)
        header_layout.setColumnStretch(0, 0)
        header_layout.setColumnStretch(1, 1)
        header_layout.setColumnStretch(2, 0)
        
        # Left: Theme controls container
        theme_container = QWidget()
        theme_container.setStyleSheet("background: transparent;")
        theme_layout = QHBoxLayout(theme_container)
        theme_layout.setContentsMargins(0, 0, 0, 0)
        theme_layout.setSpacing(0)  # No spacing - attach theme button to color selector
        
        # Dark/Light mode toggle button (same size as color selector, icon on top, text below)
        theme_btn_container = QWidget()
        theme_btn_container.setFixedSize(70, 50)
        theme_btn_container.setStyleSheet("""
            QWidget {
                background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
                    stop:0 rgba(60, 60, 80, 0.8), stop:1 rgba(40, 40, 60, 0.8));
                border: 1px solid rgba(255, 255, 255, 0.2);
                border-radius: 6px;
            }
        """)
        theme_btn_layout = QVBoxLayout(theme_btn_container)
        theme_btn_layout.setContentsMargins(4, 4, 4, 4)
        theme_btn_layout.setSpacing(2)
        theme_btn_layout.setAlignment(Qt.AlignCenter)
        
        # Icon label (bigger)
        theme_icon = QLabel("🌙")
        theme_icon.setAlignment(Qt.AlignCenter)
        theme_icon.setStyleSheet("""
            QLabel {
                background: transparent;
                color: white;
                font-size: 20pt;
                border: none;
            }
        """)
        theme_btn_layout.addWidget(theme_icon)
        
        # Text label
        theme_text = QLabel("Dark")
        theme_text.setAlignment(Qt.AlignCenter)
        theme_text.setStyleSheet("""
            QLabel {
                background: transparent;
                color: white;
                font-size: 9pt;
                font-weight: bold;
                border: none;
            }
        """)
        theme_btn_layout.addWidget(theme_text)
        
        # Make the container clickable
        theme_btn_container.mousePressEvent = lambda e: self._toggle_theme()
        theme_btn_container.setCursor(QCursor(Qt.PointingHandCursor))
        
        # Store references for updates
        self.theme_btn_container = theme_btn_container
        self.theme_icon = theme_icon
        self.theme_text = theme_text
        theme_layout.addWidget(theme_btn_container)
        
        # Color theme selector (2 rows x 3 columns)
        color_selector = QWidget()
        color_selector.setFixedSize(70, 50)
        color_selector.setStyleSheet("background: rgba(40, 40, 60, 0.4); border: 1px solid rgba(255, 255, 255, 0.2); border-radius: 6px;")
        color_layout = QVBoxLayout(color_selector)
        color_layout.setContentsMargins(4, 4, 4, 4)
        color_layout.setSpacing(3)
        
        # Row 1: Purple, Yellow, Red
        row1 = QHBoxLayout()
        row1.setContentsMargins(0, 0, 0, 0)
        row1.setSpacing(3)
        
        # Row 2: Navy, Green, Gray
        row2 = QHBoxLayout()
        row2.setContentsMargins(0, 0, 0, 0)
        row2.setSpacing(3)
        
        color_themes = ["purple", "yellow", "red", "navy", "green", "gray"]
        color_colors = {
            "purple": "#667eea",
            "yellow": "#fbbf24",
            "red": "#ef4444",
            "navy": "#3b82f6",
            "green": "#10b981",
            "gray": "#6b7280"
        }
        
        self.color_buttons = {}
        for i, theme_name in enumerate(color_themes):
            color_btn = QPushButton()
            color_btn.setFixedSize(18, 18)
            color_btn.setCheckable(True)
            color_btn.setStyleSheet(f"""
                QPushButton {{
                    background-color: {color_colors[theme_name]};
                    border: 2px solid rgba(255, 255, 255, 0.4);
                    border-radius: 3px;
                }}
                QPushButton:checked {{
                    border: 3px solid white;
                }}
                QPushButton:hover {{
                    border: 2px solid rgba(255, 255, 255, 0.8);
                }}
            """)
            color_btn.clicked.connect(lambda checked, t=theme_name: self._set_color_theme(t))
            if theme_name == "purple":
                color_btn.setChecked(True)
            self.color_buttons[theme_name] = color_btn
            
            # Add to appropriate row
            if i < 3:
                row1.addWidget(color_btn)
            else:
                row2.addWidget(color_btn)
        
        color_layout.addLayout(row1)
        color_layout.addLayout(row2)

        theme_layout.addWidget(color_selector)

        # ---- Advanced toggle (sits next to the color selector) -------
        # Real QPushButton.clicked, not mousePressEvent on a custom layout.
        # Why: the previous version used a QWidget with QLabel children and
        # `mousePressEvent = lambda ...`. The header_widget had its own
        # event filter (for window-drag), and QLabel children intercepted
        # the press before the container's override ran — net effect was
        # "the click does nothing". A QPushButton emits ``clicked`` via Qt's
        # signal/slot mechanism, which is unaffected by parent event filters
        # or child label propagation, so it just works.
        advanced_btn = QPushButton()
        advanced_btn.setFixedSize(70, 50)
        advanced_btn.setCursor(QCursor(Qt.PointingHandCursor))
        advanced_btn.setCheckable(True)
        # Two-line label inside the button via rich Unicode (Qt renders
        # text on QPushButton in one line, but a vertical look comes
        # through fine with a tall font + a tiny gap).
        advanced_btn.setText("⚙\nAdvanced")
        advanced_btn.setStyleSheet("""
            QPushButton {
                background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
                    stop:0 rgba(60, 60, 80, 0.85), stop:1 rgba(40, 40, 60, 0.85));
                border: 1px solid rgba(255, 255, 255, 0.2);
                border-radius: 6px;
                color: white;
                font-size: 9pt;
                font-weight: bold;
                padding: 0;
                text-align: center;
            }
            QPushButton:hover {
                border: 1px solid rgba(255, 255, 255, 0.4);
            }
            QPushButton:checked {
                border: 1px solid #ffd080;
                background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
                    stop:0 rgba(80, 70, 50, 0.85), stop:1 rgba(60, 50, 30, 0.85));
            }
        """)
        advanced_btn.clicked.connect(self._toggle_advanced)
        self.advanced_btn = advanced_btn
        self._advanced_visible = False
        # 6px gap from the color selector — outside the stylesheet because
        # QPushButton stylesheet margins are unreliable on Windows.
        theme_layout.addSpacing(6)
        theme_layout.addWidget(advanced_btn)

        # ---- Group toggles in the header (matches Advanced style) -----
        # Previously these lived in the main navbar, taking up two slots
        # alongside their sub-tabs. Moving them next to Advanced
        # de-clutters the navbar and groups them with the OTHER toggle
        # that reveals additional sub-buttons. Same fixed HEIGHT (50px)
        # and same dark gradient + gold-bordered :checked state as
        # Advanced; width is allowed to grow with the label so labels
        # like "Fine Tuning" don't wrap or truncate.
        def _make_header_toggle(text: str) -> QPushButton:
            btn = QPushButton(text)
            btn.setFixedHeight(50)
            btn.setCursor(QCursor(Qt.PointingHandCursor))
            btn.setCheckable(True)
            btn.setStyleSheet("""
                QPushButton {
                    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
                        stop:0 rgba(60, 60, 80, 0.85), stop:1 rgba(40, 40, 60, 0.85));
                    border: 1px solid rgba(255, 255, 255, 0.2);
                    border-radius: 6px;
                    color: white;
                    font-size: 9pt;
                    font-weight: bold;
                    padding: 0 14px;
                    text-align: center;
                }
                QPushButton:hover {
                    border: 1px solid rgba(255, 255, 255, 0.4);
                }
                QPushButton:checked {
                    border: 1px solid #ffd080;
                    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
                        stop:0 rgba(80, 70, 50, 0.85), stop:1 rgba(60, 50, 30, 0.85));
                }
            """)
            return btn

        # 'Fine Tuning' — wrench glyph + label, two-line layout matching
        # the Advanced button. Height fixed (50), width auto-fits.
        self.finetuning_group_btn = _make_header_toggle("🛠\nFine Tuning")
        # 'Agentic Team' — masks emoji matches the legacy 🎭 used in the
        # navbar; the owl_agentic.png asset is reserved for the canvas
        # surface and intentionally NOT used here.
        self.agentic_group_btn = _make_header_toggle("🎭\nAgentic Team")
        # 'Gamify' — joypad glyph. Hosts the merged 3D playground that
        # combines the legacy Arena (under Test) and Characters pages.
        self.gamify_group_btn = _make_header_toggle("🎮\nGamify")

        theme_layout.addSpacing(4)
        theme_layout.addWidget(self.finetuning_group_btn)
        theme_layout.addSpacing(4)
        theme_layout.addWidget(self.agentic_group_btn)
        theme_layout.addSpacing(4)
        theme_layout.addWidget(self.gamify_group_btn)

        # Left column (theme controls)
        header_left = QWidget()
        header_left.setStyleSheet("background: transparent;")
        header_left_layout = QHBoxLayout(header_left)
        header_left_layout.setContentsMargins(0, 0, 0, 0)
        header_left_layout.setSpacing(0)
        header_left_layout.addWidget(theme_container)
        header_left_layout.addStretch(1)
        
        # Center: App title (transparent background)
        title_container = QWidget()
        title_container.setStyleSheet("background: transparent;")
        title_layout = QHBoxLayout(title_container)
        title_layout.setContentsMargins(0, 0, 0, 0)
        title_layout.setSpacing(12)
        title_layout.setAlignment(Qt.AlignCenter)
        
        # Title text
        title_label = QLabel(APP_TITLE)
        title_label.setAlignment(Qt.AlignCenter | Qt.AlignVCenter)
        title_label.setStyleSheet("""
            QLabel {
                background: transparent;
                color: white; 
                font-size: 24pt; 
                font-weight: bold;
                border: none;
                padding: 0px;
            }
        """)
        title_layout.addWidget(title_label)
        
        # Center column (title)
        header_layout.addWidget(title_container, 0, 1, Qt.AlignCenter)
        
        # Right: System info (compact)
        sys_info_widget = QWidget()
        sys_info_widget.setStyleSheet("background: transparent; border: none;")
        # The Servers line includes the prettified running-model name(s) —
        # e.g. "🟢 Servers: 1 (Gemma 4 E4B Instruct GGUF)" — which easily
        # runs 380–500 px. Without a minimum width the right column collapses
        # to the shortest label's sizeHint, clipping API/VRAM/Servers text
        # and leaving them looking blank.
        sys_info_widget.setMinimumWidth(520)
        sys_info_widget.setSizePolicy(QSizePolicy.Preferred, QSizePolicy.Preferred)
        sys_info_layout = QVBoxLayout(sys_info_widget)
        sys_info_layout.setContentsMargins(0, 0, 0, 0)
        sys_info_layout.setSpacing(4)
        
        # Runtime info (replaces static Python/PyTorch/RAM with live operational
        # state: which servers are up, the API key clients use, and the VRAM
        # each server is consuming). Populated by _update_header_runtime_info()
        # — fires on a 2-second QTimer, with VRAM queried on a worker thread.
        # Servers row: text label + tiny restart button (mini, inline-height).
        servers_row = QWidget(self)
        servers_row.setStyleSheet("background: transparent;")
        servers_row_layout = QHBoxLayout(servers_row)
        servers_row_layout.setContentsMargins(0, 0, 0, 0)
        servers_row_layout.setSpacing(6)
        servers_label = QLabel("🟢 Servers: …", servers_row)
        servers_label.setStyleSheet("color: white; font-size: 11pt; font-weight: bold; background: transparent;")
        servers_label.setToolTip("Models with an inference server currently running.")
        servers_label.setSizePolicy(QSizePolicy.MinimumExpanding, QSizePolicy.Preferred)
        servers_row_layout.addWidget(servers_label, 1)
        # Mini restart button — sized to the text line (≈16px) so the row
        # height doesn't grow. Hidden when no server is running.
        restart_btn = QPushButton("↻", servers_row)
        restart_btn.setFixedSize(18, 18)
        restart_btn.setCursor(Qt.PointingHandCursor)
        restart_btn.setToolTip("Restart running inference server(s).")
        restart_btn.setStyleSheet(
            "QPushButton { background: transparent; color: #ffd080; border: 1px solid rgba(255,208,128,0.55); "
            "border-radius: 4px; font-size: 11pt; font-weight: bold; padding: 0px; }"
            "QPushButton:hover { background: rgba(255,208,128,0.18); border-color: #ffd080; }"
            "QPushButton:pressed { background: rgba(255,208,128,0.30); }"
        )
        restart_btn.setVisible(False)
        restart_btn.clicked.connect(self._on_header_restart_clicked)
        servers_row_layout.addWidget(restart_btn, 0, Qt.AlignVCenter)
        servers_row.setMinimumWidth(520)
        sys_info_layout.addWidget(servers_row)
        self.header_servers_label = servers_label
        self.header_servers_restart_btn = restart_btn

        # API key row: clickable 🔑 icon + non-clickable text.
        # Splitting these prevents the "click anywhere" behaviour from
        # accidentally firing as the cursor passes over the wide label.
        apikey_row = QWidget(self)
        apikey_row.setStyleSheet("background: transparent;")
        apikey_row_layout = QHBoxLayout(apikey_row)
        apikey_row_layout.setContentsMargins(0, 0, 0, 0)
        apikey_row_layout.setSpacing(4)
        apikey_icon = QLabel("🔑", apikey_row)
        apikey_icon.setStyleSheet("color: white; font-size: 11pt; font-weight: bold; background: transparent;")
        apikey_icon.setCursor(Qt.PointingHandCursor)
        apikey_icon.setToolTip("Click to copy API key to clipboard.")
        apikey_text = QLabel("API key: owllm-local", apikey_row)
        apikey_text.setStyleSheet("color: white; font-size: 11pt; font-weight: bold; background: transparent;")
        apikey_text.setToolTip(
            "API key clients use to talk to OWLLM's OpenAI-compatible proxy at "
            "http://127.0.0.1:9999/v1."
        )
        apikey_row_layout.addWidget(apikey_icon, 0, Qt.AlignVCenter)
        apikey_row_layout.addWidget(apikey_text, 1, Qt.AlignVCenter)
        apikey_row.setMinimumWidth(520)
        def _copy_apikey(_event=None):
            try:
                QApplication.clipboard().setText("owllm-local")
                apikey_text.setText("API key: copied!")
                QTimer.singleShot(1200, lambda: apikey_text.setText("API key: owllm-local"))
            except Exception:
                pass
        apikey_icon.mousePressEvent = _copy_apikey
        sys_info_layout.addWidget(apikey_row)
        self.header_apikey_label = apikey_text

        vram_label = QLabel("💾 VRAM: …", self)
        vram_label.setStyleSheet("color: white; font-size: 11pt; font-weight: bold; background: transparent;")
        vram_label.setToolTip("Total GPU VRAM in use; per-server breakdown in tooltip when servers are running.")
        vram_label.setSizePolicy(QSizePolicy.MinimumExpanding, QSizePolicy.Preferred)
        vram_label.setMinimumWidth(520)
        sys_info_layout.addWidget(vram_label)
        self.header_vram_label = vram_label

        # Cached VRAM stats — populated by _vram_worker_run on a worker thread.
        self._vram_stats: dict = {"per_pid": {}, "totals": []}
        
        # Right column (system info + window buttons)
        header_right = QWidget()
        header_right.setStyleSheet("background: transparent;")
        header_right_layout = QHBoxLayout(header_right)
        header_right_layout.setContentsMargins(0, 0, 0, 0)
        header_right_layout.setSpacing(6)
        
        # Fullscreen button (⛶) in top right
        fullscreen_btn = QPushButton("⛶")
        fullscreen_btn.setFixedSize(30, 30)
        fullscreen_btn.setStyleSheet("""
            QPushButton {
                background: transparent;
                color: #ffffff;
                border: none;
                font-size: 20pt;
                font-weight: bold;
                padding: 0px;
            }
            QPushButton:hover {
                background: rgba(255, 255, 255, 0.2);
                border-radius: 4px;
            }
            QPushButton:pressed {
                background: rgba(255, 255, 255, 0.3);
            }
        """)
        fullscreen_btn.clicked.connect(self._toggle_fullscreen)
        header_right_layout.addWidget(sys_info_widget)
        header_right_layout.addWidget(fullscreen_btn)
        self.fullscreen_btn = fullscreen_btn
        
        # Close button (X) in top right
        close_btn = QPushButton("❌")
        close_btn.setFixedSize(30, 30)
        close_btn.setStyleSheet("""
            QPushButton {
                background: transparent;
                color: #f44336;
                border: none;
                font-size: 16pt;
                font-weight: bold;
                padding: 0px;
            }
            QPushButton:hover {
                background: rgba(244, 67, 54, 0.2);
                border-radius: 4px;
            }
            QPushButton:pressed {
                background: rgba(244, 67, 54, 0.3);
            }
        """)
        close_btn.clicked.connect(self.close)
        header_right_layout.addWidget(close_btn)
        self.close_btn = close_btn  # Store reference for frame integration

        # Mount left/right columns and keep them symmetric so the title is centered
        header_layout.addWidget(header_left, 0, 0, Qt.AlignLeft | Qt.AlignVCenter)
        header_layout.addWidget(header_right, 0, 2, Qt.AlignRight | Qt.AlignVCenter)

        self.header_left_container = header_left
        self.header_right_container = header_right

        QTimer.singleShot(0, self._sync_header_side_widths)
        
        # Create main layout
        main_widget = QWidget()
        main_layout = QVBoxLayout(main_widget)
        main_layout.setContentsMargins(0, 0, 0, 0)
        main_layout.setSpacing(0)
        
        main_layout.addWidget(header_widget)

        # Create custom navbar with buttons
        navbar = QWidget()
        navbar_layout = QHBoxLayout(navbar)
        navbar_layout.setContentsMargins(0, 0, 0, 0)
        navbar_layout.setSpacing(2)
        
        # Tab buttons
        self.home_btn = QPushButton("🏠 Home")
        # Note: 'Fine Tuning' and 'Agentic Team' group toggles live in
        # the HEADER (next to the Advanced button) — see the
        # _make_header_toggle calls above. They were moved out of the
        # navbar to declutter and to group them visually with the only
        # other reveal-toggle (Advanced).
        self.download_btn = QPushButton("📦 Models")
        self.train_btn = QPushButton("🎯 Train")
        self.test_btn = QPushButton("🧪 Test")
        self.logs_btn = QPushButton("📊 Logs")
        self.server_btn = QPushButton("🖧 Server")
        self.mcp_btn = QPushButton("🧩 MCP")
        self.envs_btn = QPushButton("⚙️ Environment")
        self.characters_btn = QPushButton("🧙‍♂️ Characters")
        self.code_btn = QPushButton("💻 Code")
        self.agents_btn = QPushButton("🤖 Agents")
        self.studio_btn = QPushButton("🎭 Studio")
        self.accounts_btn = QPushButton("🔐 Accounts")
        self.bridges_btn = QPushButton("📱 Bridges")
        self.gamify_btn = QPushButton("🎮 Gamify")
        self.arena_top_btn = QPushButton("🏟 Arena")
        self.info_btn = QPushButton("ℹ️ Info")

        # Navigation buttons will be styled by theme system

        for btn in [
            self.home_btn,
            self.train_btn, self.download_btn, self.test_btn,
            self.logs_btn, self.server_btn, self.mcp_btn, self.envs_btn,
            self.characters_btn, self.code_btn, self.agents_btn,
            self.studio_btn, self.accounts_btn, self.bridges_btn,
            self.gamify_btn, self.arena_top_btn, self.info_btn,
        ]:
            btn.setCheckable(True)
            # Strong active-tab highlight — the theme's default :checked
            # style only flips a gradient direction, which is nearly
            # invisible on dark backgrounds. Inject an explicit per-button
            # stylesheet so the active tab is unambiguous: brighter fill,
            # bright cyan bottom border, white bold text.
            btn.setStyleSheet("""
                QPushButton {
                    background: rgba(255, 255, 255, 0.04);
                    color: #cbd2e0;
                    border: none;
                    border-bottom: 3px solid transparent;
                    padding: 12px 20px;
                    font-size: 13pt;
                    font-weight: 600;
                    min-height: 32px;
                }
                QPushButton:hover {
                    background: rgba(255, 255, 255, 0.10);
                    color: #ffffff;
                }
                QPushButton:checked {
                    background: rgba(116, 164, 255, 0.18);
                    color: #ffffff;
                    font-weight: bold;
                    border-bottom: 3px solid #74a4ff;
                }
                QPushButton:checked:hover {
                    background: rgba(116, 164, 255, 0.28);
                }
            """)

        # Layout — order matters because we toggle visibility on the
        # individual buttons below. The Fine Tuning and Agentic Team
        # GROUP TOGGLES that previously lived between these sub-buttons
        # have been moved to the HEADER (see _make_header_toggle calls
        # next to the Advanced button); only the sub-buttons remain in
        # the navbar.
        navbar_layout.addWidget(self.home_btn)
        # Fine Tuning sub-tabs — hidden until the header group toggle is on.
        navbar_layout.addWidget(self.download_btn)
        navbar_layout.addWidget(self.train_btn)
        navbar_layout.addWidget(self.test_btn)
        # Agentic Team sub-tabs — hidden until the header group toggle is on.
        navbar_layout.addWidget(self.code_btn)
        navbar_layout.addWidget(self.agents_btn)
        navbar_layout.addWidget(self.studio_btn)
        navbar_layout.addWidget(self.bridges_btn)
        # Gamify sub-tabs — hidden until the Gamify header toggle is on.
        navbar_layout.addWidget(self.gamify_btn)
        navbar_layout.addWidget(self.characters_btn)
        navbar_layout.addWidget(self.arena_top_btn)
        navbar_layout.addWidget(self.server_btn)

        # Add stretch to consume remaining space
        navbar_layout.addStretch(1)

        # Right-side buttons — Info always visible. Advanced sub-tabs
        # (MCP / Environment / Accounts / Logs) appear here only when the
        # Advanced toggle in the header is on.
        navbar_layout.addWidget(self.mcp_btn)
        navbar_layout.addWidget(self.envs_btn)
        navbar_layout.addWidget(self.accounts_btn)
        navbar_layout.addWidget(self.logs_btn)
        navbar_layout.addWidget(self.info_btn)
        
        main_layout.addWidget(navbar)

        # Create tab widget for content (hide the tab bar since we're using custom buttons)
        tabs = QTabWidget()
        tabs.tabBar().setVisible(False)
        # IMPORTANT: store on self for other callbacks (GPU refresh, background detection, etc.)
        self.tabs = tabs
        
        # Page name constants for reliable tab navigation
        self.tab_page_names = {
            "home": "🏠 Home",
            "models": "Models",
            "train": "Train",
            "test": "Test",
            "logs": "Logs",
            "server": "Server",
            "mcp": "MCP",
            "characters": "Characters",
            "code": "Code",
            "agents": "Agents",
            "studio": "Studio",
            "accounts": "Accounts",
            "bridges": "Bridges",
            "gamify": "Gamify",
            "arena": "Arena",
            "github_import": "GitHub Import",
            "environment": "Environment Manager",
            "info": "Info"
        }
        
        def _timed_build(name: str, builder):
            t0 = time.perf_counter()
            widget = builder()
            dt = (time.perf_counter() - t0) * 1000.0
            try:
                self._log_to_app_log(f"[STARTUP] built tab '{name}' in {dt:.0f}ms")
            except Exception:
                pass
            return widget

        tabs.addTab(_timed_build("Home", self._build_home_tab), "🏠 Home")
        tabs.addTab(_timed_build("Models", self._build_models_tab), "Models")
        tabs.addTab(_timed_build("Train", self._build_train_tab), "Train")
        tabs.addTab(_timed_build("Test", self._build_test_tab), "Test")
        tabs.addTab(_timed_build("Logs", self._build_logs_tab), "Logs")
        self.server_page = _timed_build("Server", lambda: ServerPage(self))
        tabs.addTab(self.server_page, "Server")
        tabs.addTab(_timed_build("MCP", lambda: MCPPage(self)), "MCP")
        tabs.addTab(_timed_build("GitHub Import", lambda: GitHubImportPage(self)), "GitHub Import")
        
        # 3D Characters page — left panel is replaced with an Arena-
        # style model A/B/C selector column (Avatar Selection +
        # Instruction Templates + System Prompt + Logs tabs) so the
        # Characters page exposes the same per-model controls the
        # Arena page does, on its left side, while keeping the 3D
        # scene on the right.
        def _build_characters():
            page = Characters3DPage(self)
            self._characters_page = page
            try:
                arena_panel = self._build_characters_arena_style_panel()
                page.replace_left_panel(arena_panel)
            except Exception:
                logger.exception("[CHARACTERS] arena-style panel injection failed")
            return page
        tabs.addTab(_timed_build("Characters", _build_characters), "Characters")

        # Gamify — merged 3D playground (Characters scene + Arena's
        # right-column model + character selectors). Lazy-built on
        # first open so startup stays light when the user isn't using
        # the playground.
        self._gamify_page = None
        self._gamify_tab_placeholder = QWidget()
        _gp_layout = QVBoxLayout(self._gamify_tab_placeholder)
        _gp_layout.setContentsMargins(20, 20, 20, 20)
        _gp_layout.addWidget(QLabel("Gamify loads when opened…"))
        _gp_layout.addStretch(1)
        self._gamify_tab_index = tabs.addTab(self._gamify_tab_placeholder, "Gamify")

        # Arena (top-level) — surfaces the existing Test → Arena
        # sub-tab as its own top-level tab so the Gamify navbar can
        # link to it directly. The Test page's Arena sub-tab is
        # hidden in _build_test_tab when this top-level entry exists.
        self._arena_top_page = None
        self._arena_top_tab_placeholder = QWidget()
        _atp = QVBoxLayout(self._arena_top_tab_placeholder)
        _atp.setContentsMargins(20, 20, 20, 20)
        _atp.addWidget(QLabel("Arena loads when opened…"))
        _atp.addStretch(1)
        self._arena_top_tab_index = tabs.addTab(self._arena_top_tab_placeholder, "Arena")

        # Code tab — bundled VSCodium + Cline embedded in OWLLM. Lazy-built
        # so the (potentially first-run) bootstrap doesn't block startup.
        self._code_page = None
        self._code_tab_placeholder = QWidget()
        _code_placeholder_layout = QVBoxLayout(self._code_tab_placeholder)
        _code_placeholder_layout.setContentsMargins(20, 20, 20, 20)
        _code_placeholder_layout.addWidget(QLabel("Code editor loads when opened…"))
        _code_placeholder_layout.addStretch(1)
        self._code_tab_index = tabs.addTab(self._code_tab_placeholder, "Code")
        tabs.currentChanged.connect(lambda idx: self._init_code_page_if_needed(tabs, idx))

        # Agents tab — multi-agent OWLLM runtime (orchestrator + specialists).
        # Lazy-built so importing PySide-heavy modules doesn't slow startup.
        self._agents_page = None
        self._agents_tab_placeholder = QWidget()
        _agents_placeholder_layout = QVBoxLayout(self._agents_tab_placeholder)
        _agents_placeholder_layout.setContentsMargins(20, 20, 20, 20)
        _agents_placeholder_layout.addWidget(QLabel("Agents runtime loads when opened…"))
        _agents_placeholder_layout.addStretch(1)
        self._agents_tab_index = tabs.addTab(self._agents_tab_placeholder, "Agents")
        tabs.currentChanged.connect(lambda idx: self._init_agents_page_if_needed(tabs, idx))

        # Accounts tab — top-level. Lazy-built like the others to keep
        # startup snappy.
        self._accounts_page = None
        self._accounts_tab_placeholder = QWidget()
        _ap_layout = QVBoxLayout(self._accounts_tab_placeholder)
        _ap_layout.setContentsMargins(20, 20, 20, 20)
        _ap_layout.addWidget(QLabel("Accounts loads when opened…"))
        _ap_layout.addStretch(1)
        self._accounts_tab_index = tabs.addTab(self._accounts_tab_placeholder, "Accounts")
        tabs.currentChanged.connect(lambda idx: self._init_accounts_page_if_needed(tabs, idx))

