    def _on_repair_model(self, model_path: str):
        """Repair or resume download for an incomplete model"""
        path = Path(model_path)
        model_name = path.name
        
        # Try to extract model ID
        status = self.model_checker.check_model(path)
        model_id = status.model_id
        
        if not model_id:
            QMessageBox.warning(self, "Repair Model", 
                                f"Could not determine HuggingFace Model ID for: {model_name}\n\n"
                                "You may need to delete and redownload it manually.")
            return
            
        reply = QMessageBox.question(self, "Repair Model", 
                                    f"Do you want to repair '{model_id}'?\n\n"
                                    "This will purge the model's Hugging Face cache entry and redownload files "
                                    "(replacing any corrupted or missing shards). If repair fails, you'll be prompted to delete and redownload.",
                                    QMessageBox.Yes | QMessageBox.No)
        
        if reply == QMessageBox.Yes:
            self._log_models(f"🔧 Repairing {model_id}...")
            
            # Unlock files first (stop any active downloads, kill locking processes)
            path_obj = Path(model_path)
            self._unlock_model_files(path_obj, log_callback=lambda m: self._log_models(m))
            
            # Keep .incomplete files so repair can resume instead of restarting from zero.
            
            # Find the card to show progress
            card = None
            for c in self.downloaded_model_cards:
                if c.model_path == model_path:
                    card = c
                    break
            
            if not card:
                return
            
            # Disable repair button
            if hasattr(card, 'repair_btn'):
                card.repair_btn.setEnabled(False)
                card.repair_btn.setText("⏳ Fixing...")
            
            # Create progress bar
            progress_bar = QProgressBar()
            progress_bar.setMinimum(0)
            progress_bar.setMaximum(100)
            progress_bar.setValue(0)
            progress_bar.setTextVisible(True)
            progress_bar.setFormat("Repairing... %p%")
            progress_bar.setStyleSheet("""
                QProgressBar {
                    border: none;
                    border-radius: 4px;
                    text-align: center;
                    background-color: #262730;
                    color: white;
                    font-weight: bold;
                    height: 30px;
                }
                QProgressBar::chunk {
                    background: qlineargradient(x1:0, y1:0, x2:1, y2:0, 
                        stop:0 #ffa500, stop:1 #ff8c00);
                    border-radius: 4px;
                }
            """)
            
            # Add progress bar to card layout
            card.layout().addWidget(progress_bar)
            
            # Add status label to show current step (purge, downloading file X/Y, etc.)
            status_label = QLabel("Preparing repair...")
            status_label.setStyleSheet("color: #ccc; font-size: 11pt; padding: 6px;")
            status_label.setWordWrap(True)
            card.layout().addWidget(status_label)
            
            # Prefer persisted selected-weights marker; fallback to local GGUF inference.
            repair_allow_patterns = None
            try:
                marker_path = path_obj / ".selected_weights.json"
                if marker_path.exists():
                    marker = json.loads(marker_path.read_text(encoding="utf-8"))
                    pats = marker.get("allow_patterns")
                    if isinstance(pats, list):
                        repair_allow_patterns = [str(p) for p in pats if isinstance(p, str) and p.strip()]
                        if repair_allow_patterns:
                            self._log_models(f"  Repair will re-download selected subset ({len(repair_allow_patterns)} file(s)).")
                if not repair_allow_patterns:
                    from core.model_file_utils import list_repo_files
                    local_gguf = list(path_obj.rglob("*.gguf"))
                    if local_gguf:
                        siblings = list_repo_files(model_id, token=self._resolve_hf_token())
                        repo_gguf = [s.get("rfilename", "") for s in siblings if (s.get("rfilename") or "").lower().endswith(".gguf")]
                        if len(repo_gguf) > 1 and len(local_gguf) == 1:
                            match_name = local_gguf[0].name
                            for r in repo_gguf:
                                if Path(r).name == match_name:
                                    repair_allow_patterns = [r]
                                    self._log_models(f"  Repair will re-download only: {match_name}")
                                    break
            except Exception:
                pass
            # Create repair thread (resume-first, non-destructive)
            thread = RepairThread(model_id, path_obj, force_fresh_only=False, cache_dir=self.hf_cache_dir, token=self._resolve_hf_token(), allow_patterns=repair_allow_patterns)
            
            # Mark as active
            repair_key = f"repair_{model_id}"
            self.active_downloads[repair_key] = (thread, card)
            
            # Connect signals
            thread.progress.connect(lambda p: self._safe_progress_set(progress_bar, p))
            thread.status.connect(lambda msg: self._safe_label_set(status_label, msg))
            thread.status.connect(lambda msg: self._safe_progress_text(progress_bar, "Repairing", msg))
            thread.finished.connect(lambda dest: self._on_repair_complete(model_id, dest, card, progress_bar, repair_key, status_label))
            # Store repair info so we can look it up when error signal is received
            if not hasattr(self, '_repair_info'):
                self._repair_info = {}
            self._repair_info[repair_key] = {
                'model_id': model_id, 'card': card, 'progress_bar': progress_bar,
                'status_label': status_label, 'model_path': path_obj, 'operation': 'repair'
            }
            # Simple lambda that looks up the info
            thread.error.connect(lambda err, rk=repair_key: self._handle_repair_error(rk, err))
            
            # Log immediately
            self._log_models(f"🔧 Starting repair for {model_id}...")
            self._log_models(f"   Purging HF cache and redownloading files (replacing corrupted shards)")
            
            # Start repair
            thread.start()
            
            # Update progress bar immediately
            self._safe_progress_set(progress_bar, 2)

    def _on_create_dedicated_env(self, model_path: str):
        """Manually trigger creation of a dedicated environment for a model"""
        path = Path(model_path)
        model_name = path.name
        
        # Try to extract model ID
        status = self.model_checker.check_model(path)
