    def _delete_model_directory_robust(self, path: Path, log_callback=None) -> bool:
        """
        Robustly delete a model directory using the same strategy as Delete button.
        Returns True if directory is deleted, False otherwise.
        """
        def log(msg):
            if log_callback:
                log_callback(msg)
            else:
                self._log_models(msg)
        
        if not path.exists():
            return True
        
        log(f"Deleting directory: {path.name}")
        
        # Unlock files first (stop downloads, kill locking processes)
        self._unlock_model_files(path, log_callback=log)
        
        # Robust deletion with retries for Windows (same as Delete button)
        import time
        import subprocess
        
        success = False
        for attempt in range(1, 5):
            try:
                # Before deletion, try to remove .incomplete files first
                if path.exists():
                    cache_dir = path / ".cache" / "huggingface" / "download"
                    if cache_dir.exists():
                        try:
                            # Remove incomplete files
                            for incomplete_file in cache_dir.rglob("*.incomplete"):
                                try:
                                    incomplete_file.unlink()
                                except Exception:
                                    pass
                            # Try to remove cache directory
                            if cache_dir.exists():
                                shutil.rmtree(cache_dir, ignore_errors=True)
                        except Exception:
                            pass
                
                if sys.platform == 'win32':
                    # Force delete on Windows using cmd with retries
                    result = subprocess.run(
                        ['cmd', '/c', 'rmdir', '/S', '/Q', str(path)], 
                        capture_output=True, 
                        timeout=30,
                        **SUBPROCESS_FLAGS
                    )
                    # Also try PowerShell method as fallback
                    if path.exists() and attempt >= 2:
                        ps_cmd = f'Remove-Item -Path "{path}" -Recurse -Force -ErrorAction SilentlyContinue'
                        subprocess.run(
                            ['powershell', '-Command', ps_cmd],
                            capture_output=True,
                            timeout=30,
                            **SUBPROCESS_FLAGS
                        )
                else:
                    shutil.rmtree(path, ignore_errors=True)
                
                if not path.exists():
                    success = True
                    log(f"✓ Directory deleted successfully")
                    break
            except Exception as e:
                if attempt < 4:
                    log(f"Deletion attempt {attempt} failed, retrying... ({str(e)[:100]})")
            
            if attempt < 4:
                time.sleep(2)
        
        if not success and path.exists():
            # Final attempt with direct shutil
            try:
                shutil.rmtree(path, ignore_errors=True)
            except Exception:
                pass
        
        return not path.exists()
    
    def _unlock_model_files(self, model_path: Path, log_callback=None) -> bool:
        """
        Unlock files in a model directory by killing processes that might be using them.
        Specifically targets:
        - Active download/repair threads for this model
        - Python processes running huggingface_hub downloads
        - Any processes with file handles open in the directory
        
        Returns:
            True if unlocking succeeded or no locks detected, False if unlocking failed
        """
        def log(msg):
            if log_callback:
                log_callback(msg)
            else:
                self._log_models(msg)
        
        log(f"Unlocking files in {model_path.name}...")
        
        # 1. Stop any active download/repair threads for this model
        model_id = model_path.name.replace("__", "/")
        if hasattr(self, 'active_downloads'):
            if model_id in self.active_downloads:
                log("Stopping active download thread...")
                thread, card = self.active_downloads[model_id]
                if thread.isRunning():
                    # Ask thread to stop cooperatively first
                    try:
                        if hasattr(thread, "request_stop"):
                            thread.request_stop()
                    except Exception:
                        pass
                    # Give it time to release HuggingFace file locks
                    thread.wait(10000)  # Wait up to 10 seconds
                    if thread.isRunning():
                        thread.terminate()
                        thread.wait(3000)  # Wait up to 3 seconds
                del self.active_downloads[model_id]
            
            # Also check for repair threads (they use a different key format)
            repair_key = f"repair_{model_id}"
            if repair_key in self.active_downloads:
                log("Stopping active repair thread...")
                thread, card = self.active_downloads[repair_key]
                if thread.isRunning():
                    try:
                        if hasattr(thread, "request_stop"):
                            thread.request_stop()
                    except Exception:
                        pass
                    thread.wait(10000)
                    if thread.isRunning():
                        thread.terminate()
                        thread.wait(3000)
                del self.active_downloads[repair_key]
        
        # 2. Remove .incomplete files that are often locked
        try:
            cache_dir = model_path / ".cache" / "huggingface" / "download"
            if cache_dir.exists():
                incomplete_files = list(cache_dir.rglob("*.incomplete"))
                if incomplete_files:
                    log(f"Removing {len(incomplete_files)} incomplete download files...")
                    for incomplete_file in incomplete_files:
                        try:
                            # Try to remove read-only attribute first
                            if sys.platform == 'win32':
                                import subprocess
                                subprocess.run(['attrib', '-R', str(incomplete_file)], 
                                             capture_output=True, timeout=2, **SUBPROCESS_FLAGS)
                            incomplete_file.unlink()
                        except Exception:
                            pass
        except Exception as e:
            log(f"Warning: Could not clean incomplete files: {e}")
        
        # 3. On Windows, try to find and kill processes that might be locking files
        if sys.platform == 'win32':
            try:
                import subprocess
                import time
                
                # Find Python processes that might be downloading
                # Check for processes with the model path in their command line
                try:
                    # Use wmic to find processes (more reliable than tasklist for this)
                    cmd = f'wmic process where "CommandLine like \'%{model_path.name}%\'" get ProcessId /format:value'
                    result = subprocess.run(
                        cmd,
                        shell=True,
                        capture_output=True,
                        text=True,
                        timeout=5,
                        **SUBPROCESS_FLAGS
                    )
                    # Parse PIDs and kill them
                    for line in result.stdout.split('\n'):
                        if 'ProcessId=' in line:
                            try:
                                pid = int(line.split('=')[1].strip())
                                if pid:
                                    log(f"Killing process {pid} that may be locking files...")
                                    subprocess.run(['taskkill', '/F', '/PID', str(pid)],
                                                 capture_output=True, timeout=3, **SUBPROCESS_FLAGS)
                            except (ValueError, IndexError):
                                pass
                except Exception:
                    pass
                
                # Wait for file handles to be released
                log("Waiting for file handles to be released...")
                time.sleep(3)  # Give processes time to release handles
                
            except Exception as e:
                log(f"Warning: Could not check for locking processes: {e}")
        
        log("File unlock attempt completed")
        return True
    
    def _on_delete_model(self, model_path: str):
        """Delete a downloaded model directory forcefully"""
        path = Path(model_path)
        model_name = path.name
        
        # Check if any inference process is running
        running_procs = []
        if hasattr(self, 'test_proc_a') and self.test_proc_a is not None: running_procs.append("Model A")
        if hasattr(self, 'test_proc_b') and self.test_proc_b is not None: running_procs.append("Model B")
        if hasattr(self, 'test_proc_c') and self.test_proc_c is not None: running_procs.append("Model C")
        
        if running_procs:
            QMessageBox.warning(
                self, "Model Locked",
                f"Cannot delete model while inference is running for: {', '.join(running_procs)}.\n\n"
                "Please stop inference before deleting."
            )
            return

        # Confirmation dialog
        reply = QMessageBox.question(
            self, "Delete Model",
            f"Are you sure you want to delete the model '{model_name}'?\n\n"
            f"This will permanently remove all files from:\n{model_path}",
            QMessageBox.Yes | QMessageBox.No, QMessageBox.No
        )
        
        if reply == QMessageBox.Yes:
            try:
                self._log_models(f"🗑️ Deleting model: {model_name}...")
                
                # Unlock files first (stop downloads, kill locking processes)
                self._unlock_model_files(path, log_callback=lambda m: self._log_models(m))
                
                # Robust deletion with retries for Windows
                import time
                import subprocess
                
                success = False
                for attempt in range(1, 5):  # Increased retries
                    try:
                        # Before deletion, try to remove .incomplete files first
                        if path.exists():
                            cache_dir = path / ".cache" / "huggingface" / "download"
                            if cache_dir.exists():
                                try:
                                    # Remove incomplete files
                                    for incomplete_file in cache_dir.rglob("*.incomplete"):
                                        try:
                                            incomplete_file.unlink()
                                        except Exception:
                                            pass
                                    # Try to remove cache directory
                                    if cache_dir.exists():
                                        shutil.rmtree(cache_dir, ignore_errors=True)
                                except Exception:
                                    pass
                        
                        if sys.platform == 'win32':
                            # Force delete on Windows using cmd with retries
                            result = subprocess.run(
                                ['cmd', '/c', 'rmdir', '/S', '/Q', str(path)], 
                                capture_output=True, 
                                timeout=30,
                                **SUBPROCESS_FLAGS
                            )
                            # Also try PowerShell method as fallback
                            if path.exists() and attempt >= 2:
                                ps_cmd = f'Remove-Item -Path "{path}" -Recurse -Force -ErrorAction SilentlyContinue'
                                subprocess.run(
                                    ['powershell', '-Command', ps_cmd],
                                    capture_output=True,
                                    timeout=30,
                                    **SUBPROCESS_FLAGS
                                )
                        else:
                            shutil.rmtree(path, ignore_errors=True)
                        
                        if not path.exists():
                            success = True
                            break
                    except Exception as e:
                        if attempt < 4:
                            log_msg = f"Deletion attempt {attempt} failed, retrying... ({str(e)[:100]})"
                            self._log_models(log_msg)
                    
                    if attempt < 4:
                        time.sleep(2)  # Longer wait between retries
                
                if success:
                    self._log_models(f"✓ Model '{model_name}' deleted successfully.")
                else:
                    # Final attempt with direct shutil if path still exists
                    if path.exists():
                        try:
                            shutil.rmtree(path, ignore_errors=True)
                        except Exception:
                            pass
                    
                    if not path.exists():
                        self._log_models(f"✓ Model '{model_name}' deleted successfully.")
                    else:
                        # Last resort: try to delete individual files
                        try:
                            for item in path.rglob("*"):
                                try:
                                    if item.is_file():
                                        item.unlink()
                                    elif item.is_dir():
                                        item.rmdir()
                                except Exception:
                                    pass
                            # Try to remove the directory itself
                            path.rmdir()
                        except Exception:
                            pass
                        
                        if path.exists():
                            raise RuntimeError(
                                f"Could not delete model directory after multiple attempts.\n"
                                f"Some files may still be locked by another process.\n"
                                f"Try closing other applications and restarting the app, then delete again."
                            )
                        else:
                            self._log_models(f"✓ Model '{model_name}' deleted successfully (after cleanup).")
                
                # Refresh all local state (Download tab cards + dropdowns)
                self._refresh_locals()
                    
            except Exception as e:
                self._log_models(f"❌ Error deleting model: {str(e)}")
                QMessageBox.critical(
                    self, "Error", 
                    f"Could not delete model directory:\n{str(e)}\n\n"
                    f"Files may be locked by another process.\n"
                    f"Try:\n"
                    f"1. Closing other applications\n"
                    f"2. Restarting this app\n"
                    f"3. Manually deleting the folder: {model_path}"
                )
    
    def _on_models_tab_changed(self, index: int):
        """Handle models tab changes - sync custom button states"""
        self.browse_tab_btn.setChecked(index == 0)
        self.downloaded_tab_btn.setChecked(index == 1)
        if hasattr(self, "tuned_tab_btn"):
            self.tuned_tab_btn.setChecked(index == 2)
        if index == 2:
            try:
                self._refresh_tuned_models()
            except Exception:
                pass

    def _refresh_tuned_models(self) -> None:
        """Re-list locally fine-tuned outputs (PEFT adapters) into the
        Tuned Models tab.

        Source of truth: ``LLM/fine_tuned/`` — every subdir with both
        ``adapter_config.json`` and an ``adapter_model.{safetensors,bin}``
        is treated as a finished training run. Anything else (in-progress
        checkpoint dirs, broken outputs) is skipped.

        Layout: 2-column QGridLayout matching the Downloaded Models page.
        """
        if not hasattr(self, "tuned_layout") or not hasattr(self, "tuned_container"):
            return
        # Clear the entire grid before repopulating.
        while self.tuned_layout.count():
            item = self.tuned_layout.takeAt(0)
            w = item.widget() if item else None
            if w is not None:
                w.setParent(None)

        from core.models import list_local_adapters
        adapters = list_local_adapters()
        adapter_root = self.root / "fine_tuned"

        if not adapters:
            empty = QLabel(
                "No fine-tuned models yet.\n\n"
                "Run a training job in the Train tab — finished LoRA adapters\n"
                f"will show up here automatically (saved under {adapter_root})."
            )
            empty.setAlignment(Qt.AlignCenter)
            empty.setStyleSheet(
                "color:#888; font-size: 12pt; padding: 40px;"
            )
            # Span the empty-state label across both columns.
            self.tuned_layout.addWidget(empty, 0, 0, 1, 2)
            return

        # Four columns so each card lands at ~25 % of the window width
        # (matches the user's spec). Below, _resize_tuned_cards keeps
        # min/max widths in step with the actual window size on resize.
        max_cols = 4
        row = col = 0
        self._tuned_cards: List[QFrame] = []
        for name in adapters:
            path = adapter_root / name
            card = self._build_tuned_model_card(name, path)
            self.tuned_layout.addWidget(card, row, col)
            self._tuned_cards.append(card)
            col += 1
            if col >= max_cols:
                col = 0
                row += 1
        self._resize_tuned_cards()

    def _build_tuned_model_card(self, name: str, path: "Path") -> QFrame:
        """Render one fine-tuned adapter as a card.

        Visual is intentionally identical to ``DownloadedModelCard`` —
        same outer dimensions, same gradient + colored border, same
        50×50 icon, same 14 pt bold name, same status-badge style,
        same blue ``rgba(102, 126, 234, …)`` button palette. Only the
        accent emoji (🎯) and the action set distinguish it from a
        downloaded base model.
        """
        import json as _json
        import os
        import urllib.parse
        from datetime import datetime as _dt

        # --- metadata ---------------------------------------------------
        base_model = "—"
        adapter_cfg_path = path / "adapter_config.json"
        if adapter_cfg_path.exists():
            try:
                with adapter_cfg_path.open("r", encoding="utf-8") as f:
                    cfg = _json.load(f)
                base_model = (
                    cfg.get("base_model_name_or_path")
                    or cfg.get("base_model")
                    or "—"
                )
                if base_model and "/" in base_model:
                    base_model = base_model.split("/")[-1]
                if base_model and len(base_model) > 50:
                    base_model = base_model[:47] + "…"
            except Exception:
                pass

        size_bytes = 0
        try:
            for p in path.rglob("*"):
                if p.is_file():
                    size_bytes += p.stat().st_size
        except Exception:
            pass
        size_mb = size_bytes / (1024 * 1024) if size_bytes else 0.0
        size_str = f"{size_mb:.1f} MB" if size_mb < 1024 else f"{size_mb / 1024:.2f} GB"

        try:
            mtime = max((p.stat().st_mtime for p in path.rglob("*") if p.is_file()), default=0)
        except Exception:
            mtime = 0
        date_str = (
            _dt.fromtimestamp(mtime).strftime("%Y-%m-%d %H:%M") if mtime else "—"
        )
        onboarded = (path / ".onboarded").exists()

        # --- card frame: same border + gradient as DownloadedModelCard --
        card = QFrame()
        card.setMinimumHeight(220)
        card.setFrameShape(QFrame.Box)
        # Match DownloadedModelCard's blue-accent dark gradient + 2 px
        # border + hover pop. The colour values are copied verbatim
        # from model_card_widget.DownloadedModelCard._apply_style so the
        # two card types render identically side by side.
        border_color = "#667eea"
        card.setStyleSheet(f"""
            QFrame {{
                background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
                    stop:0 #1e1e2e, stop:1 #16213e);
                border: 2px solid {border_color};
                border-radius: 10px;
            }}
            QFrame:hover {{
                background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
                    stop:0 #262740, stop:1 #1a2540);
            }}
            QLabel {{ background: transparent; color: #fafafa; border: none; }}
        """)
        layout = QVBoxLayout(card)
        layout.setContentsMargins(20, 15, 20, 15)
        layout.setSpacing(8)

        # --- header: 50×50 icon + title column --------------------------
        header_layout = QHBoxLayout()
        header_layout.setSpacing(15)

        # Adapter icon — mirror the family icon of its base model so a
        # Gemma-tuned adapter shows 💎, a Llama-tuned one shows 🦙, etc.
        # Falls back to the generic 🎯 only when the base name matches
        # no known family.
        icon_label = QLabel(card)
        icon_label.setFixedSize(50, 50)
        icon_label.setAlignment(Qt.AlignCenter)
        family_lookup = (base_model or name or "").lower()
        if "llama" in family_lookup:
            icon_text, icon_bg = "🦙", "#4CAF50"
        elif "qwen" in family_lookup:
            icon_text, icon_bg = "💮", "#9C27B0"
        elif "mistral" in family_lookup or "mixtral" in family_lookup:
            icon_text, icon_bg = "🌬️", "#FF9800"
        elif "gemma" in family_lookup or "google" in family_lookup:
            icon_text, icon_bg = "💎", "#4285F4"
        elif "phi" in family_lookup or "microsoft" in family_lookup:
            icon_text, icon_bg = "Φ", "#00A4EF"
        elif "deepseek" in family_lookup:
            icon_text, icon_bg = "🐳", "#0000FF"
        else:
            icon_text, icon_bg = "🎯", "#c08aff"
        icon_label.setText(icon_text)
        icon_label.setStyleSheet(
            "QLabel {"
            f"background-color: {icon_bg};"
            "color: white;"
            "border-radius: 25px;"
            "font-size: 24px;"
            "font-weight: bold;"
            "border: 2px solid rgba(255, 255, 255, 0.2);"
            "}"
        )
        header_layout.addWidget(icon_label)

        title_stats_layout = QVBoxLayout()
        title_stats_layout.setSpacing(2)

        # Top row: name + status badge.
        top_row = QHBoxLayout()
        top_row.setSpacing(10)
        name_label = QLabel(name, card)
        name_font = QFont()
        name_font.setPointSize(14)
        name_font.setBold(True)
        name_label.setFont(name_font)
        name_label.setWordWrap(True)
        name_label.setMaximumWidth(350)
        top_row.addWidget(name_label)

        if onboarded:
            badge_text = "✅ ONBOARDED"
            badge_bg = "#4CAF50"
        else:
            badge_text = "🆕 NEW"
            badge_bg = "#FF9800"
        status_badge = QLabel(badge_text, card)
        status_badge.setStyleSheet(f"""
            QLabel {{
                background-color: {badge_bg};
                color: white;
                padding: 3px 8px;
                border-radius: 4px;
                font-size: 11px;
                font-weight: bold;
            }}
        """)
        status_badge.setMaximumWidth(180)
        top_row.addWidget(status_badge)
        top_row.addStretch(1)
        title_stats_layout.addLayout(top_row)

        # Stats row: base model + modified date (mirrors the
        # downloads/likes row on the other cards).
        stats_row = QHBoxLayout()
        stats_row.setSpacing(15)
        base_lbl = QLabel(f"🧬 Base: {base_model}", card)
        base_lbl.setStyleSheet("color: #888; font-size: 11px;")
        stats_row.addWidget(base_lbl)
        date_lbl = QLabel(f"🕒 {date_str}", card)
        date_lbl.setStyleSheet("color: #888; font-size: 11px;")
        stats_row.addWidget(date_lbl)
        stats_row.addStretch(1)
        title_stats_layout.addLayout(stats_row)

        # Local-status badge row (matches DownloadedModelCard).
        local_row = QHBoxLayout()
        local_row.setSpacing(10)
        local_badge = QLabel("🎯 Fine-tuned", card)
        local_badge.setStyleSheet("""
            QLabel {
                background: rgba(192, 138, 255, 0.20);
                color: #c08aff;
                padding: 2px 6px;
                border-radius: 3px;
                font-size: 10px;
                font-weight: bold;
            }
        """)
        local_row.addWidget(local_badge)
        local_row.addStretch(1)
        title_stats_layout.addLayout(local_row)

        header_layout.addLayout(title_stats_layout, 1)
        layout.addLayout(header_layout)

        # --- middle row: size + accent emoji ----------------------------
        middle_layout = QHBoxLayout()
        size_label = QLabel(f"📦 {size_str}", card)
        size_font = QFont()
        size_font.setPointSize(13)
        size_label.setFont(size_font)
        middle_layout.addWidget(size_label)
        middle_layout.addStretch(1)
        accent_label = QLabel("🎯", card)
        accent_font = QFont()
        accent_font.setPointSize(18)
        accent_label.setFont(accent_font)
        middle_layout.addWidget(accent_label)
        layout.addLayout(middle_layout)

        # --- path link row (matches DownloadedModelCard) ---------------
        abs_path = os.path.abspath(str(path))
        file_url = f"file:///{urllib.parse.quote(abs_path.replace(os.sep, '/'))}"
        path_label = QLabel(
            f'📂 <a href="{file_url}" style="color: #667eea; text-decoration: none;">{path}</a>',
            card,
        )
        path_label.setOpenExternalLinks(True)
        path_label.setTextInteractionFlags(Qt.TextBrowserInteraction)
        path_font = QFont()
        path_font.setPointSize(11)
        path_label.setFont(path_font)
        path_label.setWordWrap(True)
        layout.addWidget(path_label)

        layout.addStretch(1)

        # --- button row (same blue palette as DownloadedModelCard) ----
        button_layout = QHBoxLayout()
        button_layout.setSpacing(8)
        button_style = """
            QPushButton {
                background: rgba(102, 126, 234, 0.15);
                border: 1px solid rgba(102, 126, 234, 0.4);
                color: white;
                border-radius: 6px;
                padding: 6px 15px;
                font-weight: bold;
            }
            QPushButton:hover {
                background: rgba(102, 126, 234, 0.25);
                border: 1px solid rgba(102, 126, 234, 0.6);
            }
            QPushButton:pressed {
                background: rgba(102, 126, 234, 0.35);
            }
            QPushButton:disabled {
                background: rgba(150, 150, 150, 0.05);
                color: #888;
                border: 1px solid rgba(150, 150, 150, 0.1);
            }
        """
        delete_style = button_style.replace(
            "rgba(102, 126, 234, 0.15)", "rgba(244, 67, 54, 0.18)"
        ).replace(
            "rgba(102, 126, 234, 0.4)", "rgba(244, 67, 54, 0.55)"
        ).replace(
            "rgba(102, 126, 234, 0.25)", "rgba(244, 67, 54, 0.30)"
        ).replace(
            "rgba(102, 126, 234, 0.6)", "rgba(244, 67, 54, 0.70)"
        ).replace(
            "rgba(102, 126, 234, 0.35)", "rgba(244, 67, 54, 0.45)"
        )

        # 'Use in Chat' and 'Onboard' buttons removed at the user's
        # request — adapters share their base model's onboarding, so
        # there's nothing to onboard separately, and selecting the
        # adapter from the Test / agent dropdowns is the canonical way
        # to use it in chat.
        open_btn = QPushButton("📂 Open", card)
        open_btn.setMinimumHeight(35)
        open_btn.setStyleSheet(button_style)
        open_btn.clicked.connect(
            lambda _checked=False, p=path: self._open_path_in_explorer(str(p))
        )
        button_layout.addWidget(open_btn)

        # Per-card "Convert to GGUF" — turns the adapter into a
        # quantised GGUF the llama-server backend can serve at full
        # speed. Visible on every adapter card so the user doesn't
        # have to retrain just to get the post-training prompt back.
        gguf_btn = QPushButton("⚡ To GGUF", card)
        gguf_btn.setMinimumHeight(35)
        gguf_btn.setToolTip(
            "Merge the LoRA into the base, convert to GGUF, quantise to "
            "Q5_K_M. Result lands in models/<adapter>__gguf/ and shows "
            "up in every dropdown — runs 3–8× faster than the "
            "Transformers backend."
        )
        # Highlight visually with the kbeauty/llamacpp accent so the
        # action stands out from the neutral Open button.
        gguf_style = button_style.replace(
            "rgba(102, 126, 234, 0.15)", "rgba(255, 196, 0, 0.18)"
        ).replace(
            "rgba(102, 126, 234, 0.4)", "rgba(255, 196, 0, 0.55)"
        ).replace(
            "rgba(102, 126, 234, 0.25)", "rgba(255, 196, 0, 0.30)"
        ).replace(
            "rgba(102, 126, 234, 0.6)", "rgba(255, 196, 0, 0.70)"
        ).replace(
            "rgba(102, 126, 234, 0.35)", "rgba(255, 196, 0, 0.45)"
        )
        gguf_btn.setStyleSheet(gguf_style)
        gguf_btn.clicked.connect(
            lambda _checked=False, p=path: self._convert_tuned_card_to_gguf(p)
        )
        button_layout.addWidget(gguf_btn)

        button_layout.addStretch(1)

        delete_btn = QPushButton("🗑️ Delete", card)
        delete_btn.setMinimumHeight(35)
        delete_btn.setStyleSheet(delete_style)
        delete_btn.clicked.connect(
            lambda _checked=False, n=name, p=path: self._delete_tuned_model(n, p)
        )
        button_layout.addWidget(delete_btn)

        layout.addLayout(button_layout)

        return card

    def _convert_tuned_card_to_gguf(self, adapter_path: "Path") -> None:
        """Resolve the adapter's base, prompt for quant, kick off async conversion.

        Wired to the ⚡ To GGUF button on every fine-tuned card. The
        underlying _convert_adapter_to_gguf_async runs the same
        pipeline used by the post-training prompt, so behaviour stays
        consistent regardless of where the conversion was triggered.
        """
        from PySide6.QtWidgets import QMessageBox, QInputDialog

        # Resolve the base path from adapter_config.json + onboarding
        # store. Reusing _resolve_adapter_base_path handles HF hub ids
        # and path variants the same way Onboard / Use-in-Chat do.
        base_raw = self._resolve_adapter_base_path(adapter_path) or ""
        base_path = ""
        if base_raw:
            cand = Path(base_raw)
            if cand.exists():
                base_path = str(cand)
            else:
                # Try as a folder under models/ (handles "google/gemma-4-E4B-it"
                # → models/google__gemma-4-E4B-it).
                slug = base_raw.replace("/", "__")
                cand = self.root / "models" / slug
                if cand.exists():
                    base_path = str(cand)
        if not base_path:
            QMessageBox.warning(
                self, "Convert to GGUF",
                f"Couldn't resolve the base model for adapter "
                f"<b>{adapter_path.name}</b>.<br><br>"
                "The adapter's <code>adapter_config.json</code> names a "
                "base model that isn't on disk under <code>models/</code>. "
                "Download or onboard the base first."
            )
            return

        # Quant picker — Q5_K_M default; let users pick smaller/larger
        # without leaving the page.
        from core.adapter_to_gguf import QUANT_PRESETS
        labels = list(QUANT_PRESETS.keys())
        try:
            default_idx = labels.index("Q5_K_M")
        except ValueError:
            default_idx = 0
        choice, ok = QInputDialog.getItem(
            self,
            "Convert to GGUF",
            f"Quantisation for <b>{adapter_path.name}</b>:\n\n"
            "Q5_K_M is the recommended sweet spot.\n"
            "Q4_K_M is smallest (low VRAM); Q8_0 is near-lossless.",
            labels,
            current=default_idx,
            editable=False,
        )
        if not ok or not choice:
            return

        # Confirm — conversion can take 2–5 min and burns ~16 GB of disk
        # for an 8B base while the merged HF model is on disk.
        confirm = QMessageBox.question(
            self,
            "Convert to GGUF",
            f"<b>Adapter:</b> {adapter_path.name}<br>"
            f"<b>Base:</b> {Path(base_path).name}<br>"
            f"<b>Quant:</b> {choice}<br><br>"
            "Conversion runs in the background and writes to "
            f"<code>models/{adapter_path.name}__gguf/</code>. "
            "Progress streams into the Train log.<br><br>"
            "Continue?",
            QMessageBox.Yes | QMessageBox.Cancel,
            QMessageBox.Yes,
        )
        if confirm != QMessageBox.Yes:
            return

        # Switch to the Train tab so the user sees the streaming log,
        # then dispatch the same async conversion the post-training
        # prompt uses.
        try:
            self._switch_tab(self.tabs, "train")
        except Exception:
            pass
        self._convert_adapter_to_gguf_async(
            adapter_dir=adapter_path,
            base_model_path=Path(base_path),
            quant=choice,
        )

    # ------------------------------------------------------------------
    # Helpers shared by Onboard / Use in Chat for tuned adapters
    # ------------------------------------------------------------------

    def _resolve_adapter_base_path(self, adapter_dir: "Path") -> Optional[str]:
        """Read adapter_config.json from a LoRA adapter dir and return
        the base model's local path (or HF id) on disk.

        Returns ``None`` if adapter_config.json is missing or doesn't
        name a base.
        """
        import json as _json
        cfg_path = adapter_dir / "adapter_config.json"
        if not cfg_path.exists():
            return None
        try:
            with cfg_path.open("r", encoding="utf-8") as f:
                cfg = _json.load(f)
        except Exception:
            return None
        return (
            cfg.get("base_model_name_or_path")
            or cfg.get("base_model")
            or None
        )

    def _base_model_match_keys(self, raw: str) -> set[str]:
        """Generate every reasonable lowercased identifier for a base model.

        A "base model" can show up in three different forms across the app:
          • A Windows path like ``C:\\1_Git\\LocaLLM\\LLM\\models\\google__gemma-4-E4B-it``
          • A POSIX-style path like ``C:/1_Git/.../google__gemma-4-E4B-it``
            (this is what PEFT writes into ``adapter_config.json``)
          • A HuggingFace hub id like ``google/gemma-4-E4B-it``
          • A sanitised model-dir basename like ``google__gemma-4-E4B-it``

        ``_find_base_onboarding`` used to compare ``str(Path(x)).lower()``
        on both sides — that fails the moment one side has backslashes and
        the other has forward slashes (which is exactly what happens with
        Windows + PEFT-written adapter_config.json). It also fails when a
        base was onboarded under its hub id but the adapter records the
        absolute local path (or vice versa). Returning a *set* of every
        likely form and intersecting with the row's keys fixes both gaps
        without inventing a brittle "canonical form" rule.
        """
        keys: set[str] = set()
        if not raw:
            return keys
        s = str(raw).strip()
        if not s:
            return keys
        keys.add(s.lower())
        # Slash variants — Windows vs POSIX serialisation.
        keys.add(s.replace("\\", "/").lower())
        keys.add(s.replace("/", "\\").lower())

        # Pathlib-resolved variants (handles redundant ./, trailing /, etc).
        try:
            p = Path(s)
            keys.add(str(p).lower())
            keys.add(p.as_posix().lower())
            if p.exists():
                rp = p.resolve()
                keys.add(str(rp).lower())
                keys.add(rp.as_posix().lower())
            # Directory basename — when both sides reference the same
            # model dir but with different parent paths (e.g. one is
            # absolute, one is relative).
            if p.name:
                keys.add(p.name.lower())
                # Sanitised basename -> hub id ("google__gemma-4-E4B-it"
                # -> "google/gemma-4-E4B-it"). Two-component split is
                # the safe default; any further "__" inside the model
                # name is a Gemma/Llama-style separator that should
                # stay as-is.
                if "__" in p.name:
                    keys.add(p.name.replace("__", "/", 1).lower())
        except Exception:
            pass

        # If the raw form looks like a hub id ("org/name"), also add the
        # disk-sanitised variant ("org__name") that the Models page uses.
        if "/" in s and "\\" not in s and ":" not in s:
            keys.add(s.replace("/", "__").lower())

        return keys

    def _find_base_onboarding(self, base_path: str) -> Optional[Dict[str, Any]]:
        """Look up an onboarding row for a given base model.

        Used to clone the base's env_key/backend/accelerator into the
        adapter's row so the adapter inherits a working environment.

        Two relaxations from the previous behaviour:

        1. **Tolerant matching.** A base is considered the same row if
           ANY of the candidate keys (path, hub id, basename,
           slash-flipped, sanitised, ...) of the requested side
           intersects ANY of the row's stored keys (against both
           ``base_model_path`` AND ``model_id``). Strict
           ``str(Path(x)).lower()`` equality misses across
           POSIX/Windows slash differences and across the hub-id ↔
           local-path representation gap that's standard in
           ``adapter_config.json``.

        2. **Status-tolerant.** We search ALL onboarding rows, not
           just ``status='READY'``. A base flagged BROKEN by a stale
           health check may still be functionally working (the user
           literally just trained an adapter on it). We prefer READY
           rows when several candidates match, but if only a non-READY
           candidate exists we use it anyway — the alternative is
           refusing to register a perfectly-trainable adapter, which
           is what the user has been hitting.

        Also falls back to the ``models`` table when no onboarding row
        matches at all, so bases registered via the Models page but
        never onboarded through the wizard still wire up correctly.
        """
        # Append a single diagnostic line per call to logs/app.log so a
        # mismatch between "I see the row in sqlite" and "the matcher
        # returned None" is debuggable from a fresh chair. Cheap, off
        # the hot path.
        def _diag(msg: str) -> None:
            try:
                self._log_to_app_log(f"[base-match] {msg}")
            except Exception:
                pass

        try:
            # Use the global StateStore singleton — calling
            # ``StateStore()`` directly fails because the constructor
            # requires a ``db_path`` argument. The factory wires the
            # canonical LLM/data/owllm_state.db path automatically.
            from core.state_store import get_state_store
            ss = get_state_store()
            wanted = self._base_model_match_keys(base_path)
            _diag(f"input={base_path!r} wanted_keys={sorted(wanted)}")
            if not wanted:
                return None

            # Pass 1 — onboarding table, ANY status. Collect every
            # match and prefer READY at the end.
            candidates: list[Dict[str, Any]] = []
            try:
                rows = ss.list_all_onboarding()
            except Exception as exc:
                _diag(f"list_all_onboarding raised: {exc!r} — falling back to READY-only")
                rows = ss.list_onboarding_by_status("READY")  # legacy fallback
            _diag(f"scanning {len(rows)} onboarding rows")
            for row in rows:
                row_keys = set()
                row_keys |= self._base_model_match_keys(
                    str(row.get("base_model_path", "") or "")
                )
                row_keys |= self._base_model_match_keys(
                    str(row.get("model_id", "") or "")
                )
                if wanted & row_keys:
                    candidates.append(row)

            if candidates:
                ready = [r for r in candidates if (r.get("status") or "").upper() == "READY"]
                pick = ready[0] if ready else candidates[0]
                _diag(f"matched onboarding row: {pick.get('model_id')!r} status={pick.get('status')!r}")
                return pick

            # Pass 1.5 — brute-force fallback. The keyset matcher should
            # have caught any sane representation, but just in case the
            # row stored a path with mixed separators, NTFS short names,
            # an extra trailing slash, or some other oddity we haven't
            # codified, do a final loose comparison: lowercased,
            # separator-flattened (every \ and / becomes /). If that
            # finds a substring match in either direction (one is a
            # suffix of the other), accept it.
            def _flat(x: str) -> str:
                s = (x or "").lower().replace("\\", "/").rstrip("/")
                return s

            wanted_flat = {_flat(k) for k in wanted if k}
            for row in rows:
                bp = _flat(str(row.get("base_model_path", "") or ""))
                mid = _flat(str(row.get("model_id", "") or ""))
                for w in wanted_flat:
                    if not w:
                        continue
                    if bp and (w == bp or w.endswith("/" + bp.split("/")[-1])
                               or bp.endswith("/" + w.split("/")[-1])):
                        _diag(f"loose-matched onboarding row via base_model_path: {row.get('model_id')!r}")
                        return row
                    if mid and (w == mid or w.endswith("/" + mid.split("/")[-1])):
                        _diag(f"loose-matched onboarding row via model_id: {row.get('model_id')!r}")
                        return row

            # Pass 2 — fall back to the ``models`` table. This catches
            # bases registered via a different code path (e.g. a direct
            # download that bypassed the onboarding wizard). We hand
            # back a synthesised onboarding-like dict so the caller's
            # downstream code still finds env_key/backend/etc.
            try:
                conn = ss._get_connection()
                model_rows = [dict(r) for r in conn.execute(
                    "SELECT model_id, backend, model_path FROM models"
                ).fetchall()]
            except Exception as exc:
                _diag(f"models-table query failed: {exc!r}")
                model_rows = []
            _diag(f"scanning {len(model_rows)} models-table rows as fallback")
            for mr in model_rows:
                m_keys = set()
                m_keys |= self._base_model_match_keys(
                    str(mr.get("model_path", "") or "")
                )
                m_keys |= self._base_model_match_keys(
                    str(mr.get("model_id", "") or "")
                )
                if wanted & m_keys:
                    _diag(f"matched models-table row: {mr.get('model_id')!r}")
                    return {
                        "model_id": mr.get("model_id"),
                        "base_model_path": mr.get("model_path"),
                        "backend": mr.get("backend"),
                        "env_key": None,
                        "accelerator": None,
                        "status": "READY",  # synthetic — present in models table = usable
                    }
            _diag("NO MATCH in onboarding or models tables")
        except Exception as e:
            try:
                self.train_log.appendPlainText(
                    f"[WARN] _find_base_onboarding failed: {e}"
                )
            except Exception:
                pass
        return None

    def _synthesize_base_row_from_adapter(
        self, adapter_dir: "Path", base_path: str
    ) -> Optional[Dict[str, Any]]:
        """Build a usable base-onboarding-like row when nothing matched.

        Strategy: read ``training_info.json`` (written by finetune.py
        on success — see [LLM/finetune.py] save_training_metadata
        block). It contains the exact base_model that was used to
        train and is the most authoritative breadcrumb available when
        the registry has no matching row.

        Picks an env_key by scanning ``LLM/.envs`` for a venv whose
        directory name contains the base's sanitised slug (e.g. for
        ``google/gemma-4-E4B-it`` it'll prefer
        ``...--dedicated--google__gemma-4-E4B-it`` if present).
        Falls back to the active env_key resolver, then to a hardcoded
        ``tf-cu121-t25-bnb-stable`` default that's known to load any
        bf16-quantised PEFT adapter.

        Returns ``None`` only when the adapter has no training metadata
        AND no environment can be inferred — at which point we genuinely
        can't proceed without user input.
        """
        import json as _json
        info_path = Path(adapter_dir) / "training_info.json"
        meta: Dict[str, Any] = {}
        try:
            if info_path.exists():
                meta = _json.loads(info_path.read_text(encoding="utf-8"))
        except Exception:
            meta = {}

        base_model = (
            meta.get("base_model")
            or base_path
            or ""
        )

        # Attempt 1: pick the venv that was already used for training.
        # finetune.py logs the active venv path in the training log;
        # we can re-derive it from the model's sanitised slug.
        env_key: Optional[str] = None
        try:
            base_slug = (
                Path(base_model).name
                if Path(base_model).exists() or "\\" in base_model or "/" in base_model
                else base_model.replace("/", "__")
            )
            envs_dir = self.root / ".envs"
            if envs_dir.exists():
                # Prefer dedicated env for this exact base.
                for d in envs_dir.iterdir():
                    if d.is_dir() and base_slug.lower() in d.name.lower() and "dedicated" in d.name.lower():
                        env_key = d.name
                        break
                # Fall back to any venv whose name contains the slug.
                if env_key is None:
                    for d in envs_dir.iterdir():
                        if d.is_dir() and base_slug.lower() in d.name.lower():
                            env_key = d.name
                            break
        except Exception:
            env_key = None

        # Attempt 2: ask the active profile resolver. This returns the
        # env_key the GUI would pick for a vanilla PEFT load right now,
        # which is always usable for adapter inference.
        if not env_key:
            try:
                from desktop_app import training_env_manager as tem
                env_key = tem._venv_dir(self.root).name  # type: ignore[attr-defined]
            except Exception:
                env_key = None

        # Attempt 3: hardcoded last-resort default. Picked because
        # ``tf-cu121-t25-bnb-stable`` ships with bitsandbytes + transformers
        # + peft and is the env every recent stable build uses for
        # PEFT-adapter inference. If it doesn't exist on disk, registration
        # still succeeds — the env will be auto-built when the user first
        # tries to chat with the adapter.
        if not env_key:
            env_key = "tf-cu121-t25-bnb-stable"

        return {
            "model_id": f"synth__{Path(base_model).name or 'unknown'}",
            "base_model_path": str(base_path),
            "env_key": env_key,
            "backend": "tf",  # transformers; correct for any PEFT adapter
            "accelerator": "cu121",
            "status": "READY",
        }

    def _register_tuned_adapter(self, name: str, adapter_dir: "Path") -> Tuple[bool, str]:
        """Register a tuned LoRA adapter as a usable model.

        Strategy: read the adapter's base_model from adapter_config.json,
        find an existing READY onboarding row for that base, then upsert
        a new row pairing the same base + this adapter dir with status
        READY. The chat picker reads from list_ready_models() so the
        adapter shows up automatically after this.

        If the base model isn't onboarded yet, return (False, hint) so
        the caller can trigger base onboarding instead of silently
        leaving a half-broken row in the DB.
        """
        base_path = self._resolve_adapter_base_path(adapter_dir)
        if not base_path:
            return False, (
                "adapter_config.json is missing or does not name a base "
                "model. The adapter directory looks corrupted."
            )

        # The base might be a HuggingFace id ('google/gemma-4-E4B-it')
        # or a local path. If it's a relative HF id, try resolving it
        # against LLM/models/<sanitized> first.
        from pathlib import Path as _P
        base_p = _P(base_path)
        if not base_p.exists():
            sanitised = base_path.replace("/", "__")
            candidate = self.root / "models" / sanitised
            if candidate.exists():
                base_path = str(candidate)
            else:
                return False, (
                    f"Base model '{base_path}' is not present locally "
                    f"under {self.root / 'models'}. Onboard the base "
                    "model first (Models page → Browse → Download → "
                    "Onboard), then re-click Use here."
                )

        # Locate an existing onboarding row for this base — we need its
        # env so the adapter inherits a working runtime. The matcher
        # is tolerant (see _find_base_onboarding for details), but if
        # it still misses, we don't want to dead-end the user: the
        # adapter is on disk, valid, and the user clearly trained it
        # against a real base. Synthesize a usable row from the
        # adapter's own training_info.json (written by finetune.py on
        # success) and proceed with registration.
        base_row = self._find_base_onboarding(base_path)
        synth_used = False
        if base_row is None:
            try:
                base_row = self._synthesize_base_row_from_adapter(adapter_dir, base_path)
            except Exception:
                base_row = None
            if base_row is not None:
                synth_used = True
                try:
                    self._log_to_app_log(
                        "[base-match] no row matched; synthesised one from adapter "
                        f"training_info.json (env_key={base_row.get('env_key')!r})."
                    )
                except Exception:
                    pass
        if base_row is None:
            self._last_missing_base_path = str(base_path)
            try:
                self._last_missing_base_dirname = Path(base_path).name
            except Exception:
                self._last_missing_base_dirname = None
            return False, (
                "The base model isn't registered yet.\n\n"
                f"Base: {base_path}\n\n"
                "Click 'Open Models' below to jump to the Downloaded tab "
                "where you can Onboard it, then come back and try again."
            )
        # Clear any prior 'missing base' breadcrumbs.
        self._last_missing_base_path = None
        self._last_missing_base_dirname = None
        # If the row we got was synthesised (no real onboarding row in
        # either table), record a hint in the success message so the
        # user knows the registration succeeded but health may be
        # incomplete until the base goes through proper onboarding.
        synth_note = (
            "" if not synth_used
            else " (Note: base wasn't in the registry — registered the "
                 "adapter using the training metadata. Onboard the base "
                 "from the Models tab if you want a fully-verified env.)"
        )

        # Upsert the adapter row.
        try:
            # Use the global StateStore singleton — see
            # _find_base_onboarding for the same fix; ``StateStore()``
            # with no args fails because the constructor requires
            # ``db_path``.
            from core.state_store import get_state_store
            ss = get_state_store()
            ss.upsert_onboarding(
                model_id=f"tuned__{name}",
                base_model_path=str(base_path),
                adapter_dir=str(adapter_dir),
                env_key=base_row.get("env_key"),
                backend=base_row.get("backend"),
                accelerator=base_row.get("accelerator"),
                status="READY",
            )
        except Exception as e:
            return False, f"State-store write failed: {e}"

        # Wire the adapter into llm_backends.yaml so it SHARES the
        # base's port + server process. See _wire_adapter_into_yaml
        # for the full design rationale (one server hosts base+adapter,
        # per-request ``adapter`` flag toggles the LoRA layer).
        try:
            self._wire_adapter_into_yaml(name, str(base_path), str(adapter_dir), base_row)
        except Exception as exc:
            try:
                self._log_to_app_log(
                    f"[adapter-wire] could not wire {name} into "
                    f"llm_backends.yaml: {exc!r}"
                )
            except Exception:
                pass

        # Drop the sentinel so the card flips to the green badge.
        try:
            (adapter_dir / ".onboarded").touch(exist_ok=True)
        except Exception:
            pass
        return True, "Adapter is now ready for chat." + synth_note

    def _wire_adapter_into_yaml(
        self,
        adapter_name: str,
        base_path: str,
        adapter_dir: str,
        base_row: Dict[str, Any],
    ) -> None:
        """Make the freshly-registered adapter share the base's server.

        Edits ``configs/llm_backends.yaml`` so:
          1. The BASE entry (created if it doesn't exist) carries
             ``adapter_dir = <this adapter>`` — the server will load
             base + adapter at startup.
          2. The ADAPTER entry (``tuned__<name>``) reuses the SAME
             ``port`` as the base. Both entries resolve to the same
             backend process, so the Test page can pick Model A
             (base) and Model B (adapter) without spawning a second
             16 GB server. Per-request ``adapter`` field on chat
             calls flips the LoRA layer on/off via PEFT's
             ``enable_adapter_layers()`` / ``disable_adapter_layers()``.

        Caveats / current limits:
          - One adapter per base at a time. Switching to a different
            adapter requires re-registering and bouncing the server.
            Multi-adapter-per-base would need a list of paths and
            per-request ``adapter_name`` selection — future work.
          - If the base server is already running when the adapter is
            registered, the running process won't gain the adapter
            until the user stops + starts it. The next ``Use in Chat``
            click will write the YAML correctly; user just needs one
            server bounce.
        """
        from pathlib import Path as _P
        config_path = self.root / "configs" / "llm_backends.yaml"
        try:
            import yaml as _yaml
        except ImportError:
            self._log_to_app_log(
                "[adapter-wire] PyYAML not available; cannot edit llm_backends.yaml"
            )
            return

        cfg: Dict[str, Any] = {}
        try:
            if config_path.exists():
                with open(config_path, "r", encoding="utf-8") as f:
                    cfg = _yaml.safe_load(f) or {}
        except Exception as exc:
            self._log_to_app_log(f"[adapter-wire] failed to read YAML: {exc!r}")
            return
        if not isinstance(cfg, dict):
            cfg = {}
        models = cfg.setdefault("models", {})

        # 1. Find or create the BASE entry. We match by base_path
        # (case-insensitive, slash-normalized) since the YAML stores
        # ``base_model`` as a path string and the comparison must be
        # tolerant of Windows / POSIX separator differences.
        def _norm(p: str) -> str:
            return str(p).replace("\\", "/").lower().rstrip("/")

        base_norm = _norm(base_path)
        base_entry = None
        base_id = None
        for mid, ent in list(models.items()):
            if not isinstance(ent, dict):
                continue
            if _norm(str(ent.get("base_model", ""))) == base_norm and not ent.get("adapter_dir"):
                base_entry = ent
                base_id = mid
                break
        # If no base-only entry exists, just take the first one that
        # references this base_model (we'll patch it to carry the adapter).
        if base_entry is None:
            for mid, ent in list(models.items()):
                if not isinstance(ent, dict):
                    continue
                if _norm(str(ent.get("base_model", ""))) == base_norm:
                    base_entry = ent
                    base_id = mid
                    break

        # If still none, synthesize a base entry.
        if base_entry is None:
            from core.model_id_resolver import derive_from_model_path
            try:
                canonical = derive_from_model_path(base_path)
                base_id = canonical or _P(base_path).name.replace("__", "/")
            except Exception:
                base_id = _P(base_path).name.replace("__", "/")
            # Allocate a port — first free in the 10500+ range.
            used_ports = {
                int(v.get("port", 0))
                for v in models.values()
                if isinstance(v, dict) and v.get("port") is not None
            }
            preferred_port = 10500
            while preferred_port in used_ports:
                preferred_port += 1
            base_entry = {
                "base_model": base_path,
                "adapter_dir": None,
                "model_type": "instruct",
                "port": preferred_port,
                "use_4bit": True,
                "system_prompt": "",
            }
            models[base_id] = base_entry

        # 2. Patch base entry: load with the adapter on startup. Only
        # overwrite if blank/None so a user who manually set a
        # different adapter (rare but possible) isn't silently
        # overridden.
        if not base_entry.get("adapter_dir"):
            base_entry["adapter_dir"] = adapter_dir
            self._log_to_app_log(
                f"[adapter-wire] patched base entry '{base_id}' to load "
                f"adapter_dir={adapter_dir}"
            )

        # 3. Add/refresh the adapter entry — same port as base.
        adapter_id = f"tuned__{adapter_name}"
        adapter_entry = models.get(adapter_id, {}) or {}
        adapter_entry.update({
            "base_model": base_path,
            "adapter_dir": adapter_dir,
            "model_type": base_entry.get("model_type", "instruct"),
            # Same port — chat requests for this model_id route to
            # the base's server process. The per-request ``adapter``
            # field on the chat call enables/disables the LoRA layer.
            "port": int(base_entry.get("port", 10500)),
            "use_4bit": base_entry.get("use_4bit", True),
            "system_prompt": adapter_entry.get("system_prompt", ""),
            # Mark this entry as adapter-only so the launcher knows
            # NOT to start a second server for it. The base entry is
            # what spawns the process.
            "shares_server_with": base_id,
        })
        models[adapter_id] = adapter_entry

        # Write back.
        try:
            with open(config_path, "w", encoding="utf-8") as f:
                _yaml.safe_dump(cfg, f, sort_keys=False, default_flow_style=False)
        except Exception as exc:
            self._log_to_app_log(f"[adapter-wire] write failed: {exc!r}")
            return

        # Sync the runtime manager so subsequent launches see the new entries.
        try:
            from core.llm_server_manager import get_global_server_manager
            get_global_server_manager()._load_config()
        except Exception:
            pass

        self._log_to_app_log(
            f"[adapter-wire] {adapter_id} now shares port "
            f"{adapter_entry['port']} with base '{base_id}'."
        )

    def _refresh_chat_pickers(self) -> None:
        """Re-populate every chat-tab model dropdown so a freshly
        registered adapter shows up immediately. Best-effort — silently
        ignores pickers that don't exist yet (lazy-loaded sub-tabs).
        """
        for fn_name in (
            "_load_tool_chat_models",
            "_load_chat_models",
            "_load_test_models",
            "_load_m2m_models",
            "_refresh_chat_model_picker",
        ):
            fn = getattr(self, fn_name, None)
            if callable(fn):
                try:
                    fn()
                except Exception:
                    pass

    def _navigate_to_chat_tab(self) -> None:
        """Switch the main tab bar to the Test tab (which hosts Chat /
        Tool Chat sub-pages). Walks the tab labels because the tab index
        isn't stored as a named attribute.
        """
        try:
            for i in range(self.tabs.count()):
                if self.tabs.tabText(i).strip().lower() in ("test", "🧪 test"):
                    self.tabs.setCurrentIndex(i)
                    return
        except Exception:
            pass

    def _navigate_to_models_for_onboarding(self, base_path_or_id: str) -> None:
        """Switch to Models → Downloaded so the user can Onboard the base.

        Called from the "base not registered" dialog on the tuned-adapter
        card. The Downloaded sub-tab is where the Onboard button lives
        (the ``Browse`` sub-tab is for searching new models to download).
        Also runs the existing models refresh so freshly-installed bases
        show up immediately.
        """
        try:
            # Outer tabs — switch to Models (label-walked, same pattern
            # as _navigate_to_chat_tab so renames don't break us).
            for i in range(self.tabs.count()):
                if "models" in self.tabs.tabText(i).strip().lower():
                    self.tabs.setCurrentIndex(i)
                    break
        except Exception:
            pass
        # Inner tabs — switch to the Downloaded sub-tab. The button at
        # main.py:6756 is wired to ``models_content_tabs.setCurrentIndex(1)``;
        # we mirror that here.
        try:
            if hasattr(self, "models_content_tabs"):
                self.models_content_tabs.setCurrentIndex(1)
        except Exception:
            pass
        # Best-effort highlight: refresh the downloaded list so the
        # base appears, and emit one log line so the user knows what to
        # click next.
        try:
            for fn_name in ("_refresh_downloaded_models", "_refresh_models",
                            "_load_downloaded_models"):
                fn = getattr(self, fn_name, None)
                if callable(fn):
                    fn()
                    break
        except Exception:
            pass
        try:
            self._log_to_app_log(
                f"[GUIDE] Navigated to Models → Downloaded. Find '"
                f"{base_path_or_id}' in the list and click Onboard, "
                "then return to the Tuned tab and click Use in Chat."
            )
        except Exception:
            pass

    # ------------------------------------------------------------------
    # Tuned-model card actions (Use / Onboard / Delete)
    # ------------------------------------------------------------------

    def _use_tuned_model(self, name: str, path: "Path") -> None:
        """Make this adapter usable in chat and route the user there.

        Flow:
          1. Register the adapter via _register_tuned_adapter (looks
             up the base's env_key/backend/accelerator and writes a
             READY row pointing at the adapter dir).
          2. Refresh every chat-tab dropdown so the new entry appears.
          3. Switch the main tab bar to the Test/Chat tab.
        Failure path: show ONE actionable dialog explaining what's
        missing (no more "the adapter at PATH will be applied
        automatically" runaround).
        """
        ok, msg = self._register_tuned_adapter(name, path)
        if not ok:
            # Actionable failure dialog. When the missing thing is the
            # base model, give the user a one-click jump to the Models
            # tab's Downloaded sub-tab (where the Onboard button lives)
            # rather than expecting them to navigate manually. We only
            # show that path when we actually have a missing base to
            # point at — for other failure shapes (corrupt
            # adapter_config.json, DB write error) the standard warning
            # is right.
            missing_base = getattr(self, "_last_missing_base_path", None)
            if missing_base:
                # QMessageBox auto-detects text format from content. The
                # informative text starts with several plain-text lines
                # (\n\n separators), so auto-detection picked PLAIN and
                # any HTML tags came through literally. Force RichText
                # AND format the entire body as HTML so it renders
                # consistently — no more raw <br>/<i> bleeding into the
                # UI.
                box = QMessageBox(self)
                box.setIcon(QMessageBox.Warning)
                box.setWindowTitle("Use Tuned Model — base not registered")
                box.setTextFormat(Qt.RichText)
                box.setText(
                    "<b>The base model for this adapter isn't registered yet.</b>"
                )
                # Escape the path for HTML safety (backslashes are fine,
                # but if a path ever contains <, >, or & this prevents
                # mojibake). Use a fixed-width inline so the path stays
                # visually distinct from the surrounding prose.
                from html import escape as _h
                box.setInformativeText(
                    f"<p>Base:&nbsp;<code>{_h(missing_base)}</code></p>"
                    "<p>Click <b>Open Models</b> below to jump to the "
                    "Downloaded tab where you can Onboard it, then come "
                    "back and try again.</p>"
                    "<p><i>Tip: once the base is registered, your adapter "
                    "automatically inherits its environment — you only "
                    "need to click <b>Use in Chat</b> again.</i></p>"
                )
                open_btn = box.addButton("📁  Open Models", QMessageBox.AcceptRole)
                box.addButton("Cancel", QMessageBox.RejectRole)
                box.exec()
                if box.clickedButton() is open_btn:
                    self._navigate_to_models_for_onboarding(missing_base)
                # Reset breadcrumbs after the dialog closes.
                self._last_missing_base_path = None
                self._last_missing_base_dirname = None
                return
            # Generic failure path — keep the original concise warning.
            QMessageBox.warning(self, "Use Tuned Model", msg)
            return

        self._refresh_chat_pickers()
        self._refresh_tuned_models()  # flip ONBOARDED badge
        self._navigate_to_chat_tab()

    def _onboard_tuned_model(self, name: str, path: "Path") -> None:
        """Same registration logic as Use, minus the tab navigation —
        this is the explicit 'prepare it for use, but don't take me
        to chat yet' button.
        """
        ok, msg = self._register_tuned_adapter(name, path)
        if not ok:
            QMessageBox.warning(self, "Onboarding Failed", msg)
            return
        self._refresh_chat_pickers()
        self._refresh_tuned_models()
        QMessageBox.information(
            self,
            "Tuned Model Ready",
            f"'{name}' is now onboarded and will appear in the chat "
            f"model picker on the Test tab.",
        )

    def _delete_tuned_model(self, name: str, path: "Path") -> None:
        """Confirm and delete a fine-tuned adapter directory."""
        try:
            ans = QMessageBox.question(
                self,
                "Delete Tuned Model?",
                f"Permanently delete '{name}'?\n\nThis removes the entire "
                f"directory:\n{path}\n\nThis cannot be undone.",
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.No,
            )
            if ans != QMessageBox.Yes:
                return
            import shutil
            shutil.rmtree(path, ignore_errors=False)
            self._refresh_tuned_models()
        except Exception as e:
            QMessageBox.warning(
                self,
                "Delete Failed",
                f"Could not delete '{name}':\n\n{e}",
            )

    def _open_path_in_explorer(self, path: str) -> None:
        """Reveal a folder in the OS file manager (Windows / macOS / Linux)."""
        try:
            from PySide6.QtGui import QDesktopServices
            from PySide6.QtCore import QUrl
            QDesktopServices.openUrl(QUrl.fromLocalFile(path))
        except Exception:
            pass

    def _update_progress_bar_text(self, progress_bar, prefix: str, status_msg: str) -> None:
        """Show GB/GB details in progress bars when status includes them."""
        try:
            if not progress_bar:
                return
            msg = (status_msg or "").strip()
            details = ""
            if " | " in msg:
                details = msg.split(" | ", 1)[1].strip()
            if details:
                progress_bar.setFormat(f"{prefix}... %p% | {details}")
            else:
                progress_bar.setFormat(f"{prefix}... %p%")
        except Exception:
            pass

    def _fmt_size_short(self, size_bytes: Optional[int]) -> str:
        """Format bytes for compact UI labels."""
        try:
            n = int(size_bytes or 0)
        except Exception:
            n = 0
        if n <= 0:
            return "unknown"
        units = ["B", "KB", "MB", "GB", "TB"]
        i = 0
        v = float(n)
        while v >= 1024.0 and i < len(units) - 1:
            v /= 1024.0
            i += 1
        if i <= 1:
            return f"{int(v)} {units[i]}"
        return f"{v:.2f} {units[i]}"

    def _guess_gguf_quant(self, filename: str) -> str:
        """Best-effort quant tag extraction from GGUF filename."""
        try:
            import re
            base = Path(filename).name
            m = re.search(r"(IQ\d+_[A-Z0-9]+|Q\d+_[A-Z0-9]+|Q\d+_[0-9A-Z]+|Q\d+|F16|F32)", base, flags=re.IGNORECASE)
            if m:
                return m.group(1).upper()
        except Exception:
            pass
        return "unknown"

    def _gguf_quant_weight(self, quant: str) -> int:
        """Heuristic weight ranking for GGUF quants (higher = heavier)."""
        q = (quant or "").upper()
        if "F32" in q:
            return 100
        if "F16" in q:
            return 95
        if q.startswith("Q8") or "Q8_" in q:
            return 80
        if q.startswith("Q6") or "Q6_" in q:
            return 65
        if q.startswith("Q5") or "Q5_" in q:
            return 55
        if q.startswith("Q4") or "Q4_" in q:
            return 45
        if q.startswith("IQ4"):
            return 42
        if q.startswith("Q3") or "Q3_" in q:
            return 35
        if q.startswith("IQ3"):
            return 33
        if q.startswith("Q2") or "Q2_" in q:
            return 25
        if q.startswith("IQ2"):
            return 23
        return 40

    def _prompt_gguf_variant_selection(self, model_id: str, token: Optional[str]) -> tuple[bool, Optional[List[str]]]:
        """
        Ask user to choose GGUF variant when repo exposes multiple .gguf files.
        Returns: (proceed, allow_patterns). allow_patterns=None means download all files.
        Uses index-based mapping and shows FITS/TOO LARGE by VRAM; no silent download-all on error.
        """
        from core.model_file_utils import list_repo_files
        try:
            siblings = list_repo_files(model_id, token=token)
        except Exception as e:
            self._log_models(f"[WARNING] Could not list repo files for GGUF selection: {e}")
            reply = QMessageBox.question(
                self,
                "GGUF selection unavailable",
                f"Could not load the list of GGUF files for this model.\n\nError: {e}\n\n"
                "Do you want to download all files anyway?",
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.No,
            )
            if reply == QMessageBox.Yes:
                self._log_models("User chose to download all files after listing failure.")
                return True, None
            self._log_models("User cancelled download after listing failure.")
            return False, None

        gguf_rows = []
        for s in siblings:
            name = s.get("rfilename", "")
            if isinstance(name, str) and name.lower().endswith(".gguf"):
                quant = self._guess_gguf_quant(name)
                gguf_rows.append((name, int(s.get("size", 0) or 0), quant))
        if len(gguf_rows) <= 1:
            self._log_models("Single or no GGUF variant; downloading all files.")
            return True, None

        # Sort strictly from heaviest to lightest.
        # Known sizes use byte size; unknown sizes fall back to quant heaviness.
        gguf_rows.sort(
            key=lambda x: (x[1] > 0, x[1] if x[1] > 0 else self._gguf_quant_weight(x[2])),
            reverse=True,
        )
        vram_gb = float(getattr(self, "user_vram_gb", 0) or 0)
        if vram_gb <= 0:
            # Avoid "all red" when VRAM detection fails; use a practical fallback.
            vram_gb = 8.0
            self._log_models("[WARNING] VRAM detection unavailable. Using 8 GB estimate for GGUF fit colors.")
        vram_bytes = vram_gb * (1024 ** 3)

        # Build list of (rfilename, display_label, fits_vram)
        file_list: List[str] = []
        labels_with_fit: List[Tuple[str, bool]] = []
        for name, size, quant in gguf_rows:
            file_list.append(name)
            size_str = self._fmt_size_short(size)
            # Fit rule:
            # - Known size: FITS when file size <= VRAM
            # - Unknown size: use quant heuristic; only clearly heavy quants are TOO LARGE
            if size <= 0:
                quant_weight = self._gguf_quant_weight(quant)
                fits = quant_weight < 80  # Q8/F16/F32 default to red; others green
                prefix = "[FITS]" if fits else "[TOO LARGE]"
            else:
                fits = size <= vram_bytes
                prefix = "[FITS]" if fits else "[TOO LARGE]"
            labels_with_fit.append((f"{prefix}  {Path(name).name}  [{quant}]  ({size_str})", fits))

        # Custom dialog with colorized multi-select list.
        dialog = QDialog(self)
        dialog.setWindowTitle("Choose GGUF quantization")
        layout = QVBoxLayout(dialog)
        layout.addWidget(QLabel(
            f"'{model_id}' has multiple GGUF variants.\n"
            "Select one or more to download.\n"
            "Green entries are estimated to fit your VRAM. Use the first row only if you really want every GGUF variant."
        ))
        list_widget = QListWidget()
        list_widget.setMinimumHeight(280)
        list_widget.setSelectionMode(QAbstractItemView.MultiSelection)
        # First item: download all
        list_widget.addItem(QListWidgetItem("Download all GGUF variants"))
        for label_text, fits in labels_with_fit:
            item = QListWidgetItem(label_text)
            item.setForeground(QBrush(QColor("#4CAF50") if fits else QColor("#f44336")))
            list_widget.addItem(item)
        # Do not preselect multiple variants for the user.
        # Just focus the first recommended item (or "download all" as a fallback).
        focused_row = 0
        for idx, (_, fits) in enumerate(labels_with_fit, start=1):
            if fits:
                focused_row = idx
                break
        list_widget.setCurrentRow(focused_row)
        layout.addWidget(list_widget)
        buttons = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
        buttons.accepted.connect(dialog.accept)
        buttons.rejected.connect(dialog.reject)
        layout.addWidget(buttons)

        if dialog.exec() != QDialog.DialogCode.Accepted:
            self._log_models("User cancelled GGUF selection.")
            return False, None

        selected_rows = sorted({i.row() for i in list_widget.selectedIndexes()})
        if not selected_rows:
            QMessageBox.information(
                self,
                "Choose GGUF quantization",
                "Select one or more GGUF variants, or explicitly choose 'Download all GGUF variants'.",
            )
            self._log_models("User closed GGUF selection without choosing any variant.")
            return False, None
        specific_rows = [r for r in selected_rows if r > 0]
        if 0 in selected_rows and specific_rows:
            # Explicit file picks always win over accidental mixed selection with row 0.
            selected_rows = specific_rows
        elif 0 in selected_rows:
            self._log_models("User selected: download all GGUF variants.")
            return True, None
        selected_patterns: List[str] = []
        for row in selected_rows:
            if row <= 0:
                continue
            idx = row - 1
            if 0 <= idx < len(file_list):
                selected_patterns.append(file_list[idx])
        if not selected_patterns:
            self._log_models("User selection empty after filtering; defaulting to download all.")
            return True, None
        selected_names = [Path(p).name for p in selected_patterns]
        self._log_models(f"GGUF selection: downloading {len(selected_patterns)} variant(s): {selected_names}")
        return True, selected_patterns

    def _list_local_gguf_relpaths(self, model_dir: Path) -> List[str]:
        """List local GGUF files as stable relative POSIX paths."""
        rels: List[str] = []
        try:
            for f in sorted(model_dir.rglob("*.gguf")):
                try:
                    rels.append(str(f.relative_to(model_dir)).replace("\\", "/"))
                except Exception:
                    rels.append(f.name)
        except Exception:
            pass
        # Deduplicate while preserving order.
        out: List[str] = []
        seen = set()
        for r in rels:
            if r not in seen:
                seen.add(r)
                out.append(r)
        return out

    def _sync_selected_weights_marker(
        self,
        model_dir: Path,
        model_id: Optional[str] = None,
        append_patterns: Optional[List[str]] = None,
        preferred_active: Optional[str] = None,
    ) -> dict:
        """
        Merge marker allow_patterns with discovered local GGUF files and optional new patterns.
        Ensures manual GGUF files become selectable runtime variants without redownload.
        """
        marker_path = model_dir / ".selected_weights.json"
        data: dict = {}
        existing_patterns: List[str] = []
        active_variant: Optional[str] = None
        try:
            if marker_path.exists():
                data = json.loads(marker_path.read_text(encoding="utf-8")) or {}
                pats = data.get("allow_patterns")
                if isinstance(pats, list):
                    existing_patterns = [str(x) for x in pats if isinstance(x, str) and x.strip()]
                av = data.get("active_variant")
                if isinstance(av, str) and av.strip():
                    active_variant = av.strip().replace("\\", "/")
        except Exception:
            data = {}
            existing_patterns = []
            active_variant = None

        local_ggufs = self._list_local_gguf_relpaths(model_dir)
        local_set = set(local_ggufs)
        local_by_name = {Path(rel).name: rel for rel in local_ggufs}

        # Keep only patterns that currently map to existing local GGUF files.
        merged: List[str] = []
        for group in (existing_patterns, append_patterns or []):
            for p in group:
                if not isinstance(p, str):
                    continue
                pp = p.strip().replace("\\", "/")
                if not pp:
                    continue
                mapped = ""
                if pp in local_set:
                    mapped = pp
                else:
                    mapped = local_by_name.get(Path(pp).name, "")
                if mapped and mapped not in merged:
                    merged.append(mapped)

        # Ensure all discovered local GGUF files are represented.
        for rel in local_ggufs:
            if rel not in merged:
                merged.append(rel)

        chosen_active = ""
        for candidate in (preferred_active, active_variant):
            cand = str(candidate or "").strip().replace("\\", "/")
            if not cand:
                continue
            if cand in local_set:
                chosen_active = cand
                break
            by_name = local_by_name.get(Path(cand).name, "")
            if by_name:
                chosen_active = by_name
                break
        if not chosen_active:
            chosen_active = merged[0] if merged else ""
        payload = {
            "model_id": model_id or data.get("model_id") or model_dir.name.replace("__", "/"),
            "allow_patterns": merged,
            "active_variant": chosen_active,
            "saved_at": datetime.now().isoformat(),
        }
        try:
            marker_path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
        except Exception as e:
            self._log_models(f"[WARNING] Could not write selected weights marker: {e}")
        return payload

    def _prompt_manage_gguf_variant_selection(
        self,
        model_id: str,
        token: Optional[str],
        existing_patterns: List[str],
        active_variant: Optional[str] = None,
    ) -> tuple[bool, Optional[List[str]]]:
        """
        Ask user which GGUF variants should exist locally for a downloaded model.
        Selected local variants are kept, selected missing variants are downloaded, and
        deselected local variants are removed after successful updates.
        """
        from core.model_file_utils import list_repo_files
        try:
            siblings = list_repo_files(model_id, token=token)
        except Exception as e:
            QMessageBox.warning(
                self,
                "Weights",
                f"Could not load GGUF variants for '{model_id}'.\n\nError: {e}",
            )
            return False, None

        normalized_existing = []
        for rel in existing_patterns or []:
            if isinstance(rel, str) and rel.strip():
                normalized_existing.append(rel.strip().replace("\\", "/"))
        existing_set = set(normalized_existing)
        existing_names = {Path(rel).name.lower() for rel in normalized_existing}
        active_rel = str(active_variant or "").strip().replace("\\", "/")
        active_name = Path(active_rel).name.lower() if active_rel else ""

        gguf_rows: List[Tuple[str, int, str]] = []
        for s in siblings:
            name = s.get("rfilename", "")
            if not (isinstance(name, str) and name.lower().endswith(".gguf")):
                continue
            quant = self._guess_gguf_quant(name)
            gguf_rows.append((name, int(s.get("size", 0) or 0), quant))

        repo_relpaths = {name for name, _size, _quant in gguf_rows}
        repo_basenames = {Path(name).name.lower() for name in repo_relpaths}
        for rel in normalized_existing:
            if rel in repo_relpaths or Path(rel).name.lower() in repo_basenames:
                continue
            gguf_rows.append((rel, 0, self._guess_gguf_quant(rel)))

        if not gguf_rows:
            QMessageBox.information(
                self,
                "Weights",
                "No additional GGUF variants are available. All repo GGUF files already exist locally.",
            )
            return False, None

        gguf_rows.sort(
            key=lambda x: (x[1] > 0, x[1] if x[1] > 0 else self._gguf_quant_weight(x[2])),
            reverse=True,
        )
        vram_gb = float(getattr(self, "user_vram_gb", 0) or 0)
        if vram_gb <= 0:
            vram_gb = 8.0
        vram_bytes = vram_gb * (1024 ** 3)

        file_list: List[str] = []
        labels_with_fit: List[Tuple[str, bool]] = []
        for name, size, quant in gguf_rows:
            file_list.append(name)
            size_str = self._fmt_size_short(size)
            if size <= 0:
                fits = self._gguf_quant_weight(quant) < 80
            else:
                fits = size <= vram_bytes
            prefix = "[FITS]" if fits else "[TOO LARGE]"
            labels_with_fit.append((f"{prefix}  {Path(name).name}  [{quant}]  ({size_str})", fits))

        dialog = QDialog(self)
        dialog.setWindowTitle("Manage GGUF weights")
        layout = QVBoxLayout(dialog)
        layout.addWidget(QLabel(
            f"Select the GGUF variants you want to keep for '{model_id}'.\n"
            "Selected missing files will be downloaded. Deselected local files will be removed after successful updates."
        ))
        list_widget = QListWidget()
        list_widget.setMinimumHeight(280)
        list_widget.setSelectionMode(QAbstractItemView.MultiSelection)
        list_widget.addItem(QListWidgetItem("Select all GGUF variants"))
        for idx, (name, _size, _quant) in enumerate(gguf_rows):
            label_text, fits = labels_with_fit[idx]
            is_local = name in existing_set or Path(name).name.lower() in existing_names
            is_active = (
                active_rel == name
                or (active_name and Path(name).name.lower() == active_name)
            )
            state = "LOCAL" if is_local else "MISSING"
            active_suffix = "  [ACTIVE]" if is_active else ""
            item = QListWidgetItem(f"[{state}] {label_text}{active_suffix}")
            item.setForeground(QBrush(QColor("#4CAF50") if fits else QColor("#f44336")))
            list_widget.addItem(item)
            if is_local:
                list_widget.item(idx + 1).setSelected(True)

        layout.addWidget(list_widget)
        buttons = QDialogButtonBox(QDialogButtonBox.Ok | QDialogButtonBox.Cancel)
        buttons.accepted.connect(dialog.accept)
        buttons.rejected.connect(dialog.reject)
        layout.addWidget(buttons)

        if dialog.exec() != QDialog.DialogCode.Accepted:
            return False, None

        selected_rows = sorted({i.row() for i in list_widget.selectedIndexes()})
        if not selected_rows:
            reply = QMessageBox.question(
                self,
                "Remove all GGUF weights?",
                "This will remove all local GGUF weights for this model and leave it incomplete.\n\nContinue?",
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.No,
            )
            if reply == QMessageBox.Yes:
                return True, []
            return False, None
        specific_rows = [r for r in selected_rows if r > 0]
        if 0 in selected_rows and specific_rows:
            selected_rows = specific_rows
        elif 0 in selected_rows:
            return True, list(file_list)

        selected_patterns: List[str] = []
        for row in selected_rows:
            if row <= 0:
                continue
            idx = row - 1
            if 0 <= idx < len(file_list):
                selected_patterns.append(file_list[idx])
        if not selected_patterns:
            return False, None
        return True, selected_patterns

    def _delete_local_gguf_variants(self, model_dir: Path, relpaths: List[str]) -> Tuple[List[str], List[str]]:
        """Delete specific local GGUF variants and prune now-empty parent folders."""
        root = Path(model_dir)
        deleted: List[str] = []
        failed: List[str] = []
        for rel in relpaths or []:
            normalized = str(rel or "").strip().replace("\\", "/")
            if not normalized:
                continue
            target = root / normalized
            if not target.exists():
                by_name = Path(normalized).name
                matches = [p for p in root.rglob("*.gguf") if p.name == by_name]
                target = matches[0] if matches else target
            try:
                if target.exists() and target.is_file():
                    parent = target.parent
                    target.unlink()
                    while parent != root and parent.exists():
                        try:
                            next(parent.iterdir())
                            break
                        except StopIteration:
                            parent.rmdir()
                            parent = parent.parent
                deleted.append(normalized)
            except Exception:
                failed.append(normalized)
        return deleted, failed

    def _on_add_weights(self, model_path: str):
        """Manage GGUF variants for an already downloaded model directory."""
        path_obj = Path(model_path)
        if not path_obj.exists() or not path_obj.is_dir():
            QMessageBox.warning(self, "Weights", "Model folder was not found.")
            return

        status = self.model_checker.check_model(path_obj)
        model_id = status.model_id
        if not model_id:
            QMessageBox.warning(
                self,
                "Weights",
                f"Could not determine Hugging Face model ID for '{path_obj.name}'.",
            )
            return

        if model_id in self.active_downloads or f"repair_{model_id}" in self.active_downloads:
            QMessageBox.information(
                self,
                "Weights",
                f"A download/repair is already active for '{model_id}'. Please wait for it to finish.",
            )
            return

        card = None
        for c in self.downloaded_model_cards:
            if getattr(c, "model_path", "") == model_path:
                card = c
                break
        if card is None:
            self._log_models(f"Could not find model card for add-weights action: {model_path}")
            return

        add_btn = getattr(card, "add_weights_btn", None)
        if add_btn is not None:
            add_btn.setEnabled(False)
            add_btn.setText("⏳ Loading...")

        token = self._resolve_hf_token()
        try:
            marker_data = self._sync_selected_weights_marker(path_obj, model_id=model_id)
        except Exception:
            marker_data = {}

        current_local_patterns = self._list_local_gguf_relpaths(path_obj)
        active_variant = str((marker_data or {}).get("active_variant") or "").strip().replace("\\", "/")
        proceed, desired_patterns = self._prompt_manage_gguf_variant_selection(
            model_id,
            token,
            current_local_patterns,
            active_variant=active_variant,
        )
        if not proceed or desired_patterns is None:
            if add_btn is not None:
                add_btn.setEnabled(True)
                add_btn.setText("⚖️ Weights")
            return

        desired_patterns = [
            str(p).strip().replace("\\", "/")
            for p in desired_patterns
            if isinstance(p, str) and str(p).strip()
        ]
        # Deduplicate while preserving order.
        desired_patterns = list(dict.fromkeys(desired_patterns))
        current_local_set = set(current_local_patterns)
        desired_set = set(desired_patterns)
        to_add = [p for p in desired_patterns if p not in current_local_set]
        to_delete = [p for p in current_local_patterns if p not in desired_set]
        preferred_active = active_variant if active_variant in desired_set else (desired_patterns[0] if desired_patterns else "")

        if not to_add and not to_delete:
            self._log_models(f"ℹ No GGUF weight changes selected for {model_id}.")
            if add_btn is not None:
                add_btn.setEnabled(True)
                add_btn.setText("⚖️ Weights")
            return

        if to_delete:
            action_parts = []
            if to_add:
                action_parts.append(f"download {len(to_add)} new weight(s)")
            action_parts.append(f"delete {len(to_delete)} local weight(s)")
            sample = ", ".join(Path(p).name for p in to_delete[:5])
            if len(to_delete) > 5:
                sample += ", ..."
            reply = QMessageBox.question(
                self,
                "Update GGUF weights",
                f"Do you want to {', and '.join(action_parts)} for '{model_id}'?\n\n"
                f"Will delete: {sample}",
                QMessageBox.Yes | QMessageBox.No,
                QMessageBox.No,
            )
            if reply != QMessageBox.Yes:
                if add_btn is not None:
                    add_btn.setEnabled(True)
                    add_btn.setText("⚖️ Weights")
                return

        if not to_add:
            deleted, failed = self._delete_local_gguf_variants(path_obj, to_delete)
            if deleted:
                self._log_models(f"⚖️ Removed GGUF variants for {model_id}: {[Path(p).name for p in deleted]}")
            if failed:
                self._log_models(f"[WARNING] Could not remove some GGUF variants: {[Path(p).name for p in failed]}")
                QMessageBox.warning(
                    self,
                    "Weights",
                    "Some GGUF variants could not be removed. They may be in use by another process.",
                )
            try:
                self._sync_selected_weights_marker(
                    path_obj,
                    model_id=model_id,
                    append_patterns=desired_patterns,
                    preferred_active=preferred_active or None,
                )
            except Exception as e:
                self._log_models(f"[WARNING] Could not update selected weights marker: {e}")
            if add_btn is not None:
                add_btn.setEnabled(True)
                add_btn.setText("⚖️ Weights")
            QTimer.singleShot(100, self._refresh_models)
            QTimer.singleShot(150, self._refresh_locals)
            return

        selected_names = [Path(p).name for p in to_add]
        self._log_models(f"⚖️ Updating GGUF variants for {model_id}: add={selected_names}, delete={[Path(p).name for p in to_delete]}")

        progress_bar = QProgressBar()
        progress_bar.setMinimum(0)
        progress_bar.setMaximum(100)
        progress_bar.setValue(0)
        progress_bar.setTextVisible(True)
        progress_bar.setFormat("Updating weights... %p%")
        progress_bar.setStyleSheet("""
            QProgressBar {
                border: none;
                border-radius: 4px;
                text-align: center;
                background-color: #262730;
                color: white;
                font-weight: bold;
                height: 30px;
            }
            QProgressBar::chunk {
                background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
                    stop:0 #4CAF50, stop:1 #2e7d32);
                border-radius: 4px;
            }
        """)
        card.layout().addWidget(progress_bar)

        status_label = QLabel("Preparing weight update...")
        status_label.setStyleSheet("color: #ccc; font-size: 11pt; padding: 6px;")
        status_label.setWordWrap(True)
        card.layout().addWidget(status_label)

        repair_key = f"repair_{model_id}_addweights_{int(time.time() * 1000)}"
        thread = RepairThread(
            model_id,
            path_obj,
            force_fresh_only=False,
            cache_dir=self.hf_cache_dir,
            token=token,
            allow_patterns=to_add,
        )
        self.active_downloads[repair_key] = (thread, card)

        thread.progress.connect(lambda p: self._safe_progress_set(progress_bar, p))
        thread.status.connect(lambda msg: self._safe_label_set(status_label, msg))
        thread.status.connect(lambda msg: self._safe_progress_text(progress_bar, "Updating weights", msg))
        thread.finished.connect(lambda dest: self._on_repair_complete(model_id, dest, card, progress_bar, repair_key, status_label))

        if not hasattr(self, "_repair_info"):
            self._repair_info = {}
        self._repair_info[repair_key] = {
            "model_id": model_id,
            "card": card,
            "progress_bar": progress_bar,
            "status_label": status_label,
            "model_path": path_obj,
            "operation": "add_weights",
            "weights_to_delete": to_delete,
            "desired_patterns": desired_patterns,
            "preferred_active": preferred_active,
        }
        thread.error.connect(lambda err, rk=repair_key: self._handle_repair_error(rk, err))
        thread.start()
    
    def _on_search_text_changed(self, text: str):
        """Handle search text changes - return to curated view when cleared"""
        if not text.strip():
            # Search bar is empty, return to curated view
            self.browse_stack.setCurrentIndex(0)
    
    def _download_model_by_id(self, model_id: str):
        """Download a model by its ID (for search results)"""
        # Reuse the curated model download logic
        self._download_curated_model(model_id)
    
    def _download_curated_model(self, model_id: str):
        """Download a curated model in background thread with progress"""
        # Check if already downloading
        if model_id in self.active_downloads:
            self._log_models(f"⚠ {model_id} is already downloading...")
            return
        
        # Find the card (check both curated and search results)
        card = None
        for c in self.model_cards:
            if c.model_id == model_id:
                card = c
                break
        
        # If not found in curated, check search results
        if not card:
            for c in self.search_model_cards:
                if c.model_id == model_id:
                    card = c
                    break
        
        if not card:
            self._log_models(f"❌ Card not found for {model_id}")
            return
        
        # If this repo is gated/private and no token is set, show clear guidance and abort
        if getattr(card, "requires_token", False) and not self._resolve_hf_token():
            self._show_gated_no_token_dialog(model_id, parent_win=self)
            return

        token = self._resolve_hf_token()
        proceed, selected_patterns = self._prompt_gguf_variant_selection(model_id, token)
        if not proceed:
            self._log_models(f"Cancelled download for {model_id}")
            return
        
        # IMMEDIATELY disable button to prevent double-clicks
        card.download_btn.setEnabled(False)
        card.download_btn.setText("⏳ Starting...")

        # Pink-blink + pin-to-top: mark this card as actively downloading
        # and reorder the curated grid so it sits at (0, 0).
        try:
            card.set_downloading(True)
            self._reorder_curated_grid()
        except Exception:
            pass

        self._log_models(f"📥 Downloading {model_id}...")
        if selected_patterns:
            self._log_models(f"  Selected weights: {[Path(p).name for p in selected_patterns]}")
        else:
            self._log_models("  Downloading all files.")
        target = Path(self.hf_target_dir.text().strip())
        # Ensure destination folder exists immediately so it appears in Downloaded tab during download
        try:
            model_slug = model_id.replace("/", "__")
            dest_dir = target / model_slug
            dest_dir.mkdir(parents=True, exist_ok=True)
            # Marker helps distinguish "created but empty" vs real files during refresh
            try:
                (dest_dir / ".download_in_progress").write_text("1", encoding="utf-8")
            except Exception:
                pass
            # Persist selected weights so repair/restart keeps the same subset.
            try:
                selection_marker = dest_dir / ".selected_weights.json"
                if selected_patterns:
                    payload = {
                        "model_id": model_id,
                        "allow_patterns": selected_patterns,
                        "active_variant": selected_patterns[0],
                        "saved_at": datetime.now().isoformat(),
                    }
                    selection_marker.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
                elif selection_marker.exists():
                    selection_marker.unlink()
            except Exception as e:
                self._log_models(f"[WARNING] Could not persist selected weights marker: {e}")
        except Exception as e:
            self._log_models(f"[WARNING] Could not pre-create destination folder: {e}")
        
        # Hide button after a moment (let user see "Starting...")
        QTimer.singleShot(500, lambda: card.download_btn.setVisible(False))
        
        # Create progress bar
        progress_bar = QProgressBar()
        progress_bar.setMinimum(0)
        progress_bar.setMaximum(100)
        progress_bar.setValue(0)
        progress_bar.setTextVisible(True)
        progress_bar.setFormat("Downloading... %p%")
        progress_bar.setStyleSheet("""
            QProgressBar {
                border: none;
                border-radius: 4px;
                text-align: center;
                background-color: #262730;
                color: white;
                font-weight: bold;
                height: 30px;
            }
            QProgressBar::chunk {
                background: qlineargradient(x1:0, y1:0, x2:1, y2:0, 
                    stop:0 #667eea, stop:1 #764ba2);
                border-radius: 4px;
            }
        """)
        
        # Add progress bar to card layout
        card.layout().addWidget(progress_bar)
        
        # Create download thread with central cache
        thread = DownloadThread(
            model_id,
            target,
            cache_dir=self.hf_cache_dir,
            token=token,
            allow_patterns=selected_patterns,
        )
        
        # Mark as active BEFORE starting
        self.active_downloads[model_id] = (thread, card)
        
        # Connect signals (progress on card and in status log so it stays visible)
        thread.progress.connect(lambda p: progress_bar.setValue(p))
        thread.status.connect(lambda msg: self._update_progress_bar_text(progress_bar, "Downloading", msg))
        thread.status.connect(lambda msg: self._log_models(f"  {msg}"))
        thread.finished.connect(lambda dest: self._on_download_complete(model_id, dest, card, progress_bar))
        thread.error.connect(lambda err: self._on_download_error(model_id, err, card, progress_bar))
        
        # Start download
        thread.start()

    def _reorder_curated_grid(self) -> None:
        """Re-pack ``self.curated_layout`` so downloading cards sit at the top.

        Preserves the existing relative order within each bucket (the list
        was already sorted green → red on initial build). Removing widgets
        from a QGridLayout requires takeAt + setParent(None) — Qt won't
        repaint properly otherwise — so we drain the grid first, then
        re-add in the new order. 2 columns to match the initial pack.
        """
        if not hasattr(self, "curated_layout") or not hasattr(self, "model_cards"):
            return
        # Drain the grid without destroying widgets.
        while self.curated_layout.count():
            item = self.curated_layout.takeAt(0)
            w = item.widget() if item else None
            if w is not None:
                w.setParent(None)

        downloading = [c for c in self.model_cards if getattr(c, "is_downloading", False)]
        idle = [c for c in self.model_cards if not getattr(c, "is_downloading", False)]
        max_cols = 2
        for i, c in enumerate(downloading + idle):
            r, col = divmod(i, max_cols)
            self.curated_layout.addWidget(c, r, col)
            c.show()

    def _on_download_complete(self, model_id: str, dest: str, card, progress_bar):
        """Handle successful download"""
        self._log_models(f"✓ Downloaded to: {dest}")
        dest_path = Path(dest)

        # Remove any in-progress marker
        try:
            marker = dest_path / ".download_in_progress"
            if marker.exists():
                marker.unlink()
        except Exception:
            pass
        
        def _has_real_files_fast(root: Path) -> bool:
            # Fast early-exit scan (avoid blocking UI with rglob)
            import os
            stack = [root]
            while stack:
                d = stack.pop()
                try:
                    with os.scandir(d) as it:
                        for entry in it:
                            name = entry.name
                            if name.startswith(".") or name == "__pycache__":
                                continue
                            if entry.is_file():
                                if name.endswith(".lock") or name.endswith(".incomplete") or name == ".download_in_progress":
                                    continue
                                return True
                            if entry.is_dir():
                                stack.append(Path(entry.path))
                except Exception:
                    continue
            return False

        # Verify download actually has files (fast)
        has_files = False
        try:
            has_files = dest_path.exists() and dest_path.is_dir() and _has_real_files_fast(dest_path)
        except Exception as e:
            self._log_models(f"DEBUG: Error checking files: {e}")
        
        if not has_files:
            self._log_models(f"⚠️ WARNING: Download completed but no files found in {dest}")
            # Don't mark as complete - let repair handle it
        else:
            # Auto-start onboarding in the background (silent) so badges/env association update
            try:
                entry = self.state_store.get_onboarding(model_id)
                status = (entry.get("status") if entry else None) or "NEW"
                # Only kick onboarding if not already READY or BUILDING
                if status not in ("READY", "BUILDING"):
                    self._start_model_onboarding_silent(str(dest_path), model_id)
            except Exception as e:
                self._log_models(f"[WARNING] Could not start onboarding automatically: {e}")
        
        # Clean up thread first
        if model_id in self.active_downloads:
            thread, _ = self.active_downloads[model_id]
            if thread.isRunning():
                thread.quit()
                thread.wait()
            del self.active_downloads[model_id]

        # Remove progress bar
        if progress_bar:
            progress_bar.setVisible(False)
            progress_bar.deleteLater()

        # Stop the pink-blink ring on the card.
        try:
            if card is not None:
                card.set_downloading(False)
        except Exception:
            pass

        # Don't hide the card - let _refresh_models handle showing it as downloaded
        
        # Refresh both downloaded models list AND train dropdown
        # Use QTimer to ensure download thread is fully cleaned up first
        def refresh_after_download():
            self._refresh_models()  # This will update the card with correct status
            self._refresh_locals()  # This updates the Train tab dropdown
        
        QTimer.singleShot(500, refresh_after_download)
    
