    def _start_model_onboarding(self, model_path: str, model_id: str):
        """Start onboarding for a model"""
        return self._start_model_onboarding_impl(model_path=model_path, model_id=model_id, focus_ui=True)

    def _start_model_onboarding_silent(self, model_path: str, model_id: str):
        """Start onboarding for a model without forcing UI tab switches."""
        return self._start_model_onboarding_impl(model_path=model_path, model_id=model_id, focus_ui=False)

    def _start_model_onboarding_impl(self, model_path: str, model_id: str, focus_ui: bool):
        """Internal onboarding starter (optionally focuses Environment tab)."""
        try:
            # Validate inputs
            if not model_path:
                raise ValueError("model_path is required")
            if not Path(model_path).exists():
                raise ValueError(f"Model path does not exist: {model_path}")
            
            # IMPORTANT: Onboarding status/badges/Test-tab use HF-style model_id keys.
            # Do NOT use _resolve_model_id_from_path() here (it may create synthetic IDs for servers).
            extracted = None
            try:
                extracted = self._extract_model_id_from_path(model_path)
            except Exception as e:
                import logging
                logging.warning(f"Could not extract model_id from path {model_path}: {e}")
                extracted = None
            resolved_model_id = extracted or model_id
            if not resolved_model_id:
                resolved_model_id = model_id
            
            # Check if already BUILDING to prevent duplicate starts
            from core.model_onboarding import get_onboarding_service
            onboarding = get_onboarding_service()
            current_status = onboarding.get_onboarding_status(resolved_model_id)
            if current_status == "BUILDING":
                if hasattr(self, 'onboarding_log_display'):
                    self.onboarding_log_display.appendPlainText(f"⚠️ Onboarding already in progress for {resolved_model_id}\n")
                return
            
            if focus_ui:
                # Ensure we're on Environment tab and prevent tab switching during onboarding
                if hasattr(self, 'downloaded_details_tabs'):
                    # Block signals to prevent Info tab from loading
                    self.downloaded_details_tabs.blockSignals(True)
                    self.downloaded_details_tabs.setCurrentIndex(2)  # Force Environment tab
                    self.downloaded_details_tabs.blockSignals(False)
            
            if focus_ui:
                # Clear log
                if hasattr(self, 'onboarding_log_display'):
                    self.onboarding_log_display.clear()
                    self.onboarding_log_display.appendPlainText(f"Starting onboarding for: {resolved_model_id}\n")
                    self.onboarding_log_display.appendPlainText(f"Model path: {model_path}\n\n")
                if hasattr(self, "onboarding_progress_bar"):
                    self.onboarding_progress_bar.setRange(0, 100)
                    self.onboarding_progress_bar.setValue(5)
                    self.onboarding_progress_bar.setFormat("Onboarding: starting...")
                    # Start lightweight heartbeat so UI doesn't look stuck when logs are sparse.
                    if hasattr(self, "_onboarding_progress_timer") and self._onboarding_progress_timer:
                        try:
                            self._onboarding_progress_timer.stop()
                        except Exception:
                            pass
                    self._onboarding_progress_timer = QTimer(self)
                    self._onboarding_progress_timer.timeout.connect(self._tick_onboarding_progress_bar)
                    self._onboarding_progress_timer.start(900)

            # Normalize stale marker entries before integrity checks run in onboarding.
            try:
                self._sync_selected_weights_marker(Path(model_path), model_id=resolved_model_id)
            except Exception:
                pass
            
            # Create onboarding thread
            onboarding_thread = OnboardingThread(resolved_model_id, model_path, None)
            
            # Connect signals
            onboarding_thread.progress.connect(lambda msg: self._on_onboarding_progress(msg))
            onboarding_thread.finished.connect(lambda result: self._on_onboarding_finished(resolved_model_id, result))
            onboarding_thread.error.connect(lambda err: self._on_onboarding_error(resolved_model_id, err))
            
            # Start thread
            onboarding_thread.start()
            
            # Store reference
            if not hasattr(self, '_onboarding_threads'):
                self._onboarding_threads = {}
            self._onboarding_threads[resolved_model_id] = onboarding_thread

            # Nudge UI to reflect BUILDING quickly (cards are otherwise stale until completion).
            try:
                QTimer.singleShot(500, lambda mid=resolved_model_id: self._refresh_models())
            except Exception:
                pass
            
            if focus_ui and hasattr(self, 'onboarding_log_display'):
                self.onboarding_log_display.appendPlainText("✓ Onboarding thread started\n")
        except Exception as e:
            import traceback
            error_msg = f"Failed to start onboarding: {e}\n{traceback.format_exc()}"
            if hasattr(self, 'onboarding_log_display'):
                self.onboarding_log_display.appendPlainText(f"❌ {error_msg}\n")
            else:
                import logging
                logging.error(error_msg)
            # Also show error dialog
            QMessageBox.critical(self, "Onboarding Error", f"Failed to start onboarding:\n{error_msg}")
    
    def _on_onboarding_progress(self, msg: str):
        """Handle onboarding progress updates"""
        self._append_terminal(msg, source="onboarding")
        if hasattr(self, 'onboarding_log_display'):
            self.onboarding_log_display.appendPlainText(msg)
            # Auto-scroll to bottom
            scrollbar = self.onboarding_log_display.verticalScrollBar()
            scrollbar.setValue(scrollbar.maximum())
        if hasattr(self, "onboarding_progress_bar"):
            import re
            m = re.search(r"(\d{1,3})\s*%", msg or "")
            if m:
                p = max(0, min(100, int(m.group(1))))
                self.onboarding_progress_bar.setRange(0, 100)
                self.onboarding_progress_bar.setValue(p)
                self.onboarding_progress_bar.setFormat(f"Onboarding: {p}%")
            else:
                # Keep progress moving even when log lines don't include numeric percentages.
                curr = int(self.onboarding_progress_bar.value())
                if curr < 95:
                    curr = min(95, curr + 3)
                    self.onboarding_progress_bar.setRange(0, 100)
                    self.onboarding_progress_bar.setValue(curr)
                    self.onboarding_progress_bar.setFormat(f"Onboarding: {curr}%")

    def _tick_onboarding_progress_bar(self):
        """Timer-based progress heartbeat for sparse-log onboarding steps."""
        if not hasattr(self, "onboarding_progress_bar"):
            return
        try:
            curr = int(self.onboarding_progress_bar.value())
            if curr < 90:
                curr = min(90, curr + 1)
                self.onboarding_progress_bar.setRange(0, 100)
                self.onboarding_progress_bar.setValue(curr)
                self.onboarding_progress_bar.setFormat(f"Onboarding: {curr}%")
        except Exception:
            pass
    
    def _on_onboarding_finished(self, model_id: str, result: dict):
        """Handle onboarding completion"""
        status = result.get("status", "UNKNOWN")
        if hasattr(self, "_onboarding_progress_timer") and self._onboarding_progress_timer:
            try:
                self._onboarding_progress_timer.stop()
            except Exception:
                pass
        if hasattr(self, "onboarding_progress_bar"):
            self.onboarding_progress_bar.setRange(0, 100)
            self.onboarding_progress_bar.setValue(100 if status == "READY" else 0)
            self.onboarding_progress_bar.setFormat("Onboarding: complete" if status == "READY" else "Onboarding: failed")
        if hasattr(self, 'onboarding_log_display'):
            if status == "READY":
                self.onboarding_log_display.appendPlainText("\n✅ Onboarding completed successfully!")
            else:
                error = result.get("last_error", "Unknown error")
                self.onboarding_log_display.appendPlainText(f"\n{self._format_onboarding_error(error)}")
                if "REBOOT_REQUIRED_VC" in (error or ""):
                    QTimer.singleShot(300, self._show_vcredist_reboot_prompt)
        
        # Refresh the environment list to show newly created dedicated environments
        if hasattr(self, '_refresh_environment_list'):
            QTimer.singleShot(500, self._refresh_environment_list)
        
        # Ensure we stay on Environment tab (don't let Info tab interrupt)
        if hasattr(self, 'downloaded_details_tabs'):
            # Remember current tab index
            current_index = self.downloaded_details_tabs.currentIndex()
            
            # Update environment tab (this will block signals internally to prevent tab changes)
            path = Path(result.get("base_model_path", ""))
            if path.exists():
                self._update_environment_tab(str(path), model_id, status)
            
            # Ensure we stay on Environment tab if we were there (index 2)
            if current_index == 2:
                self.downloaded_details_tabs.blockSignals(True)
                self.downloaded_details_tabs.setCurrentIndex(2)
                self.downloaded_details_tabs.blockSignals(False)
        else:
            # Update environment tab if tabs don't exist
            path = Path(result.get("base_model_path", ""))
            if path.exists():
                self._update_environment_tab(str(path), model_id, status)
        
        # Rebuild the specific card deterministically (with delay to ensure DB write completes)
        QTimer.singleShot(300, lambda: self._rebuild_model_card(model_id, status))
        
        # Also refresh all models to ensure consistency (with longer delay as fallback)
        QTimer.singleShot(1000, self._refresh_models)
        
        # Refresh Test tab dropdowns after onboarding completion so new/updated models appear
        # without requiring app restart (READY/BROKEN transitions can both affect availability).
        QTimer.singleShot(1500, self._refresh_locals)  # _refresh_locals updates Test tab dropdowns
        QTimer.singleShot(1600, self._load_tool_chat_models)  # Tool Chat has its own READY-model loader
        # Refresh Server page model selector so newly READY models appear without app restart
        if hasattr(self, "server_page") and hasattr(self.server_page, "_populate_model_selector"):
            QTimer.singleShot(1700, self.server_page._populate_model_selector)
        
        # DO NOT automatically switch to Info tab - let user stay on Environment tab to see results
    
    def _rebuild_model_card(self, model_id: str, status: str):
        """Deterministically rebuild a single model card with updated onboarding status"""
        # Find the card and its position in the grid
        card_to_replace = None
        card_row = None
        card_col = None
        
        for card in getattr(self, 'downloaded_model_cards', []):
            card_model_id = None
            if hasattr(card, 'model_id'):
                card_model_id = card.model_id
            elif hasattr(card, 'model_path'):
                # Derive model_id from path (same logic as _refresh_models)
                path = Path(card.model_path)
                model_name = path.name
                card_model_id = model_name.replace("__", "/")
            
            # Match by model_id
            if card_model_id == model_id:
                # Find position in grid layout by iterating
                for row in range(self.downloaded_layout.rowCount()):
                    for col in range(self.downloaded_layout.columnCount()):
                        item = self.downloaded_layout.itemAtPosition(row, col)
                        if item and item.widget() == card:
                            card_row, card_col = row, col
                            break
                    if card_row is not None:
                        break
                
                card_to_replace = card
                break
        
        if not card_to_replace or card_row is None:
            # Log mismatch for debugging - show what model_ids exist vs what we're looking for
            existing_ids = []
            for card in getattr(self, 'downloaded_model_cards', []):
                if hasattr(card, 'model_id'):
                    existing_ids.append(card.model_id)
                elif hasattr(card, 'model_path'):
                    path = Path(card.model_path)
                    existing_ids.append(path.name.replace("__", "/"))
            self._log_models(f"⚠️ Card not found for model_id: {model_id}")
            self._log_models(f"   Looking for: {model_id}")
            self._log_models(f"   Available model_ids: {existing_ids[:5]}..." if len(existing_ids) > 5 else f"   Available model_ids: {existing_ids}")
            self._log_models(f"   Check Environment tab for resolved model_id and env_key")
            return
        
        # Get fresh data for the card (same logic as _refresh_models)
        model_path = card_to_replace.model_path
        path = Path(model_path)
        model_name = path.name
        
        # Get fresh onboarding status from StateStore
        from core.model_onboarding import get_onboarding_service
        onboarding = get_onboarding_service()
        fresh_status = onboarding.get_onboarding_status(model_id) or "NEW"
        
        # Get environment key from onboarding entry (source of truth)
        env_key = None
        try:
            onboarding_entry = self.state_store.get_onboarding(model_id)
            if onboarding_entry and onboarding_entry.get("env_key"):
                env_key = onboarding_entry.get("env_key")
            else:
                # Legacy fallback: models.env_key (onboarding is authoritative)
                model_entry = self.state_store.get_model(model_id)
                if model_entry:
                    env_key = model_entry.get("env_key")
        except Exception:
            pass
        
        # Get other card data
        from desktop_app.model_card_widget import DownloadedModelCard
        from core.models import detect_model_capabilities, get_capability_icons, get_model_size
        from core.model_requirements import get_model_compatibility_badge
        
        status_check = self.model_checker.check_model(path)
        
        if not status_check.is_complete:
            size = "⚠️ INCOMPLETE"
            icons = "❌"
            compatibility_badge = None
        else:
            size = get_model_size(str(path))
            capabilities = detect_model_capabilities(model_name=model_name, model_path=str(path))
            icons = get_capability_icons(capabilities)
            compatibility_badge = get_model_compatibility_badge(model_id, model_name, self.user_vram_gb)
        
        display_fresh_status = "BROKEN" if (not status_check.is_complete) else fresh_status

        # Create new card with fresh data
        new_card = DownloadedModelCard(
            model_name,
            str(path),
            size,
            icons,
            is_incomplete=not status_check.is_complete,
            compatibility_badge=compatibility_badge,
            onboarding_status=display_fresh_status,
            env_key=env_key,
            parent=self.downloaded_container,
        )
        new_card.set_theme(self.dark_mode)
        new_card.selected.connect(self._on_model_selected)
        new_card.delete_clicked.connect(self._on_delete_model)
        new_card.add_weights_clicked.connect(self._on_add_weights)
        new_card.dedicated_env_clicked.connect(self._on_create_dedicated_env)
        if not status_check.is_complete:
            new_card.repair_clicked.connect(self._on_repair_model)
        new_card.model_id = model_id
        
        # Replace old card with new one in layout
        self.downloaded_layout.removeWidget(card_to_replace)
        card_to_replace.deleteLater()
        self.downloaded_layout.addWidget(new_card, card_row, card_col)
        
        # Update the cards list
        card_index = self.downloaded_model_cards.index(card_to_replace)
        self.downloaded_model_cards[card_index] = new_card
        
        self._log_models(f"✓ Rebuilt card for {model_id} with status {fresh_status}")
    
    
    def _format_onboarding_error(self, error_msg: str) -> str:
        """
        Format onboarding error message to show user-friendly reason codes.
        
        Args:
            error_msg: Raw error message from onboarding
            
        Returns:
            Formatted error message with clear reason codes
        """
        if not error_msg:
            return "Unknown error"
        if "[RUNTIME_MISSING_COMPONENT]" in error_msg:
            return (
                "❌ Runtime Components Missing\n\n"
                "The selected backend runtime is not fully installed in the model environment.\n"
                "Use Repair/Re-onboard to install required runtime components.\n\n"
                f"Technical details:\n{error_msg[:700]}"
            )
        if "[BACKEND_INCOMPATIBLE_MODEL]" in error_msg:
            if "GGUF_BACKEND_INCOMPATIBLE" in error_msg or ".gguf" in error_msg.lower():
                return (
                    "❌ GGUF Backend Incompatible\n\n"
                    "The selected GGUF variant could not be loaded by the available GGUF runtime backend.\n"
                    "Trying a newer Transformers build will not help here. Pick a different GGUF variant or repair/update the GGUF runtime backend.\n\n"
                    f"Technical details:\n{error_msg[:700]}"
                )
            return (
                "❌ Backend Incompatible With Model Variant\n\n"
                "The selected model variant cannot be parsed/loaded by the available runtime backend.\n"
                "Try another variant or repair backend runtime.\n\n"
                f"Technical details:\n{error_msg[:700]}"
            )
        if "GGUF_BACKEND_INCOMPATIBLE" in error_msg:
            return (
                "❌ GGUF Backend Incompatible\n\n"
                "The selected GGUF variant could not be loaded by the available GGUF runtime backend.\n"
                "Trying a newer Transformers build will not help here. Pick a different GGUF variant or repair/update the GGUF runtime backend.\n\n"
                f"Technical details:\n{error_msg[:700]}"
            )
        if "[MODEL_FILE_CORRUPT]" in error_msg:
            return (
                "❌ Model Files Corrupted or Incomplete\n\n"
                "Repair model files and rerun onboarding.\n\n"
                f"Technical details:\n{error_msg[:700]}"
            )
        if "[NETWORK_OR_AUTH]" in error_msg:
            return (
                "❌ Network/Auth Issue\n\n"
                "The runtime could not access required remote artifacts. Verify network and HF token.\n\n"
                f"Technical details:\n{error_msg[:700]}"
            )
        
        # Check for reason codes in error message
        if "UNSUPPORTED_ARCH" in error_msg or "does not recognize this architecture" in error_msg:
            return (
                "❌ Unsupported Model Architecture\n\n"
                "The model uses an architecture that is not supported by the current Transformers version.\n"
                "The system will automatically try to upgrade to a newer version or install from source.\n\n"
                f"Technical details:\n{error_msg[:500]}"
            )
        elif "MISSING_PACKAGE" in error_msg or "No module named" in error_msg or "ImportError" in error_msg:
            return (
                "❌ Missing Package\n\n"
                "The model requires a package that is not installed in the environment.\n"
                "The system will automatically attempt to install missing packages.\n\n"
                f"Technical details:\n{error_msg[:500]}"
            )
        elif "REMOTE_CODE_REQUIRED" in error_msg:
            return (
                "❌ Remote Code Required\n\n"
                "The model requires custom code that must be loaded from the repository.\n"
                "This is automatically enabled during onboarding.\n\n"
                f"Technical details:\n{error_msg[:500]}"
            )
        elif "REBOOT_REQUIRED_VC" in error_msg:
            return (
                "❌ Onboarding Failed (VC++ runtime)\n\n"
                "The Microsoft Visual C++ Redistributable was installed, but a Windows reboot may be required "
                "for it to take effect. Please restart your PC, then retry onboarding for this model.\n\n"
                f"Technical details:\n{error_msg[:800]}"
            )
        else:
            # Generic error - show first 500 chars
            return f"❌ Onboarding Failed\n\n{error_msg[:500]}"
    
    def _show_vcredist_reboot_prompt(self):
        """Show popup when VC++ was installed and reboot is recommended (REBOOT_REQUIRED_VC)."""
        from PySide6.QtGui import QDesktopServices
        from PySide6.QtCore import QUrl
        msg = QMessageBox(self)
        msg.setWindowTitle("Restart required")
        msg.setIcon(QMessageBox.Information)
        msg.setText("Visual C++ Redistributable was installed.")
        msg.setInformativeText(
            "A Windows restart may be required for PyTorch to load correctly. "
            "Restart your PC, then retry model onboarding."
        )
        btn_later = msg.addButton("Restart later", QMessageBox.AcceptRole)
        btn_help = msg.addButton("Open reboot instructions", QMessageBox.ActionRole)
        btn_reboot = msg.addButton("Restart now", QMessageBox.ActionRole)
        msg.setDefaultButton(btn_later)
        msg.exec()
        clicked = msg.clickedButton()
        if clicked == btn_help:
            try:
                QDesktopServices.openUrl(QUrl("https://support.microsoft.com/en-us/windows/restart-your-pc-8932b879-4f5c-b2e7-4a46-b8d7f899f2c2"))
            except Exception:
                pass
        elif clicked == btn_reboot:
            try:
                import subprocess
                subprocess.Popen(["shutdown", "/r", "/t", "10", "/c", "LLM Studio: restarting for VC++ runtime"])
            except Exception:
                pass

    def _on_onboarding_error(self, model_id: str, error: str):
        """Handle onboarding error"""
        if hasattr(self, "_onboarding_progress_timer") and self._onboarding_progress_timer:
            try:
                self._onboarding_progress_timer.stop()
            except Exception:
                pass
        if hasattr(self, "onboarding_progress_bar"):
            self.onboarding_progress_bar.setRange(0, 100)
            self.onboarding_progress_bar.setValue(0)
            self.onboarding_progress_bar.setFormat("Onboarding: failed")
        if hasattr(self, 'onboarding_log_display'):
            formatted = self._format_onboarding_error(error)
            self.onboarding_log_display.appendPlainText(f"\n{formatted}")
        
        if "REBOOT_REQUIRED_VC" in (error or ""):
            QTimer.singleShot(300, self._show_vcredist_reboot_prompt)

        # Rebuild card with BROKEN status
        QTimer.singleShot(300, lambda: self._rebuild_model_card(model_id, "BROKEN"))
        
        # Refresh models
        QTimer.singleShot(1000, self._refresh_models)
    
    def _on_repair_complete(self, model_id: str, dest: str, card, progress_bar, repair_key: str, status_label=None):
        """Handle successful repair"""
        self._log_models(f"✓ Repair complete: {dest}")
        repair_info = {}
        if hasattr(self, "_repair_info"):
            repair_info = self._repair_info.get(repair_key) or {}

        if str(repair_info.get("operation") or "") == "add_weights":
            weights_to_delete = [
                str(p).strip().replace("\\", "/")
                for p in (repair_info.get("weights_to_delete") or [])
                if isinstance(p, str) and str(p).strip()
            ]
            desired_patterns = [
                str(p).strip().replace("\\", "/")
                for p in (repair_info.get("desired_patterns") or [])
                if isinstance(p, str) and str(p).strip()
            ]
            preferred_active = str(repair_info.get("preferred_active") or "").strip().replace("\\", "/")
            dest_path = Path(dest)
            if weights_to_delete:
                deleted, failed = self._delete_local_gguf_variants(dest_path, weights_to_delete)
                if deleted:
                    self._log_models(f"⚖️ Removed GGUF variants after download: {[Path(p).name for p in deleted]}")
                if failed:
                    self._log_models(f"[WARNING] Could not remove some GGUF variants after download: {[Path(p).name for p in failed]}")
                    QMessageBox.warning(
                        self,
                        "Weights",
                        "Some GGUF variants could not be removed after updating. They may be in use by another process.",
                    )
            try:
                self._sync_selected_weights_marker(
                    dest_path,
                    model_id=model_id,
                    append_patterns=desired_patterns,
                    preferred_active=preferred_active or None,
                )
            except Exception as e:
                self._log_models(f"[WARNING] Could not finalize selected weights marker: {e}")

        # Auto-start onboarding in the background (silent) so badges/env association update
        try:
            # Add-weights operation should not retrigger onboarding flow.
            if "_addweights_" not in str(repair_key):
                dest_path = Path(dest)
                entry = self.state_store.get_onboarding(model_id)
                status = (entry.get("status") if entry else None) or "NEW"
                # Only set READY again via onboarding; if still BROKEN/NEW, run onboarding (probe will set READY or BROKEN)
                if status not in ("READY", "BUILDING"):
                    self._start_model_onboarding_silent(str(dest_path), model_id)
        except Exception as e:
            self._log_models(f"[WARNING] Could not start onboarding automatically after repair: {e}")
        
        # Clean up thread
        if repair_key in self.active_downloads:
            thread, _ = self.active_downloads[repair_key]
            if thread.isRunning():
                thread.quit()
                thread.wait()
            del self.active_downloads[repair_key]
        if hasattr(self, "_repair_info") and repair_key in self._repair_info:
            try:
                del self._repair_info[repair_key]
            except Exception:
                pass
        
        # Remove progress bar and status label
        if progress_bar:
            progress_bar.setVisible(False)
            progress_bar.deleteLater()
        if status_label:
            status_label.setVisible(False)
            status_label.deleteLater()
        
        # Refresh models to update status (use QTimer to ensure thread cleanup is done)
        def refresh_after_repair():
            self._refresh_models()  # This will update the card with correct status and onboarding badge
            self._refresh_locals()
        
        QTimer.singleShot(500, refresh_after_repair)

    def _restore_model_card_action_buttons(self, card, prefer_fix_text: bool = False) -> None:
        """Restore card action buttons after failed/aborted background operations."""
        try:
            if hasattr(card, "repair_btn"):
                card.repair_btn.setEnabled(True)
                card.repair_btn.setText("🔧 Fix" if prefer_fix_text else "🔧 Repair")
        except Exception:
            pass

    def _is_qt_obj_alive(self, obj) -> bool:
        """Best-effort QObject validity guard for async signal handlers."""
        if obj is None:
            return False
        try:
            from shiboken6 import isValid as _is_valid
            return bool(_is_valid(obj))
        except Exception:
            try:
                _ = obj.objectName() if hasattr(obj, "objectName") else True
                return True
            except Exception:
                return False

    def _safe_progress_set(self, progress_bar, value: int) -> None:
        try:
            if self._is_qt_obj_alive(progress_bar):
                progress_bar.setValue(int(value))
        except Exception:
            pass

    def _safe_label_set(self, label, text: str) -> None:
        try:
            if self._is_qt_obj_alive(label):
                label.setText(str(text))
        except Exception:
            pass

    def _safe_progress_text(self, progress_bar, prefix: str, msg: str) -> None:
        try:
            if self._is_qt_obj_alive(progress_bar):
                self._update_progress_bar_text(progress_bar, prefix, msg)
        except Exception:
            pass
        try:
            if hasattr(card, "add_weights_btn"):
                card.add_weights_btn.setVisible(True)
                card.add_weights_btn.setEnabled(True)
                card.add_weights_btn.setText("⚖️ Weights")
        except Exception:
            pass
    
    def _handle_repair_error(self, repair_key: str, error: str):
        """Handle repair error signal - looks up stored info and delegates to the actual handler"""
        # Look up the stored repair info
        if not hasattr(self, '_repair_info') or repair_key not in self._repair_info:
            self._log_models(f"Error: Repair info not found for key {repair_key}")
            return
        
        info = self._repair_info[repair_key]
        model_id = info['model_id']
        card = info['card']
        progress_bar = info['progress_bar']
        status_label = info['status_label']
        model_path = info['model_path']
        operation = str(info.get("operation") or "repair")
        
        # Clean up stored info
        del self._repair_info[repair_key]
        
        # Use QTimer to ensure dialog runs on the main thread event loop
        from PySide6.QtCore import QTimer
        QTimer.singleShot(0, lambda: self._show_repair_error_dialog(model_id, card, progress_bar, repair_key, status_label, model_path, error, operation))

    def _show_repair_error_dialog(self, model_id: str, card, progress_bar, repair_key: str, status_label, model_path: Path, error: str, operation: str = "repair"):
        """Actually show the repair error dialog - called via QTimer to ensure main thread"""
        self._log_models(f"Error repairing {model_id}: {error}")
        
        # Update status label to show error occurred (immediate visual feedback)
        if status_label:
            self._safe_label_set(status_label, "Repair failed - asking...")
        
        # Clean up thread
        if repair_key in self.active_downloads:
            thread, _ = self.active_downloads[repair_key]
            if thread.isRunning():
                thread.quit()
                thread.wait(5000)  # Wait max 5 seconds
                if thread.isRunning():
                    thread.terminate()
                    thread.wait(2000)
            del self.active_downloads[repair_key]
        
        # Check if error is due to locked directory (no fallback for this)
        is_locked_error = (
            "locked by another process" in error.lower() or
            "modeldirlockederror" in error.lower() or
            "cannot clean" in error.lower() and "locked" in error.lower()
        )
        
        if is_locked_error:
            # Remove progress bar and status label
            if progress_bar:
                progress_bar.setVisible(False)
                progress_bar.deleteLater()
            if status_label:
                status_label.setVisible(False)
                status_label.deleteLater()
            
            self._restore_model_card_action_buttons(card, prefer_fix_text=False)
            
            # Show error message - NO AUTOMATIC RESTART
            from PySide6.QtWidgets import QMessageBox
            msg = QMessageBox(self)
            msg.setIcon(QMessageBox.Critical)
            msg.setWindowTitle("Repair Failed")
            msg.setText(f"Cannot repair model '{model_id}'\n\n"
                       f"Directory is locked and cannot be deleted:\n{model_path}\n\n"
                       f"Please:\n"
                       f"1. Close all other applications\n"
                       f"2. Close antivirus/Windows Search\n"
                       f"3. Manually delete the folder\n"
                       f"4. Try repair again")
            msg.setStandardButtons(QMessageBox.Ok)
            msg.exec()
            return
        
        # For other errors (stall, network failure, etc.), prompt for delete+redownload fallback
        from PySide6.QtWidgets import QMessageBox

        if operation == "add_weights":
            # Add-weights failure should never suggest deleting the model folder.
            if progress_bar:
                progress_bar.setVisible(False)
                progress_bar.deleteLater()
            if status_label:
                status_label.setVisible(False)
                status_label.deleteLater()
            self._restore_model_card_action_buttons(card, prefer_fix_text=False)
            QMessageBox.warning(
                self,
                "Update Weights Failed",
                f"Could not update the selected weight set for '{model_id}'.\n\n{error[:350]}",
            )
            return

        msg_box = QMessageBox(self)
        msg_box.setWindowTitle("Repair Failed")
        msg_box.setText(f"Repair failed or stalled for '{model_id}':\n\n{error[:200]}\n\n"
                       f"Do you want to delete and redownload from scratch?\n\n"
                       f"This will permanently delete the local model folder and re-download everything.")
        msg_box.setStandardButtons(QMessageBox.Yes | QMessageBox.No)
        msg_box.setDefaultButton(QMessageBox.No)
        msg_box.setIcon(QMessageBox.Question)
        msg_box.setModal(True)

        # Ensure dialog is visible and active
        if hasattr(self, 'activateWindow'):
            self.activateWindow()
            self.raise_()
        msg_box.show()
        msg_box.raise_()
        msg_box.activateWindow()
        reply = msg_box.exec()
        
        if reply == QMessageBox.Yes:
            # User chose delete+redownload fallback
            self._log_models(f"🔄 Starting delete+redownload fallback for {model_id}...")
            
            # Update status label
            if status_label:
                self._safe_label_set(status_label, "Deleting and redownloading...")
            
            # Unlock files first
            self._unlock_model_files(model_path, log_callback=lambda m: self._log_models(m))
            
            # Clean up .incomplete files
            try:
                cache_dir = model_path / ".cache" / "huggingface" / "download"
                if cache_dir.exists():
                    incomplete_files = list(cache_dir.rglob("*.incomplete"))
                    if incomplete_files:
                        self._log_models(f"Removing {len(incomplete_files)} incomplete download files...")
                        for incomplete_file in incomplete_files:
                            try:
                                incomplete_file.unlink()
                            except Exception:
                                pass
            except Exception as e:
                self._log_models(f"Warning: Could not clean incomplete files: {e}")
            
            # Prefer persisted selected-weights marker for fresh redownload too.
            fresh_allow_patterns = None
            try:
                marker_path = Path(model_path) / ".selected_weights.json"
                if marker_path.exists():
                    marker = json.loads(marker_path.read_text(encoding="utf-8"))
                    pats = marker.get("allow_patterns")
                    if isinstance(pats, list):
                        fresh_allow_patterns = [str(p) for p in pats if isinstance(p, str) and p.strip()]
                if not fresh_allow_patterns:
                    from core.model_file_utils import list_repo_files
                    local_gguf = list(Path(model_path).rglob("*.gguf"))
                    if local_gguf:
                        siblings = list_repo_files(model_id, token=self._resolve_hf_token())
                        repo_gguf = [s.get("rfilename", "") for s in siblings if (s.get("rfilename") or "").lower().endswith(".gguf")]
                        if len(repo_gguf) > 1 and len(local_gguf) == 1:
                            match_name = local_gguf[0].name
                            for r in repo_gguf:
                                if Path(r).name == match_name:
                                    fresh_allow_patterns = [r]
                                    break
            except Exception:
                pass
            thread = RepairThread(model_id, Path(model_path), force_fresh_only=True, cache_dir=self.hf_cache_dir, token=self._resolve_hf_token(), allow_patterns=fresh_allow_patterns)
            
            # Mark as active
            self.active_downloads[repair_key] = (thread, card)
            
            # Connect signals
            thread.progress.connect(lambda p: self._safe_progress_set(progress_bar, p))
            thread.status.connect(lambda msg: self._safe_label_set(status_label, msg))
            thread.status.connect(lambda msg: self._safe_progress_text(progress_bar, "Redownloading", msg))
            thread.finished.connect(lambda dest: self._on_repair_complete(model_id, dest, card, progress_bar, repair_key, status_label))
            thread.error.connect(lambda err: self._on_repair_error(model_id, err, card, progress_bar, repair_key))
            
            # Start repair
            thread.start()
            self._safe_progress_set(progress_bar, 2)
        else:
            # User declined - just clean up UI and re-enable repair button
            if progress_bar:
                progress_bar.setVisible(False)
                progress_bar.deleteLater()
            if status_label:
                status_label.setVisible(False)
                status_label.deleteLater()
            
            self._restore_model_card_action_buttons(card, prefer_fix_text=False)
    
    def _on_repair_error(self, model_id: str, error: str, card, progress_bar, repair_key: str):
        """Handle repair error (legacy - used for delete+redownload fallback errors)"""
        self._log_models(f"✗ Error repairing {model_id}: {error}")
        
        # Clean up thread
        if repair_key in self.active_downloads:
            thread, _ = self.active_downloads[repair_key]
            if thread.isRunning():
                thread.quit()
                thread.wait(5000)
                if thread.isRunning():
                    thread.terminate()
                    thread.wait(2000)
            del self.active_downloads[repair_key]
        
        # Remove progress bar
        if progress_bar:
            progress_bar.setVisible(False)
            progress_bar.deleteLater()
        
        # If error suggests gated/private, show guidance and restore button (no force-fresh)
        err_lower = (error or "").lower()
        if "401" in error or "403" in error or "gated" in err_lower or "access denied" in err_lower:
            self._show_gated_no_token_dialog(model_id, parent_win=self)
            self._restore_model_card_action_buttons(card, prefer_fix_text=True)
            return
        
        # Check if error is due to locked directory
        is_locked_error = (
            "locked by another process" in error.lower() or
            "modeldirlockederror" in error.lower() or
            "cannot clean" in error.lower() and "locked" in error.lower()
        )
        
        if is_locked_error:
            # Show error message - NO AUTOMATIC RESTART
            model_path = Path(card.model_path) if hasattr(card, 'model_path') else None
            from PySide6.QtWidgets import QMessageBox
            msg = QMessageBox(self)
            msg.setIcon(QMessageBox.Critical)
            msg.setWindowTitle("Repair Failed")
            msg.setText(f"Cannot repair model '{model_id}'\n\n"
                       f"Directory is locked and cannot be deleted:\n{model_path}\n\n"
                       f"Please:\n"
                       f"1. Close all other applications\n"
                       f"2. Close antivirus/Windows Search\n"
                       f"3. Manually delete the folder\n"
                       f"4. Try repair again")
            msg.setStandardButtons(QMessageBox.Ok)
            msg.exec()
            
            self._restore_model_card_action_buttons(card, prefer_fix_text=True)
            return
        
        # Keep local partial files after failure so the next repair can resume.
        # Do not auto-force a full redownload on generic network/stall failures.
        self._restore_model_card_action_buttons(card, prefer_fix_text=True)
    
    def _on_download_error(self, model_id: str, error: str, card, progress_bar):
        """Handle download error"""
        self._log_models(f"✗ Error downloading {model_id}: {error}")

        # Clean up thread first
        if model_id in self.active_downloads:
            thread, _ = self.active_downloads[model_id]
            if thread.isRunning():
                thread.quit()
                thread.wait()
            del self.active_downloads[model_id]

        # Remove progress bar
        if progress_bar:
            progress_bar.setVisible(False)
            progress_bar.deleteLater()

        # Stop the pink-blink ring and re-pack the grid (the failed card
        # will fall back to its compatibility-sorted slot).
        try:
            if card is not None:
                card.set_downloading(False)
            self._reorder_curated_grid()
        except Exception:
            pass

        # Restore button
        card.download_btn.setVisible(True)
        card.download_btn.setEnabled(True)
        card.download_btn.setText("❌ Failed - Retry")
        # If error suggests gated/private, show guidance
        err_lower = (error or "").lower()
        if "401" in error or "403" in error or "gated" in err_lower or "access denied" in err_lower:
            self._show_gated_no_token_dialog(model_id, parent_win=self)

    def _change_gpu_vram(self) -> None:
        """Open dialog to change GPU VRAM override"""
        current_vram = self.user_vram_gb
        vram, ok = QInputDialog.getDouble(
            self,
            "Set GPU VRAM",
            f"Enter your GPU VRAM in GB:\n\n"
            f"Current: {current_vram:.0f}GB\n"
            f"(Leave empty to use auto-detection)",
            value=current_vram,
            min=1.0,
            max=128.0,
            decimals=1
        )
        if ok and vram > 0:
            self._set_gpu_vram_override(vram)
            self.gpu_vram_label.setText(f"{vram:.0f}GB")
            # Refresh models to update compatibility badges
            self._refresh_models()
            self._log_models(f"✓ GPU VRAM set to {vram:.0f}GB - compatibility badges updated")
    
    def _browse_hf_target(self) -> None:
        d = QFileDialog.getExistingDirectory(self, "Select download folder", str(self.root))
        if d:
            self.hf_target_dir.setText(d)

    def _on_hf_filter_toggled(self, _checked: bool = False) -> None:
        """Apply the format/capability filters.

        Two surfaces are affected:
          * Search Results — re-run the current query through the filter.
          * Recommended panel — re-render from the cached HF fetch using
            the same _matches() logic, so checking 'Vision' on the
            curated view actually narrows the cards instead of being
            silently ignored.
        """
        # Search results: only re-run if there's an active query (don't
        # spam list_models on every checkbox click with an empty query).
        if hasattr(self, "hf_query") and self.hf_query.text().strip():
            self._hf_search()
        # Recommended panel: rebuild the curated grid from cached hits
        # using the current checkbox state.
        if hasattr(self, "_curated_hits_cache"):
            try:
                self._refresh_models()
            except Exception:
                pass

    def _active_hf_filter_categories(self) -> list[str]:
        """Snapshot the checkboxes into the canonical category strings."""
        wanted: list[str] = []
        if getattr(self, "hf_filter_trainable", None) and self.hf_filter_trainable.isChecked():
            wanted.append("trainable")
        if getattr(self, "hf_filter_gguf", None) and self.hf_filter_gguf.isChecked():
            wanted.append("gguf")
        if getattr(self, "hf_filter_adapter", None) and self.hf_filter_adapter.isChecked():
            wanted.append("adapter")
        if getattr(self, "hf_filter_quant", None) and self.hf_filter_quant.isChecked():
            wanted.append("quant")
        if getattr(self, "hf_filter_instruct", None) and self.hf_filter_instruct.isChecked():
            wanted.append("instruct")
        if getattr(self, "hf_filter_chat", None) and self.hf_filter_chat.isChecked():
            wanted.append("chat")
        if getattr(self, "hf_filter_reasoning", None) and self.hf_filter_reasoning.isChecked():
            wanted.append("reasoning")
        if getattr(self, "hf_filter_vision", None) and self.hf_filter_vision.isChecked():
            wanted.append("vision")
        return wanted

    def _hit_matches_filters(self, hit, wanted: list[str]) -> bool:
        """OR-style match between an HFModelHit and the active categories."""
        if not wanted:
            return True
        tagset = {t.lower() for t in (hit.tags or [])}
        mid = (hit.model_id or "").lower()
        for category in wanted:
            if category == "trainable":
                if (
                    "transformers" in tagset
                    and "gguf" not in tagset
                    and "peft" not in tagset
                    and "adapter" not in tagset
                    and not any(q in tagset for q in ("awq", "gptq", "exl2", "mlx"))
                ):
                    return True
            elif category == "gguf":
                if "gguf" in tagset:
                    return True
            elif category == "adapter":
                if "peft" in tagset or "adapter" in tagset or "lora" in tagset:
                    return True
            elif category == "quant":
                if any(q in tagset for q in ("awq", "gptq", "exl2", "bitsandbytes")):
                    return True
            elif category == "instruct":
                if any(t in tagset for t in ("instruct", "instruction-tuned", "sft")):
                    return True
                if (
                    "instruct" in mid
                    or "-it-" in mid
                    or mid.endswith("-it")
                    or mid.endswith("-it-bnb-4bit")
                ):
                    return True
            elif category == "chat":
                if any(t in tagset for t in ("chat", "conversational", "dialog", "chatml")):
                    return True
                if "chat" in mid or "dialog" in mid:
                    return True
            elif category == "reasoning":
                if any(t in tagset for t in ("reasoning", "thinking", "chain-of-thought")):
                    return True
                if any(
                    kw in mid
                    for kw in ("reasoning", "thinking", "deepseek-r1", "-r1-", "-r1", "qwq", "o1-")
                ):
                    return True
            elif category == "vision":
                if any(
                    t in tagset
                    for t in (
                        "image-text-to-text",
                        "vqa",
                        "visual-question-answering",
                        "image-to-text",
                        "multimodal",
                    )
                ):
                    return True
                if any(kw in mid for kw in ("vision", "-vl-", "-vl", "llava", "multimodal", "moondream")):
                    return True
        return False

    def _apply_hf_filter(self, hits: list) -> list:
        """Filter a list of HFModelHit by the currently-checked categories."""
        wanted = self._active_hf_filter_categories()
        if not wanted:
            return list(hits or [])
        return [h for h in (hits or []) if self._hit_matches_filters(h, wanted)]

    def _hf_search(self) -> None:
        q = self.hf_query.text().strip()
        
        # If search is empty, return to curated view
        if not q:
            self.browse_stack.setCurrentIndex(0)
            return
            
        # Switch to Search Results view
        self.browse_stack.setCurrentIndex(1)
        self.search_results_title.setText(f"🔍 Search Results for: '{q}'")
        
        # Clear existing results
        while self.search_results_layout.count():
            item = self.search_results_layout.takeAt(0)
            if item.widget():
                item.widget().deleteLater()
        self.search_model_cards.clear()
        
        wanted = self._active_hf_filter_categories()
        filter_summary = f" [filter: {', '.join(wanted)}]" if wanted else ""
        self._log_models(f"🔍 Searching Hugging Face for: {q}{filter_summary}...")

        try:
            # Over-fetch when filters are active so we still have ~24 results
            # after client-side filtering drops false positives.
            fetch_limit = 100 if wanted else 24
            raw = search_hf_models(q, limit=fetch_limit)
            hits = self._apply_hf_filter(raw)
            hits = hits[:24]
            
            if not hits:
                no_results = QLabel(f"No models found matching '{q}'")
                no_results.setStyleSheet("font-size: 14pt; color: #888; padding: 20px;")
                self.search_results_layout.addWidget(no_results, 0, 0)
                return
                
            row, col = 0, 0
            for h in hits:
                model_id = h.model_id
                model_name_raw = model_id.split("/")[-1]
                # Make search result titles wrap/read like curated cards.
                model_name = model_name_raw.replace("-", " ").replace("_", " ")
                
                # Check if downloaded
                model_slug = model_id.replace("/", "__")
                models_dir = self.root / "models"
                is_downloaded = (models_dir / model_slug).exists()
                
                capabilities = detect_model_capabilities(model_id=model_id)
                icons = get_capability_icons(capabilities)
                
                # Format stats
                dl_text = f"{h.downloads:,}" if h.downloads else "0"
                likes_text = f"{h.likes:,}" if h.likes else "0"
                
                # Get compatibility badge
                compatibility_badge = get_model_compatibility_badge(model_id, model_name_raw, self.user_vram_gb)
                
                # Create card with download functionality
                card = ModelCard(
                    model_name,
                    model_id,
                    "",
                    "Unknown size",
                    icons,
                    is_downloaded,
                    downloads=dl_text,
                    likes=likes_text,
                    compatibility_badge=compatibility_badge,
                    parent=self.search_results_container,
                )
                # Keep search cards visually consistent with curated cards.
                # Curated cards often render taller because they include descriptions.
                # Lock search result card height to the first curated card when available.
                try:
                    target_h = None
                    if hasattr(self, "model_cards") and self.model_cards:
                        ref_card = self.model_cards[0]
                        target_h = int(ref_card.sizeHint().height() or ref_card.height() or 0)
                    if not target_h or target_h < 220:
                        target_h = 280
                    card.setMinimumHeight(target_h)
                    card.setMaximumHeight(target_h)
                except Exception:
                    pass
                card.set_theme(self.dark_mode)
                # FIXED: Connect to the correct download handler for search results
                card.download_clicked.connect(lambda mid=model_id: self._download_model_by_id(mid))
                # Card click: open Info tab and load details there
                card.card_clicked.connect(lambda checked=False, mid=model_id: (self.search_details_tabs.setCurrentIndex(1), self._show_model_details(mid, self.search_info_panel)))
                self.search_results_layout.addWidget(card, row, col)
                self.search_model_cards.append(card)
                
                col += 1
                if col >= 2: # 2 columns for search results (50/50 ratio)
                    col = 0
                    row += 1
                    
            self._log_models(f"✓ Found {len(hits)} models for: {q}")
            
        except Exception as e:
            self._log_models(f"❌ HF search failed: {e}")
            error_label = QLabel(f"Error searching models: {str(e)}")
            error_label.setStyleSheet("color: #f44336; font-size: 12pt;")
            self.search_results_layout.addWidget(error_label, 0, 0)

    def _hf_download_selected(self) -> None:
        """Deprecated: use individual card download buttons"""
        pass
    
    def _show_model_details(self, model_id: str, details_panel) -> None:
        """Fetch and display detailed model information in the details panel"""
        # Update the Access & Tokens panel link to the selected model page
        try:
            self._update_hf_accept_terms_link(model_id)
        except Exception:
            pass

        # Show loading state
        details_panel.show_loading()
        
        # Create worker and thread for background fetching
        worker = ModelDetailsWorker(model_id, max_retries=2, token=self._resolve_hf_token())
        thread = QThread()
        worker.moveToThread(thread)
        
        # Map worker -> panel so slots can resolve it safely on main thread
        if not hasattr(self, "_detail_panel_by_worker"):
            self._detail_panel_by_worker = {}
        self._detail_panel_by_worker[worker] = details_panel

        # Connect signals with explicit Qt.QueuedConnection to ensure main thread execution
        from PySide6.QtCore import Qt
        worker.details_ready.connect(self._on_details_ready, Qt.QueuedConnection)
        worker.error_occurred.connect(self._on_details_error, Qt.QueuedConnection)
        worker.retrying.connect(self._on_retrying, Qt.QueuedConnection)
        
        # Start thread and trigger fetch
        thread.started.connect(worker.fetch)
        thread.start()
        
        # Store references to prevent garbage collection
        if not hasattr(self, "_detail_threads"):
            self._detail_threads = []
        if not hasattr(self, "_detail_workers"):
            self._detail_workers = []
        self._detail_threads.append(thread)
        self._detail_workers.append(worker)
        
        # Cleanup thread and worker when done
        worker.details_ready.connect(thread.quit)
        worker.error_occurred.connect(thread.quit)
        def _cleanup_worker():
            try:
                if hasattr(self, "_detail_panel_by_worker") and worker in self._detail_panel_by_worker:
                    self._detail_panel_by_worker.pop(worker, None)
                if worker in self._detail_workers:
                    self._detail_workers.remove(worker)
                if thread in self._detail_threads:
                    self._detail_threads.remove(thread)
            except Exception:
                pass
        thread.finished.connect(_cleanup_worker)
        thread.finished.connect(thread.deleteLater)
        thread.finished.connect(worker.deleteLater)
        
        # Quick watchdog timer - show error if still loading after 6 seconds
        # This catches cases where api.model_info() hangs despite timeout parameter
        watchdog_timer = QTimer()
        watchdog_timer.setSingleShot(True)
        watchdog_timer.timeout.connect(lambda: self._check_still_loading(details_panel, model_id))
        watchdog_timer.start(6000)  # 6 seconds - matches API timeout + buffer
        
        # Store watchdog timer reference
        if not hasattr(self, '_detail_watchdogs'):
            self._detail_watchdogs = []
        self._detail_watchdogs.append(watchdog_timer)
    
    def _on_retrying(self, attempt: int, max_attempts: int) -> None:
        """Update UI to show retry status"""
        try:
            worker = self.sender()
            details_panel = None
            if hasattr(self, "_detail_panel_by_worker"):
                details_panel = self._detail_panel_by_worker.get(worker)
            if details_panel is None:
                return
            details_panel.description_label.setText(
                f"Request failed, retrying... (Attempt {attempt} of {max_attempts})"
            )
            details_panel.description_label.setStyleSheet("color: #ffa500; font-size: 11pt; padding: 10px;")
        except Exception:
            pass  # Ignore errors in retry feedback
    
    def _on_details_ready(self, details: dict) -> None:
        """Handle successful model details fetch"""
        try:
            worker = self.sender()
            details_panel = None
            if hasattr(self, "_detail_panel_by_worker"):
                details_panel = self._detail_panel_by_worker.get(worker)
            if details_panel is None:
                return
            details_panel.display_details(details)
        except Exception as e:
            try:
                if details_panel is not None:
                    details_panel.show_error(f"Error displaying details: {e}")
            except Exception:
                pass
    
    def _on_details_error(self, error_msg: str) -> None:
        """Handle error during model details fetch"""
        # Provide user-friendly error messages
        if "timeout" in error_msg.lower() or "timed out" in error_msg.lower():
            friendly_msg = "Request timed out. The Hugging Face API may be slow or unavailable. Please check your internet connection and try again."
        elif "network" in error_msg.lower() or "connection" in error_msg.lower():
            friendly_msg = "Network error. Please check your internet connection and try again."
        elif "not available" in error_msg.lower():
            friendly_msg = "Hugging Face API is not available. Please ensure huggingface_hub is installed."
        else:
            friendly_msg = f"Failed to fetch model details: {error_msg}"
        
        try:
            worker = self.sender()
            details_panel = None
            if hasattr(self, "_detail_panel_by_worker"):
                details_panel = self._detail_panel_by_worker.get(worker)
            if details_panel is None:
                return
            details_panel.show_error(friendly_msg)
        except Exception:
            pass
    
    def _check_still_loading(self, details_panel, model_id: str) -> None:
        """Watchdog: Check if panel is still showing loading state"""
        try:
            # Check if title still says "Loading model details..."
            if details_panel.title_label.text() == "Loading model details...":
                details_panel.show_error(
                    "Request is taking too long. The Hugging Face API may be unavailable or slow. "
                    "Please check your internet connection and try again."
                )
        except Exception:
            pass  # Ignore errors in watchdog check

    def _detect_gpu_vram(self) -> float:
        """
        Detect GPU VRAM from system or load from config override.
        Uses live nvidia-smi data (get_gpu_memory_usage) for the selected GPU when possible.
        Returns VRAM in GB, defaults to 24GB (RTX 4090) if detection fails.
        """
        # Try to load manual override from config
        config_path = self.root / "desktop_app" / "config" / "gpu_config.json"
        if config_path.exists():
            try:
                with open(config_path, "r", encoding="utf-8") as f:
                    config = json.load(f)
                    if "vram_gb" in config and isinstance(config["vram_gb"], (int, float)):
                        return float(config["vram_gb"])
            except Exception:
                pass  # Fall through to auto-detection

        # Auto-detect from live VRAM usage (nvidia-smi) for selected GPU
        try:
            detector = SystemDetector()
            usage = detector.get_gpu_memory_usage()
            if usage:
                # Use selected GPU index from config, else 0
                gpu_index = 0
                if config_path.exists():
                    try:
                        with open(config_path, "r", encoding="utf-8") as f:
                            cfg = json.load(f)
                            indices = cfg.get("selected_gpu_indices") or cfg.get("gpu_indices")
                            if indices and len(indices) > 0:
                                gpu_index = int(indices[0]) if indices[0] is not None else 0
                    except Exception:
                        pass
                if gpu_index < len(usage):
                    total_mb = usage[gpu_index].get("total_mb", 0)
                    if total_mb > 0:
                        return round(total_mb / 1024.0, 1)
        except Exception:
            pass

        # Fallback: hardware profile (total from detect_all)
        try:
            detector = SystemDetector()
            hardware_profile = detector.get_hardware_profile()
            vram_gb = hardware_profile.get("vram_gb", 0)
            if vram_gb > 0:
                return float(vram_gb)
        except Exception:
            pass  # Fall through to default

        # Default to 24GB (RTX 4090) if detection fails
        return 24.0
    
    def _free_vram_now(self) -> None:
        """Stop all running LLM servers immediately to free GPU memory."""
        try:
            from core.llm_server_manager import get_global_server_manager
            manager = get_global_server_manager()
            # Capture any known server PIDs from StateStore first (best-effort)
            pids_to_kill = set()
            try:
                for st in ("RUNNING", "STARTING"):
                    for row in (manager.state_store.list_servers(status=st) or []):
                        pid = row.get("pid")
                        if pid:
                            try:
                                pids_to_kill.add(int(pid))
                            except Exception:
                                pass
            except Exception:
                pass

            # First attempt a clean shutdown for all servers (tracked + untracked)
            manager.shutdown_all()

            # If anything is still hanging around, force-kill the known server PIDs
            killed = 0
            for pid in sorted(pids_to_kill):
                try:
                    if os.name == "nt":
                        subprocess.run(["taskkill", "/F", "/PID", str(pid)], capture_output=True, timeout=10, **SUBPROCESS_FLAGS)
                    else:
                        try:
                            os.kill(pid, 15)
                        except Exception:
                            pass
                        try:
                            os.kill(pid, 9)
                        except Exception:
                            pass
                    killed += 1
                except Exception:
                    pass

            # Extra hard-stop: kill any orphan OWLLM uvicorn servers not recorded in StateStore.
            # These can keep VRAM pinned even after the GUI exits.
            if os.name == "nt":
                try:
                    ps = subprocess.run(
                        [
                            "powershell",
                            "-NoProfile",
                            "-Command",
                            "(Get-CimInstance Win32_Process -Filter \"Name='python.exe'\") | "
                            "Where-Object { $_.CommandLine -match 'core\\.llm_backends\\.(server_app|bundled_proxy_server):app' } | "
                            "Select-Object -ExpandProperty ProcessId",
                        ],
                        capture_output=True,
                        text=True,
                        timeout=10,
                        **SUBPROCESS_FLAGS,
                    )
                    for line in (ps.stdout or "").splitlines():
                        line = line.strip()
                        if line.isdigit():
                            pid = int(line)
                            try:
                                subprocess.run(["taskkill", "/F", "/PID", str(pid)], capture_output=True, timeout=10, **SUBPROCESS_FLAGS)
                                killed += 1
                            except Exception:
                                pass
                except Exception:
                    pass

            if killed:
                self._log_models(f"✓ Stopped servers and force-killed {killed} leftover server process(es). VRAM should free up shortly.")
            else:
                self._log_models("✓ All servers stopped. VRAM should free up shortly.")

            QTimer.singleShot(1500, lambda: self._update_gpu_vram_display(force_refresh=True))
        except Exception as e:
            self._log_models(f"Failed to free VRAM: {e}")
            QMessageBox.warning(self, "Free VRAM", f"Could not stop servers: {e}")

    def _update_gpu_vram_display(self, force_refresh: bool = False) -> None:
        """Update GPU VRAM label with live usage (total and free) from nvidia-smi for selected GPU.

        Pass ``force_refresh=True`` to bypass the module-level TTL cache in
        ``SystemDetector`` (e.g. after explicitly freeing VRAM so the user
        sees the updated value immediately).
        """
        if not hasattr(self, "gpu_vram_label") or not self.gpu_vram_label:
            return
        try:
            detector = SystemDetector()
            usage = detector.get_gpu_memory_usage(force_refresh=force_refresh)
            if not usage:
                self.gpu_vram_label.setText(f"{self.user_vram_gb:.0f} GB")
                return
            gpu_index = 0
            config_path = self.root / "desktop_app" / "config" / "gpu_config.json"
            if config_path.exists():
                try:
                    with open(config_path, "r", encoding="utf-8") as f:
                        cfg = json.load(f)
                        indices = cfg.get("selected_gpu_indices") or cfg.get("gpu_indices")
                        if indices and len(indices) > 0 and indices[0] is not None:
                            gpu_index = int(indices[0])
                except Exception:
                    pass
            if gpu_index >= len(usage):
                gpu_index = 0
            u = usage[gpu_index]
            total_mb = u.get("total_mb", 0)
            used_mb = u.get("used_mb", 0)
            free_mb = max(0, total_mb - used_mb)
            total_gb = total_mb / 1024.0
            free_gb = free_mb / 1024.0
            self.gpu_vram_label.setText(f"{total_gb:.0f} GB ({free_gb:.1f} GB free)")
        except Exception:
            self.gpu_vram_label.setText(f"{self.user_vram_gb:.0f} GB")

    def _set_gpu_vram_override(self, vram_gb: float) -> None:
        """Save manual GPU VRAM override to config file."""
        config_path = self.root / "desktop_app" / "config" / "gpu_config.json"
        config_path.parent.mkdir(parents=True, exist_ok=True)
        
        try:
            # Load existing config to preserve selected_gpu_indices
            config = {}
            if config_path.exists():
                with open(config_path, "r", encoding="utf-8") as f:
                    config = json.load(f)
            
            config["vram_gb"] = vram_gb
            with open(config_path, "w", encoding="utf-8") as f:
                json.dump(config, f, indent=2)
            self.user_vram_gb = vram_gb
        except Exception as e:
            self._log_models(f"⚠️ Failed to save GPU VRAM override: {e}")
    
    def _get_selected_gpu_indices(self) -> list:
        """Get list of selected GPU indices from config file.

        Identity is stored as ``selected_gpu_uuids`` (stable across driver/BIOS
        reorderings). Legacy ``selected_gpu_indices`` are honored as a fallback
        and migrated to UUIDs on first read.
        """
        cuda_info = self.system_info.get("cuda", {})
        all_gpus = cuda_info.get("gpus", []) or []

        for idx, gpu in enumerate(all_gpus):
            if "_orig_index" not in gpu:
                gpu["_orig_index"] = idx

        if not all_gpus:
            return []

        sorted_gpus = self._sort_gpus_by_memory(all_gpus)
        most_powerful_idx = sorted_gpus[0].get("_orig_index") if sorted_gpus else None

        # Build uuid → current _orig_index map for resolution.
        uuid_to_idx: dict = {}
        for gpu in all_gpus:
            u = gpu.get("uuid")
            if u:
                uuid_to_idx[u] = gpu.get("_orig_index")

        config_path = self.root / "desktop_app" / "config" / "gpu_config.json"
        if config_path.exists():
            try:
                with open(config_path, "r", encoding="utf-8") as f:
                    config = json.load(f) or {}

                # Preferred: UUID-based identity.
                saved_uuids = config.get("selected_gpu_uuids")
                if isinstance(saved_uuids, list) and saved_uuids and uuid_to_idx:
                    resolved = [uuid_to_idx[u] for u in saved_uuids if u in uuid_to_idx]
                    if resolved:
                        # Indices may have shifted since last save — rewrite.
                        self._save_selected_gpu_indices(resolved)
                        return resolved
                    print(f"[DEBUG] Saved UUIDs {saved_uuids} not present in current enumeration; falling back")

                # Legacy: positional indices.
                if "selected_gpu_indices" in config:
                    selected = config["selected_gpu_indices"]
                    valid_indices = [gpu.get("_orig_index", idx) for idx, gpu in enumerate(all_gpus)]
                    filtered = [idx for idx in selected if idx in valid_indices]
                    if filtered:
                        # Migrate to UUID-based storage so the next driver
                        # re-enumeration cannot silently flip the selection.
                        self._save_selected_gpu_indices(filtered)
                        return filtered
            except Exception as e:
                print(f"[DEBUG] Error reading GPU config: {e}")
                import traceback
                traceback.print_exc()

        if most_powerful_idx is not None:
            self._save_selected_gpu_indices([most_powerful_idx])
            print(f"[DEBUG] Defaulting to most powerful GPU: {most_powerful_idx}")
            return [most_powerful_idx]

        return []
    
    def _save_selected_gpu_indices(self, indices: list) -> None:
        """Save selected GPU indices to config file.

        Also writes ``selected_gpu_uuids`` (the stable identity used by
        ``core/gpu_config.py``). Indices are kept for human readability but the
        UUID list is what survives driver/BIOS re-enumerations.
        """
        config_path = self.root / "desktop_app" / "config" / "gpu_config.json"
        config_path.parent.mkdir(parents=True, exist_ok=True)

        try:
            config = {}
            if config_path.exists():
                try:
                    with open(config_path, "r", encoding="utf-8") as f:
                        config = json.load(f)
                except Exception:
                    config = {}

            sorted_indices = sorted(indices)
            config["selected_gpu_indices"] = sorted_indices

            # Resolve indices → UUIDs via system_info so the next read survives reordering.
            cuda_info = self.system_info.get("cuda", {})
            all_gpus = cuda_info.get("gpus", []) or []
            for i, gpu in enumerate(all_gpus):
                if "_orig_index" not in gpu:
                    gpu["_orig_index"] = i
            idx_to_uuid = {gpu.get("_orig_index"): gpu.get("uuid") for gpu in all_gpus if gpu.get("uuid")}
            uuids = [idx_to_uuid[i] for i in sorted_indices if i in idx_to_uuid]
            if uuids:
                config["selected_gpu_uuids"] = uuids
            elif "selected_gpu_uuids" in config:
                # No UUID known for any selected index — drop stale UUID list.
                del config["selected_gpu_uuids"]

            with open(config_path, "w", encoding="utf-8") as f:
                json.dump(config, f, indent=2)
            print(f"[DEBUG] Saved GPU selection: indices={sorted_indices} uuids={uuids}")
        except Exception as e:
            print(f"⚠️ Failed to save GPU selection: {e}")
            import traceback
            traceback.print_exc()
    
    def _on_gpu_selection_changed(self, gpu_index: int, state: int) -> None:
        """Handle GPU checkbox state change.

        Source of truth for the new selection is the live checkbox row, not
        the on-disk config — otherwise stale config from before a hot-fix can
        bounce the user's clicks back ("I unchecked the A2000 and it comes
        back"). We compute the intended selection from the actual checkbox
        states, then validate before saving.
        """
        # Read live state from the checkboxes themselves.
        selected: list[int] = []
        if hasattr(self, "gpu_checkboxes"):
            for orig_idx, cb in self.gpu_checkboxes.items():
                if cb is None:
                    continue
                if cb.isChecked():
                    selected.append(int(orig_idx))
        # bool(state) is robust across PyQt5/PyQt6 enum differences.
        is_checked = bool(state)
        print(f"[DEBUG] GPU selection changed: GPU {gpu_index}, checked={is_checked}, live selection={selected}")

        if not is_checked and not selected:
            # User just unchecked the last selected GPU. Block, since at least
            # one must stay selected.
            QMessageBox.warning(
                self,
                "GPU Selection",
                "At least one GPU must be selected. Please select another GPU before deselecting this one."
            )
            if hasattr(self, "gpu_checkboxes") and gpu_index in self.gpu_checkboxes:
                self.gpu_checkboxes[gpu_index].blockSignals(True)
                self.gpu_checkboxes[gpu_index].setChecked(True)
                self.gpu_checkboxes[gpu_index].blockSignals(False)
                selected.append(gpu_index)
            else:
                return
        
        # Save the updated selection
        self._save_selected_gpu_indices(selected)
        print(f"[DEBUG] Saved GPU selection to config: {selected}")
        
        # Refresh GPU selectors in Train/Test tabs
        self._refresh_gpu_selectors()
        
        # Update Home tab status label without rebuilding the whole tab
        if hasattr(self, 'gpu_status_label'):
            all_gpus = self.system_info.get("cuda", {}).get("gpus", []) or []
            if len(all_gpus) > len(selected):
                self.gpu_status_label.setText(f"✅ <span style='font-weight: bold; text-decoration: none; border: none; border-bottom: none;'>{len(selected)} of {len(all_gpus)} GPU{'s' if len(all_gpus) > 1 else ''} selected</span>")
            else:
                self.gpu_status_label.setText(f"✅ <span style='font-weight: bold; text-decoration: none; border: none; border-bottom: none;'>{len(selected)} GPU{'s' if len(selected) > 1 else ''} detected</span>")
    
    def _get_filtered_gpus(self) -> list:
        """Get list of GPUs filtered by user selection."""
        cuda_info = self.system_info.get("cuda", {})
        all_gpus = cuda_info.get("gpus", []) or []
        
        # Ensure all GPUs have _orig_index set
        for idx, gpu in enumerate(all_gpus):
            if "_orig_index" not in gpu:
                gpu["_orig_index"] = idx
        
        if len(all_gpus) <= 1:
            # If 1 or 0 GPUs, return all (no filtering needed)
            return all_gpus
        
        selected_indices = self._get_selected_gpu_indices()
        if not selected_indices:
            # If no selection, default to most powerful GPU
            sorted_gpus = self._sort_gpus_by_memory(all_gpus)
            if sorted_gpus:
                return [sorted_gpus[0]]  # Return only the most powerful
            return all_gpus
        
        # Filter GPUs to only include selected ones
        filtered = []
        for gpu in all_gpus:
            # Get original index - it should be stored in _orig_index
            orig_idx = gpu.get("_orig_index")
            if orig_idx is not None and orig_idx in selected_indices:
                filtered.append(gpu)
        
        # If filter resulted in empty, fallback to most powerful GPU
        if not filtered:
            sorted_gpus = self._sort_gpus_by_memory(all_gpus)
            if sorted_gpus:
                return [sorted_gpus[0]]
            return all_gpus
        
        return filtered
    
    def _log_models(self, msg: str) -> None:
        self.models_status.appendPlainText(msg)
        self._append_terminal(msg, source="models")

