    def _on_model_selected_for_training(self, model_id: str):
        """Show model info when selected"""
        if model_id:
            capabilities = detect_model_capabilities(model_id=model_id)
            icons = get_capability_icons(capabilities)
            self.model_info_label.setText(f"Selected: {model_id}\n{icons} Capabilities detected")
    
    def _auto_generate_model_name(self):
        """Auto-generate model name based on base model and dataset"""
        from datetime import datetime
        
        # Get base model name (last part after / or __)
        base_model = self.train_base_model.currentText().strip()
        if not base_model or base_model == "(No models downloaded yet)":
            return
        
        # Handle different formats: nvidia__Model or unsloth/model or unsloth__model
        if "__" in base_model:
            model_short = base_model.split("__")[-1]
        elif "/" in base_model:
            model_short = base_model.split('/')[-1]
        else:
            model_short = base_model
        
        # Clean up model name
        model_short = model_short.replace('-bnb-4bit', '').replace('unsloth-', '').replace('_', '-')
        
        # Get dataset name (filename without extension)
        dataset_path = self.train_data_path.text().strip()
        if dataset_path:
            dataset_short = Path(dataset_path).stem
        else:
            dataset_short = "dataset"
        
        # Generate: YYMMDD_modelname_dataset_HHMM
        now = datetime.now()
        auto_name = f"{now.strftime('%y%m%d')}_{model_short}_{dataset_short}_{now.strftime('%H%M')}"
        
        # Always update the name when model changes
        self.train_model_name.setText(auto_name)
    
    def _validate_dataset(self):
        """Validate and show dataset info"""
        path = self.train_data_path.text().strip()
        if not path:
            self.dataset_status_label.setText("")
            self.examples_label.setText("Total Examples: --")
            return
        
        if Path(path).exists():
            # Count lines in JSONL
            try:
                with open(path, 'r', encoding='utf-8') as f:
                    count = sum(1 for _ in f)
                self.dataset_status_label.setText(f"✅ Found dataset: {Path(path).name}")
                self.dataset_status_label.setStyleSheet("color: #4CAF50; font-weight: bold;")
                self.examples_label.setText(f"Total Examples: {count}")
            except Exception as e:
                self.dataset_status_label.setText(f"❌ Error reading file: {e}")
                self.dataset_status_label.setStyleSheet("color: #f44336;")
        else:
            self.dataset_status_label.setText("⚠️ File not found")
            self.dataset_status_label.setStyleSheet("color: #ff9800;")
    
    def _check_dataset(self):
        """Check dataset format and switch to dataset viewer"""
        path = self.train_data_path.text().strip()
        if not path or not Path(path).exists():
            QMessageBox.warning(self, "No Dataset", "Please select a dataset file first.")
            return
        
        # Switch to dataset viewer page
        self.train_right_stack.setCurrentIndex(1)
        
        # Load and display dataset preview
        self._load_dataset_preview(path)
    
    def _switch_to_dashboard(self):
        """Switch right panel back to training dashboard"""
        self.train_right_stack.setCurrentIndex(0)

    # ----------------------------------------------------------------------
    # Start-panel / mode helpers
    # ----------------------------------------------------------------------
    def _on_start_tile_clicked(self, mode: str, adapter_path: str) -> None:
        """A start-tile was clicked. Stash the mode for
        ``_start_training_impl`` and kick off the launch flow.
        """
        self._pending_run_mode = mode
        self._pending_resume_adapter = adapter_path or ""
        try:
            self._start_training()
            self._switch_to_dashboard()
        except Exception:
            # _start_training has its own modal-dialog error handler;
            # if it raised here, something escaped that handler.
            self._pending_run_mode = None
            self._pending_resume_adapter = ""
            raise

    def _on_run_mode_changed(self, mode: str) -> None:  # legacy no-op
        """Kept as a stub — old code paths reference this method but
        the run-mode selector widget no longer exists. The mode is now
        picked at click-time via the StartTrainingPanel tiles."""
        return

    def _on_continue_adapter_selected(self, adapter_path: str) -> None:
        """Slave the base-model picker to the chosen Continue-mode adapter.

        A Continue run MUST use the SAME base model the adapter was
        trained on. Letting the user pick adapter X (trained on base A)
        but leaving the base dropdown on B silently produced garbage
        outputs and corrupt training (LoRA matrices applied to the
        wrong Q/K/V/O weights).

        Strategy: read the adapter's ``adapter_config.json``, resolve
        the base reference to a local ``models/<sanitised>/`` dir if
        possible, and set the train_base_model dropdown to match. The
        launch path *also* hard-overrides the base for Continue mode
        (see _start_training_impl) so even if this UI sync race-loses,
        the actual training command is still correct.
        """
        try:
            ap = Path(str(adapter_path))
            if not ap.exists():
                return
            base_ref = self._resolve_adapter_base_path(ap)
            if not base_ref:
                return
            # Resolve to a model-dir slug the dropdown actually carries.
            base_p = Path(base_ref)
            slug: Optional[str] = None
            if base_p.exists():
                slug = base_p.name  # e.g. 'google__gemma-4-E4B-it'
            else:
                # If it's a hub id like 'google/gemma-4-E4B-it', look
                # for the sanitised local copy.
                cand = self.root / "models" / base_ref.replace("/", "__")
                if cand.exists():
                    slug = cand.name
                else:
                    # Last resort — show the hub id verbatim.
                    slug = base_ref.replace("/", "__")

            if not hasattr(self, "train_base_model") or not slug:
                return
            # Try to switch via index; fall back to setEditText for
            # editable combos. Avoid signaling a re-train of the
            # auto-name field — handled by valueChanged hooks.
            idx = self.train_base_model.findText(slug)
            if idx >= 0:
                self.train_base_model.setCurrentIndex(idx)
            else:
                try:
                    self.train_base_model.setEditText(slug)
                except Exception:
                    pass
            try:
                self.train_log.appendPlainText(
                    f"[INFO] Continue mode: locked base model to '{slug}' "
                    "(matches the selected adapter's base)."
                )
            except Exception:
                pass
        except Exception as exc:
            try:
                self._log_to_app_log(
                    f"[WARN] _on_continue_adapter_selected failed: {exc!r}"
                )
            except Exception:
                pass

    def _refresh_resume_state(self) -> None:
        """Rescan the configured output directory for resumable artifacts.

        Two scans:
          • Trainer checkpoints — directories named ``checkpoint-N``
            with a ``trainer_state.json`` (Trainer's signature). Newest
            wins. Reflected in the Resume label.
          • Saved adapters — directories with ``adapter_config.json``
            and ``adapter_model.safetensors``/``.bin`` (PEFT's
            signature). Sorted by mtime so the most recent run is
            preselected. Reflected in the Continue dropdown.
        """
        out_dir_str = ""
        try:
            out_dir_str = self.train_out_dir.text().strip()
        except Exception:
            pass
        if not out_dir_str:
            self._set_resume_label("(no output directory selected)", missing=True)
            self._populate_continue_combo([])
            return

        out_dir = Path(out_dir_str)
        if not out_dir.exists():
            self._set_resume_label(f"(does not exist: {out_dir})", missing=True)
            self._populate_continue_combo([])
            return

        # --- Trainer checkpoints ---
        ckpts: list[tuple[int, Path]] = []
        try:
            for p in out_dir.iterdir():
                if not p.is_dir() or not p.name.startswith("checkpoint-"):
                    continue
                if not (p / "trainer_state.json").exists():
                    continue
                try:
                    step = int(p.name.split("-", 1)[1])
                except (IndexError, ValueError):
                    continue
                ckpts.append((step, p))
        except Exception:
            ckpts = []

        if ckpts:
            ckpts.sort()
            step, ckpt_path = ckpts[-1]
            self._set_resume_label(
                f"step {step} — {ckpt_path.name}", missing=False
            )
        else:
            self._set_resume_label(
                "(none — enable Save Checkpoints, then Stop / Start to create one)",
                missing=True,
            )

        # --- Saved adapters (for Continue mode) ---
        adapters: list[tuple[float, Path]] = []
        try:
            for p in out_dir.iterdir():
                if not p.is_dir():
                    continue
                if p.name.startswith("checkpoint-"):
                    # Trainer checkpoints get their own resume path; don't
                    # offer them as "continue" targets.
                    continue
                cfg = p / "adapter_config.json"
                model_safe = p / "adapter_model.safetensors"
                model_bin = p / "adapter_model.bin"
                if cfg.exists() and (model_safe.exists() or model_bin.exists()):
                    try:
                        ref = model_safe if model_safe.exists() else model_bin
                        adapters.append((ref.stat().st_mtime, p))
                    except Exception:
                        adapters.append((0.0, p))
        except Exception:
            adapters = []

        adapters.sort(reverse=True)
        self._populate_continue_combo([p for _, p in adapters])

    def _set_resume_label(self, text: str, missing: bool) -> None:
        # The standalone Resume label is gone (replaced by the Resume
        # tile's subtitle). Forward to the StartTrainingPanel; if it
        # doesn't exist yet (early init) silently no-op.
        try:
            self.train_start_panel.set_resume_state(text, enabled=not missing)
        except Exception:
            pass

    def _populate_continue_combo(self, adapter_paths: list[Path]) -> None:
        # Forward to the StartTrainingPanel's adapter picker.
        try:
            self.train_start_panel.set_adapter_options(
                [str(p) for p in (adapter_paths or [])]
            )
        except Exception:
            pass
    
    def _load_dataset_preview(self, path: str):
        """Load first few entries from dataset and update viewer"""
        try:
            import json
            examples = []
            
            # Try loading the file (handle both JSONL and JSON array formats)
            with open(path, 'r', encoding='utf-8') as f:
                content = f.read().strip()
            
            # Try as JSONL first (one object per line)
            try:
                for i, line in enumerate(content.split('\n')[:10]):
                    if line.strip():
                        entry = json.loads(line.strip())
                        examples.append(entry)
            except:
                # Try as JSON array
                try:
                    data = json.loads(content)
                    if isinstance(data, list):
                        examples = data[:10]
                    elif isinstance(data, dict):
                        # Wrapped format like {"data": [...]} or {"entries": [...]}
                        for key in ['data', 'entries', 'examples', 'dataset', 'items']:
                            if key in data and isinstance(data[key], list):
                                examples = data[key][:10]
                                break
                        # If still empty, treat the dict itself as a single example
                        if not examples:
                            examples = [data]
                except:
                    pass
            
            # Update dataset viewer with loaded examples
            if hasattr(self, 'dataset_preview_text'):
                preview_text = ""
                for i, entry in enumerate(examples, 1):
                    preview_text += f"=== Entry {i} ===\n"
                    preview_text += json.dumps(entry, indent=2, ensure_ascii=False)
                    preview_text += "\n\n"
                
                self.dataset_preview_text.setPlainText(preview_text)
                
                # Validate format - comprehensive field detection
                if examples:
                    first = examples[0]
                    
                    # All possible field names
                    instruction_fields = ['instruction', 'prompt', 'input', 'text', 'question', 'query', 'user', 'human']
                    output_fields = ['output', 'response', 'completion', 'answer', 'assistant', 'reply', 'bot', 'gpt']
                    
                    found_instruction = [k for k in instruction_fields if k in first]
                    found_output = [k for k in output_fields if k in first]
                    has_messages = 'messages' in first
                    
                    # Show detailed format info
                    format_info = f"📊 Dataset has {len(examples)} entries shown\n\n"
                    format_info += f"🔍 Detected fields: {', '.join(first.keys())}\n\n"
                    
                    if found_instruction and found_output:
                        format_info += f"✅ Format: Instruction/Output\n"
                        format_info += f"   - Instruction field: {found_instruction[0]}\n"
                        format_info += f"   - Output field: {found_output[0]}\n"
                        format_info += f"   Status: Compatible ✓"
                        self.dataset_format_label.setText(format_info)
                        self.dataset_format_label.setStyleSheet("color: #4CAF50; font-size: 11pt;")
                    elif has_messages:
                        format_info += f"✅ Format: Chat/Messages\n"
                        format_info += f"   Status: Compatible ✓"
                        self.dataset_format_label.setText(format_info)
                        self.dataset_format_label.setStyleSheet("color: #4CAF50; font-size: 11pt;")
                    else:
                        format_info += f"⚠️ Format: Custom\n"
                        format_info += f"   No standard instruction/output fields found\n"
                        format_info += f"   Available fields: {', '.join(first.keys())}\n"
                        format_info += f"   May require conversion"
                        self.dataset_format_label.setText(format_info)
                        self.dataset_format_label.setStyleSheet("color: #ff9800; font-size: 11pt;")
                else:
                    self.dataset_format_label.setText("⚠️ No entries found in dataset")
                    self.dataset_format_label.setStyleSheet("color: #ff9800; font-size: 11pt;")
        except Exception as e:
            if hasattr(self, 'dataset_preview_text'):
                self.dataset_preview_text.setPlainText(f"Error loading dataset: {str(e)}")
                self.dataset_format_label.setText(f"❌ Error: {str(e)}")
                self.dataset_format_label.setStyleSheet("color: #f44336; font-size: 11pt;")
    
