    def _browse_train_out(self) -> None:
        d = QFileDialog.getExistingDirectory(self, "Select output folder", str(self.root))
        if d:
            self.train_out_dir.setText(d)

    def _start_training(self) -> None:
        # GROUND-TRUTH SIGNAL: write directly to logs/train_click.log
        # using only stdlib open(). No QTextEdit, no _append_terminal,
        # no nested handlers. If the click reaches this method AT ALL,
        # this line is on disk before anything else happens. Used to
        # determine — when the user reports 'instant error on click' —
        # whether the click handler is even being invoked.
        try:
            from datetime import datetime as _dt
            _gt_log = self.root / "logs" / "train_click.log"
            _gt_log.parent.mkdir(parents=True, exist_ok=True)
            with _gt_log.open("a", encoding="utf-8", errors="replace") as _f:
                _f.write(f"[{_dt.utcnow().isoformat()}Z] CLICK reached _start_training\n")
                try:
                    _f.write(
                        f"  dropdown={self.train_base_model.currentText()!r}\n"
                        f"  data_path={self.train_data_path.text()!r}\n"
                        f"  out_dir={self.train_out_dir.text()!r}\n"
                        f"  epochs={self.train_epochs.value()}\n"
                        f"  batch_size={self.train_batch.value()}\n"
                        f"  lr={self.train_lr.value()}\n"
                    )
                except Exception as _snap_exc:
                    _f.write(f"  form-snapshot exc: {_snap_exc!r}\n")
        except Exception:
            # Even this should never raise — but if it does, swallow
            # it (don't take down the click handler over a log write).
            pass

        # Forward to the original logger AND the in-UI panes via the
        # existing helper (kept so the train log pane gets the line
        # too — train_click.log is the disk-only fallback).
        try:
            self._log_to_app_log("[TRAIN-CLICK] Start Training pressed")
            try:
                snap = {
                    "dropdown": self.train_base_model.currentText(),
                    "data_path": self.train_data_path.text(),
                    "out_dir": self.train_out_dir.text(),
                    "epochs": self.train_epochs.value(),
                    "batch_size": self.train_batch.value(),
                    "lr": self.train_lr.value(),
                }
                self._log_to_app_log(f"[TRAIN-CLICK] form: {snap}")
            except Exception as snap_exc:
                self._log_to_app_log(f"[TRAIN-CLICK] form-snapshot failed: {snap_exc}")
        except Exception:
            pass

        try:
            self._start_training_impl()
        except Exception as exc:
            import traceback as _tb
            tb_text = _tb.format_exc()
            # 1) On disk — survives ALL ui closures and gives a
            #    paste-ready forensic trace.
            try:
                self._log_to_app_log(f"[TRAIN-FATAL] {type(exc).__name__}: {exc}")
                for line in tb_text.splitlines():
                    self._log_to_app_log(f"[TRAIN-FATAL]   {line}")
            except Exception:
                pass
            # 2) In the Train log pane (UI).
            try:
                self.train_log.appendPlainText("\n[FATAL] _start_training raised:")
                self.train_log.appendPlainText(f"  {type(exc).__name__}: {exc}")
                self.train_log.appendPlainText(tb_text)
            except Exception:
                pass
            # 3) In the source='train' terminal sink (UI).
            try:
                self._append_terminal(f"[FATAL] _start_training raised: {exc}", source="train")
                self._append_terminal(tb_text, source="train")
            except Exception:
                pass
            # 4) Modal dialog (so the user can't miss it).
            QMessageBox.critical(
                self,
                "Training failed to start",
                f"{type(exc).__name__}: {exc}\n\nFull traceback saved to logs/app.log "
                f"and visible in the Train log pane.",
            )
            try:
                self.train_start.setEnabled(True)
                self.train_stop.setEnabled(False)
            except Exception:
                pass

    def _start_training_impl(self) -> None:
        if self.train_proc is not None:
            QMessageBox.information(self, "Training", "Training is already running.")
            return
        data_path = self.train_data_path.text().strip()
        if not data_path:
            QMessageBox.warning(self, "Training", "Select a dataset file.")
            return

        # Get model name from the dropdown.
        model_name = self.train_base_model.currentText().strip()

        # Resolve the dropdown selection to whatever transformers can
        # actually load. Two-step:
        #   1) Compute the HF hub id (used for self-heal preflight,
        #      compat checks, and GGUF guard).
        #   2) Compute the LOCAL DIRECTORY PATH if the model is already
        #      downloaded into LLM/models/<slug>/. transformers'
        #      AutoModelForCausalLM.from_pretrained() takes EITHER a
        #      hub id (downloads) or a local dir (no network).
        #      Without this, the user's already-downloaded model gets
        #      re-fetched from huggingface.co every training run —
        #      confusing, slow, and required network access for a
        #      'local' workflow.
        def _to_hub_id(s: str) -> str:
            if "__" in s:
                return s.replace("__", "/")
            if "/" not in s and "_" in s:
                parts = s.split("_", 1)
                if len(parts) == 2:
                    return f"{parts[0]}/{parts[1]}"
            return s

        model_name_hf = _to_hub_id(model_name)

        # Self-heal preflight — block on GGUF (we offer to switch) and
        # auto-install missing training-env packages.
        if not self._preflight_training_or_repair(model_name_hf):
            return

        # If the user accepted the GGUF auto-switch, the dropdown was
        # rewritten — re-read for the actual launch.
        model_name_raw = self.train_base_model.currentText().strip()
        model_name_hf = _to_hub_id(model_name_raw)

        # Local-first model path resolution. The dropdown's raw text
        # is already the directory slug (LLM/models stores entries as
        # 'google__gemma-4-E4B-it' i.e. hub-id with '/' -> '__'). Look
        # for that directory and prefer it over the hub id.
        local_models_dir = self.root / "models"
        candidate_paths = [
            local_models_dir / model_name_raw,
            local_models_dir / model_name_hf.replace("/", "__"),
        ]
        local_model_path = None
        for p in candidate_paths:
            if p.exists() and p.is_dir() and (p / "config.json").exists():
                local_model_path = p
                break

        # finetune.py's --model-name argument is what transformers ends
        # up passing to from_pretrained(). If the local copy exists,
        # send the absolute path; transformers detects it as a local
        # directory and skips the HF download entirely. Otherwise fall
        # back to the hub id (legacy behaviour for users who haven't
        # downloaded yet). Note: we append the resolution message to
        # train_log AFTER train_log.clear() further down — so save it
        # for that point.
        if local_model_path is not None:
            base_model_for_finetune = str(local_model_path)
            _model_path_log_line = f"[INFO] Using local model directory: {local_model_path}"
        else:
            base_model_for_finetune = model_name_hf
            _model_path_log_line = (
                f"[WARN] No local copy of {model_name_hf} found at {local_models_dir}; "
                f"transformers will download from Hugging Face."
            )

        # LoRA params from the GUI. The previous TrainingConfig
        # construction read r/lr/epochs but silently used the dataclass
        # DEFAULTS for lora_alpha (16) and lora_dropout (0.0) — meaning
        # the alpha label in the UI ('LoRA Alpha: 32' for r=16) was a
        # COSMETIC lie that never reached the trainer. Fix: derive
        # alpha from r * 2 (matches the GUI label) and use a real
        # dropout. lora_dropout=0.05 is the PEFT / Unsloth
        # recommendation for fine-tuning; 0.0 disables regularisation
        # entirely and overfits small datasets.
        lora_r = int(self.train_lora_r.value())
        lora_alpha = lora_r * 2     # matches the read-only label in the UI
        lora_dropout = 0.05         # safer default than 0.0

        # The Model Name field on the Training Parameters card is the
        # user's chosen adapter directory name (e.g. "260504_gemma-4-
        # E4B-it_kbeauty_finetune_gemma4_1_0956"). Pipe it through so
        # the saved LoRA adapter is named what the user typed instead
        # of getting a meaningless "adapter_<timestamp>" suffix.
        adapter_name = ""
        try:
            adapter_name = self.train_model_name.text().strip()
        except Exception:
            adapter_name = ""

        # ------------------------------------------------------------------
        # Resume mode + checkpointing + stop file.
        # ------------------------------------------------------------------
        # The Run-mode card is the source of truth for what kind of run
        # we're launching. Translate its state into the three trainer
        # flags (--resume / --resume-adapter / --save-steps) and a
        # stop-file path that the Stop button will write to.
        # Run-mode is set by whichever tile was clicked in the
        # StartTrainingPanel. ``_on_start_tile_clicked`` stashes the
        # mode + adapter on self before calling _start_training, so we
        # read them directly here. Fall back to fresh-start if a code
        # path triggers training without going through the tiles.
        run_mode = getattr(self, "_pending_run_mode", None) or RUN_MODE_NEW
        pending_adapter = getattr(self, "_pending_resume_adapter", "") or ""
        resume_arg: Optional[str] = None
        resume_adapter_arg: Optional[Path] = None

        if run_mode == RUN_MODE_RESUME:
            resume_arg = "auto"
        elif run_mode == RUN_MODE_CONTINUE:
            if pending_adapter:
                resume_adapter_arg = Path(pending_adapter)
            if resume_adapter_arg is None:
                QMessageBox.warning(
                    self,
                    "Continue training",
                    "No adapter selected. Pick an adapter from the "
                    "Continue tile's dropdown, or click the Fresh start tile instead.",
                )
                return

            # HARD OVERRIDE: a Continue run MUST use the SAME base
            # model the adapter was trained on. The base picker can be
            # left on a different value (we slave it via the dropdown
            # signal, but a race can leave it stale, OR the user might
            # change it after picking the adapter). Whatever the form
            # says, the source of truth is the adapter's
            # ``adapter_config.json`` — read it and force the launch
            # command to use that base. Anything else produces garbage:
            # LoRA matrices learned on top of base A applied to base B.
            try:
                forced_base_ref = self._resolve_adapter_base_path(resume_adapter_arg)
            except Exception:
                forced_base_ref = None
            if forced_base_ref:
                forced_base_p = Path(forced_base_ref)
                if not forced_base_p.exists():
                    cand = self.root / "models" / forced_base_ref.replace("/", "__")
                    if cand.exists():
                        forced_base_p = cand
                forced_base_str = str(forced_base_p)
                if forced_base_str.lower() != base_model_for_finetune.lower():
                    self._log_to_app_log(
                        "[continue-override] form base="
                        f"{base_model_for_finetune!r} adapter base="
                        f"{forced_base_str!r} — using adapter's base."
                    )
                    base_model_for_finetune = forced_base_str
                    _model_path_log_line = (
                        "[INFO] Continue mode: base model overridden to match "
                        f"the adapter's training base: {forced_base_str}"
                    )

        # Save-checkpoints toggle. Active automatically when the user
        # picked Resume mode (we flipped it on in _on_run_mode_changed),
        # but they can still override it here by toggling it off.
        save_steps_val = 0
        save_total_limit_val = 2
        try:
            if self.train_save_toggle.is_enabled():
                save_steps_val = max(5, int(self.train_save_toggle.save_steps()))
        except Exception:
            save_steps_val = 0

        # Stop-file path. One per run, lives in the output dir alongside
        # the adapter. Pre-clean any stale file so the new subprocess
        # doesn't think it was pre-stopped on the first step.
        out_dir_path = Path(self.train_out_dir.text().strip())
        try:
            out_dir_path.mkdir(parents=True, exist_ok=True)
        except Exception:
            pass
        stop_file_path = out_dir_path / ".STOP_REQUESTED"
        try:
            if stop_file_path.exists():
                stop_file_path.unlink()
        except Exception:
            pass

        # Stash on self so _stop_training can write the file and
        # _start_training_impl callbacks can reference the active mode.
        self._active_run_mode = run_mode
        self._active_stop_file = stop_file_path
        self._stop_force_armed = False

        cfg = TrainingConfig(
            base_model=base_model_for_finetune,
            data_path=Path(data_path),
            output_dir=out_dir_path,
            epochs=int(self.train_epochs.value()),
            batch_size=int(self.train_batch.value()),
            learning_rate=float(self.train_lr.value()),
            max_seq_length=int(self.train_max_seq.value()),
            lora_r=lora_r,
            lora_alpha=lora_alpha,
            lora_dropout=lora_dropout,
            adapter_name=(adapter_name or None),
            resume=resume_arg,
            resume_adapter=resume_adapter_arg,
            save_steps=save_steps_val,
            save_total_limit=save_total_limit_val,
            stop_file=stop_file_path,
        )

        cmd = build_finetune_cmd(cfg)

        # Show logs immediately
        if not self.train_log.isVisible():
            self.logs_expand_btn.setChecked(True)
            self.train_log.setVisible(True)
            self.logs_expand_btn.setText("▲ Hide Logs")

        # Initialize training output buffer
        self._train_output_buffer = ""
        self._train_line_count = 0
        self.loss_history = []
        self._total_train_steps = None
        self._current_train_step = None
        
        # SNAPSHOT training parameters so dashboard stays consistent even if user changes GUI values
        self._active_epochs = int(self.train_epochs.value())
        self._active_lr = float(self.train_lr.value())
        
        # Reset dashboard metrics for fresh run
        try:
            self._update_metric_card(self.epoch_card, f"0/{self._active_epochs}")
            self._update_metric_card(self.steps_card, "0/?")
            self._update_metric_card(self.loss_card, "--")
            self._update_metric_card(self.eta_card, "--m --s")
            self._update_metric_card(self.speed_card, "-- s/s")
            self._update_metric_card(self.learning_rate_card, f"{self._active_lr:.2e}")
        except Exception:
            pass
        # Clear loss chart
        try:
            if hasattr(self, 'loss_chart_label'):
                self.loss_chart_label.clear()
        except Exception:
            pass
        
        env = QProcessEnvironment.systemEnvironment()
        env.insert("PYTHONIOENCODING", "utf-8")
        env.insert("PYTHONUTF8", "1")
        env.insert("PYTHONUNBUFFERED", "1")  # Force unbuffered output (even stronger than -u)
        env.insert("PYTHONLEGACYWINDOWSSTDIO", "0")  # Use new Windows stdio for better real-time output
        if hasattr(self, 'gpu_select') and self.gpu_select.isEnabled():
            selected_display_idx = self.gpu_select.currentIndex()
            real_cuda_idx = None
            if hasattr(self, 'gpu_index_map') and self.gpu_index_map and selected_display_idx < len(self.gpu_index_map):
                real_cuda_idx = self.gpu_index_map[selected_display_idx]
            else:
                real_cuda_idx = selected_display_idx
            # Pass the CUDA index VERBATIM. No CUDA_DEVICE_ORDER
            # override — the dropdown was built from torch.cuda's own
            # view in the workload venv, so the index here is exactly
            # what torch.cuda will return there. Setting
            # CUDA_DEVICE_ORDER=PCI_BUS_ID here would reorder the
            # mapping and silently route to a different GPU.
            env.insert("CUDA_VISIBLE_DEVICES", str(real_cuda_idx))
            self.train_log.appendPlainText(
                f"[INFO] Using {self.gpu_select.currentText()} "
                f"(CUDA_VISIBLE_DEVICES={real_cuda_idx})"
            )

        proc = HiddenSubprocessRunner(self)
        proc.readyReadStandardOutput.connect(lambda: self._append_training_output(proc))
        proc.errorOccurred.connect(lambda err: self._on_training_error(proc, err))
        proc.finished.connect(lambda code, status: self._train_finished(code, status))

        self.train_log.clear()
        self.train_log.appendPlainText("=== Starting Training ===")
        self.train_log.appendPlainText(_model_path_log_line)
        self.train_log.appendPlainText(f"Command: {' '.join(cmd)}")
        self.train_log.appendPlainText("=" * 50)
        self._append_terminal("=== Starting Training ===", source="train")
        self._append_terminal(_model_path_log_line, source="train")
        self._append_terminal(f"Command: {' '.join(cmd)}", source="train")

        self.train_start.setEnabled(False)
        self.train_stop.setEnabled(True)
        try:
            self.train_start_panel.set_running(True)
        except Exception:
            pass

        proc.start(
            cmd,
            working_directory=str(self.root),
            process_environment=qprocess_environment_to_environ(env),
        )
        if not proc.waitForStarted(5000):
            self.train_log.appendPlainText("\n[ERROR] Failed to start training process!")
            self._append_terminal("[ERROR] Failed to start training process!", source="train")
            self.train_start.setEnabled(True)
            self.train_stop.setEnabled(False)
            try:
                self.train_start_panel.set_running(False)
                self._refresh_resume_state()
            except Exception:
                pass
            return

        self.train_proc = proc
        self.train_log.appendPlainText("[INFO] Training process started successfully")
        self._append_terminal("[INFO] Training process started successfully", source="train")

        # Status pill -> running.
        try:
            mode_label = {
                RUN_MODE_NEW: "fresh run",
                RUN_MODE_RESUME: "resuming from checkpoint",
                RUN_MODE_CONTINUE: "continuing adapter",
            }.get(getattr(self, "_active_run_mode", RUN_MODE_NEW), "")
            self.train_status_pill.set_state("running", mode_label)
        except Exception:
            pass

        # Reset stop-button state for the new run (graceful, not armed).
        self._stop_force_armed = False
        self.train_stop.setText("⏹  Stop")

        # Start background timer for GPU stats during training
        if not hasattr(self, '_train_stats_timer'):
            self._train_stats_timer = QTimer(self)
            self._train_stats_timer.timeout.connect(self._update_training_stats_periodic)

        self._train_stats_timer.start(2000) # Update every 2 seconds

    def _preflight_training_or_repair(self, model_name_hf: str) -> bool:
        """Self-heal the training launch pipeline. Returns True if the
        caller should proceed; False if the user cancelled or the repair
        couldn't recover.

        Two heals:

        1. **GGUF guard with auto-switch.** GGUF is quantised inference-only
           weights; Unsloth needs the bf16 source. We offer to switch the
           model dropdown to the matching non-GGUF id with a single click.
        2. **Missing training packages auto-install.** ``unsloth`` / ``trl``
           / ``peft`` / ``bitsandbytes`` install on demand into the
           training venv with a progress dialog — no "open a terminal and
           run pip" hand-off.
        """
        from desktop_app import training_env_manager as tem

        # ---- GGUF guard ------------------------------------------------
        if "gguf" in model_name_hf.lower():
            replacement = tem.non_gguf_variant(model_name_hf)
            box = QMessageBox(self)
            box.setIcon(QMessageBox.Warning)
            box.setWindowTitle("GGUF cannot be fine-tuned")
            box.setText(
                "GGUF files are quantised, inference-only weights for "
                "llama.cpp. Fine-tuning needs the original (non-GGUF) model."
            )
            box.setInformativeText(
                f"<b>You picked:</b>  {model_name_hf}<br>"
                f"<b>Switch to:</b>  {replacement}"
            )
            switch_btn = box.addButton("Switch to non-GGUF", QMessageBox.AcceptRole)
            box.addButton(QMessageBox.Cancel)
            box.exec()
            if box.clickedButton() is not switch_btn:
                return False
            # Apply the swap to the dropdown.
            try:
                idx = self.train_base_model.findText(replacement)
                if idx >= 0:
                    self.train_base_model.setCurrentIndex(idx)
                else:
                    # Editable combo — just set the text. The model picker
                    # will show this as a "you'll need to download it"
                    # state on next refresh; cleaner than blocking here.
                    self.train_base_model.setEditText(replacement)
            except Exception:
                pass
            self.train_log.appendPlainText(
                f"[INFO] Switched model from {model_name_hf} → {replacement}"
            )

        # ---- Training-env auto-install --------------------------------
        try:
            cur = tem.status(Path(self.root))
        except Exception as exc:
            QMessageBox.warning(self, "Training env check", str(exc))
            return False

        if not cur.venv_python_exists:
            QMessageBox.warning(
                self,
                "Training environment missing",
                f"OWLLM Python interpreter not found:\n  {cur.venv_python_path}\n\n"
                "OWLLM expects the canonical environment under LLM/.envs/"
                "<profile>/.venv (e.g. cu121-stable). Re-run the OWLLM "
                "installer to recreate it — that step also installs the "
                "heavy ML deps (unsloth, torch+CUDA, trl, peft, "
                "bitsandbytes).",
            )
            return False

        if cur.fully_ready:
            return True

        # Modal progress dialog while pip installs the missing packages.
        # Indeterminate range (0,0) — no per-step progress from pip
        # without parsing its output, but the install is bounded to 15min
        # in the manager and the user sees status text per package.
        from PySide6.QtWidgets import QProgressDialog
        progress = QProgressDialog(
            f"Installing {len(cur.missing_packages)} training package(s)…",
            "Cancel",
            0, 0, self,
        )
        progress.setWindowTitle("Self-installing training environment")
        progress.setMinimumDuration(0)
        progress.setAutoClose(False)
        progress.show()

        # Run the install on a worker thread so the UI keeps painting.
        import threading
        result = {"err": None}

        def progress_cb(msg: str) -> None:
            from PySide6.QtCore import QMetaObject, Q_ARG, Qt
            QMetaObject.invokeMethod(
                progress, "setLabelText",
                Qt.QueuedConnection, Q_ARG(str, msg),
            )
            self._append_terminal(f"[train-env] {msg}", source="train")

        def worker():
            try:
                tem.ensure_ready(Path(self.root), progress=progress_cb)
            except Exception as exc:  # noqa: BLE001
                result["err"] = exc
            finally:
                from PySide6.QtCore import QMetaObject, Qt
                QMetaObject.invokeMethod(
                    progress, "close", Qt.QueuedConnection,
                )

        t = threading.Thread(target=worker, daemon=True, name="train-env-install")
        t.start()
        # Block the GUI on the dialog (modal). It closes itself on success
        # / failure via QMetaObject.invokeMethod above.
        progress.exec()
        t.join(timeout=2)

        if result["err"] is not None:
            QMessageBox.critical(
                self,
                "Training env install failed",
                f"Could not auto-install training packages:\n\n{result['err']}",
            )
            return False

        self.train_log.appendPlainText(
            "[INFO] Training environment auto-installed successfully."
        )
        self._append_terminal(
            "[INFO] Training environment auto-installed successfully.",
            source="train",
        )
        return True

    def _on_training_error(self, proc, error):
        """Handle training process errors with real diagnostics.

        Two bugs lived here:
          1. Dict-keyed by QProcess.FailedToStart enum, but PySide6's
             signal can pass an int that doesn't compare-hash cleanly
             with the enum member depending on the runtime — so users
             saw 'Error code: 0' instead of the readable label.
             Fix: cast both sides to int.
          2. 'FailedToStart' is reported by Qt for ANY very-quick
             non-zero exit on Windows, even when the process DID
             start and produced stderr. So 'Failed to start' was a
             lie 90% of the time; the actual error was buried in
             stderr that nobody read.
             Fix: drain stdout/stderr from the proc and surface them.
        """
        # 1) Translate the enum/int to a label safely.
        try:
            error_int = int(error)
        except Exception:
            error_int = error
        labels = {
            int(QProcess.FailedToStart): "QProcess: FailedToStart",
            int(QProcess.Crashed):       "QProcess: Crashed",
            int(QProcess.Timedout):      "QProcess: Timedout",
            int(QProcess.WriteError):    "QProcess: WriteError",
            int(QProcess.ReadError):     "QProcess: ReadError",
            int(QProcess.UnknownError):  "QProcess: UnknownError",
        }
        label = labels.get(error_int, f"QProcess error #{error_int}")

        # 2) Drain whatever stdout/stderr the child produced before exit.
        #    This is where the actual Python traceback lives — not in
        #    the enum value Qt hands us. Empty bytes -> 'no output'.
        captured: list[str] = []
        try:
            blob = bytes(proc.readAllStandardOutput()).decode(
                "utf-8", errors="replace"
            ).strip()
            if blob:
                captured.append(blob)
        except Exception:
            pass
        try:
            blob = bytes(proc.readAllStandardError()).decode(
                "utf-8", errors="replace"
            ).strip()
            if blob:
                captured.append(blob)
        except Exception:
            pass

        self.train_log.appendPlainText(f"\n[ERROR] {label}")
        self._append_terminal(f"[ERROR] {label}", source="train")
        if captured:
            output = "\n".join(captured)
            # Show a HEAD + TAIL of the output if it's huge — but never
            # silently drop. The middle is in the persisted log already.
            shown = output if len(output) <= 4000 else f"{output[:1500]}\n...\n{output[-2000:]}"
            self.train_log.appendPlainText("[ERROR] Captured output from finetune.py:")
            self.train_log.appendPlainText(shown)
            self._append_terminal("[ERROR] Captured output from finetune.py:", source="train")
            for line in shown.splitlines():
                self._append_terminal(line, source="train")
        else:
            # No output from the child — this really IS likely a
            # process-launch problem (bad PATH, antivirus blocking,
            # exec bit issue). Point the user at the verifiable thing.
            self.train_log.appendPlainText(
                "[ERROR] No output captured from finetune.py. The interpreter "
                "may have failed to launch. Verify standalone:"
            )
            self.train_log.appendPlainText(
                f"  > {self._get_target_venv_python() or 'python'} -u finetune.py --help"
            )

        self.train_start.setEnabled(True)
        self.train_stop.setEnabled(False)
        try:
            self.train_start_panel.set_running(False)
            # Refresh tile context so freshly-written checkpoint /
            # adapter shows up immediately on the next launch.
            self._refresh_resume_state()
        except Exception:
            pass

    def _stop_training(self) -> None:
        """Stop the running training process — graceful by default, with
        a 4-second force-kill escalation on second click.

        Why two-stage:
          • Graceful (1st click) writes a sentinel file that finetune.py
            polls every step. The trainer halts at the next step
            boundary, **saves a checkpoint**, releases GPU memory, and
            exits cleanly. Subsequent ``Resume`` runs then pick up
            exactly where this stopped.
          • Force-kill (2nd click within 4s, OR if graceful didn't
            release in 30s) calls QProcess.kill(). This is the last
            resort for a wedged subprocess — no checkpoint is saved,
            and any in-flight CUDA op leaks until the OS reaps the
            process. Reserved for cases where the trainer is unresponsive.
        """
        if self.train_proc is None:
            return

        # Second click within ~4s OR force-armed externally -> kill.
        if getattr(self, "_stop_force_armed", False):
            self._force_kill_training()
            return

        # First click: graceful stop.
        stop_path = getattr(self, "_active_stop_file", None)
        wrote_file = False
        if stop_path is not None:
            try:
                Path(stop_path).parent.mkdir(parents=True, exist_ok=True)
                Path(stop_path).write_text(
                    "stop requested by GUI\n", encoding="utf-8"
                )
                wrote_file = True
            except Exception as exc:
                self.train_log.appendPlainText(
                    f"\n[WARN] Could not write stop file ({stop_path}): {exc}. "
                    "Falling back to immediate terminate."
                )

        if wrote_file:
            self.train_log.appendPlainText(
                "\n[INFO] Stop requested — finetune.py will save a "
                "checkpoint and exit at the next step boundary."
            )
            self._append_terminal(
                "[INFO] Graceful stop requested.", source="train",
            )
            try:
                self.train_status_pill.set_state(
                    "stopping", "press Stop again to force-kill"
                )
            except Exception:
                pass
            self.train_stop.setText("⛔  Force kill")
            self._stop_force_armed = True

            # Auto-disarm the force-kill latch after 4s so an absent
            # second click doesn't leave the button silently armed for
            # the next click much later.
            QTimer.singleShot(4000, self._disarm_force_kill)
            # Last-resort safety net: if graceful stop hasn't released
            # the process in 30s, kill it. This handles a wedged
            # trainer (CUDA op blocking, infinite loop in callback) so
            # the user isn't stuck.
            QTimer.singleShot(30000, self._force_kill_if_still_running)
        else:
            # No stop-file path was given OR write failed — go straight
            # to terminate(). Same behaviour as before this refactor.
            self._force_kill_training()

    def _disarm_force_kill(self) -> None:
        """Reset the Stop button after the 4s force-kill window expires.

        Called by a single-shot QTimer. If the process already exited
        gracefully, the button is already disabled by ``_train_finished``
        — we just clear the latch + relabel for the next run.
        """
        if self.train_proc is None:
            return
        if not getattr(self, "_stop_force_armed", False):
            return
        # Process is still running but the force-kill window expired.
        # Relabel back to the soft action so the next click stays graceful.
        self._stop_force_armed = False
        try:
            self.train_stop.setText("⏹  Stop")
        except Exception:
            pass

    def _force_kill_if_still_running(self) -> None:
        """30s safety net for a wedged trainer that didn't honour the
        stop-file. No-op if the process already exited or graceful
        stop completed."""
        if self.train_proc is None:
            return
        try:
            self.train_log.appendPlainText(
                "\n[WARN] Graceful stop did not release the trainer "
                "within 30s — force-killing."
            )
        except Exception:
            pass
        self._force_kill_training()

    def _force_kill_training(self) -> None:
        """Hard-stop the subprocess. Used either by an explicit second
        Stop click or by the 30s wedged-process safety net."""
        if self.train_proc is None:
            return
        if hasattr(self, '_train_stats_timer'):
            self._train_stats_timer.stop()
        try:
            self.train_log.appendPlainText(
                "\n[INFO] Force-killing training process (no checkpoint will "
                "be saved by this code path; the OS will reclaim VRAM on exit)."
            )
        except Exception:
            pass
        try:
            self.train_proc.terminate()
            if not self.train_proc.waitForFinished(5000):
                self.train_proc.kill()
        except Exception as exc:
            try:
                self.train_log.appendPlainText(
                    f"[WARN] terminate/kill raised: {exc}"
                )
            except Exception:
                pass
        self._stop_force_armed = False

    def _train_finished(self, exit_code=0, exit_status=QProcess.NormalExit) -> None:
        # Stop stats timer
        if hasattr(self, '_train_stats_timer'):
            self._train_stats_timer.stop()
            
        # READ ANY REMAINING DATA from the process
        if self.train_proc:
            remaining_data = bytes(self.train_proc.readAllStandardOutput())
            if remaining_data:
                text = remaining_data.decode("utf-8", errors="replace")
                if not hasattr(self, '_train_output_buffer'):
                    self._train_output_buffer = ""
                self._train_output_buffer += text

        # Flush any remaining output in the buffer
        if hasattr(self, '_train_output_buffer') and self._train_output_buffer:
            remaining = self._train_output_buffer.strip()
            if remaining:
                # Process the last segment as metrics/logs
                # Split by \n or \r to handle final lines
                import re
                lines = re.split(r'[\n\r]+', remaining)
                for line in lines:
                    line = line.strip()
                    if line:
                        self._parse_single_line_metrics(line)
                        self._filter_and_append_to_train_log(line)
            self._train_output_buffer = ""
            
        status_str = "NormalExit" if exit_status == QProcess.NormalExit else "CrashExit"
        self.train_log.appendPlainText(f"\n[INFO] Training process finished. exit_code={exit_code}, status={status_str}")
        self._append_terminal(f"[INFO] Training process finished. exit_code={exit_code}, status={status_str}", source="train")

        # On a successful run, give the user a plain-language verdict
        # so a non-ML-savvy operator can tell at a glance whether the
        # adapter is worth keeping. Heuristic only — a true judgement
        # needs eval data — but it catches the common pathological
        # cases (no convergence at all, tiny dataset, NaN loss).
        # Treat the run as successful when EITHER the exit code is
        # clean OR the adapter clearly made it to disk. The latter
        # covers the Windows CUDA-teardown crash (exit -1073741819 /
        # 0xC0000005) that fires AFTER the adapter is fully written.
        _tail_for_save = getattr(self, "_train_raw_tail", "") or ""
        _adapter_saved_marker = (
            "Finetuning complete!" in _tail_for_save
            or "LoRA adapter saved successfully" in _tail_for_save
        )
        _treat_as_success = (
            (exit_code == 0 and exit_status == QProcess.NormalExit)
            or _adapter_saved_marker
        )
        if _treat_as_success:
            try:
                self._render_training_summary()
            except Exception as e:
                # Never let a summary-render bug mask a successful run.
                self.train_log.appendPlainText(
                    f"[WARN] Could not render training summary: {e}"
                )

        # On crash / non-zero exit, dump the rolling raw tail into the
        # train_log so the user actually sees the traceback even if
        # the filter ate every line during the run. Persist it to disk
        # too so post-mortems work after the window closes.
        if exit_code != 0 or exit_status != QProcess.NormalExit:
            tail = getattr(self, "_train_raw_tail", "") or ""
            if tail.strip():
                self.train_log.appendPlainText(
                    "\n--- RAW OUTPUT TAIL (last 8 KB, unfiltered) ---"
                )
                for line in tail.splitlines():
                    self.train_log.appendPlainText(line)
                self.train_log.appendPlainText("--- end raw tail ---\n")
                # Persist to disk too.
                try:
                    crash_log = self.root / "logs" / "train_crash.log"
                    crash_log.parent.mkdir(parents=True, exist_ok=True)
                    from datetime import datetime as _dt
                    with crash_log.open("a", encoding="utf-8", errors="replace") as _f:
                        _f.write(
                            f"\n=== {_dt.utcnow().isoformat()}Z exit={exit_code} status={status_str} ===\n"
                        )
                        _f.write(tail)
                        _f.write("\n")
                except Exception:
                    pass
            else:
                self.train_log.appendPlainText(
                    "[WARN] Process crashed but no raw output captured. "
                    "If this keeps happening, check logs/spawn.log."
                )

        # Reset the rolling tail for the next run.
        self._train_raw_tail = ""

        # Status pill — terminal state. We distinguish three cases:
        #   - normal exit + non-zero code  : failed
        #   - normal exit + code 0         : completed (or 'stopped'
        #                                    if user requested stop)
        #   - crash exit                   : failed
        # The 'stopped vs completed' signal comes from whether the
        # stop file was ever armed during the run (we persist that on
        # self._stop_force_armed-or-was-armed). Easier proxy: the stop
        # file no longer exists AND either the user clicked Stop OR
        # the trainer wrote 'stopped early by user request' in its log.
        try:
            stopped_by_user = False
            adapter_saved = False
            try:
                tail = getattr(self, "_train_raw_tail", "") or ""
                stopped_by_user = "stopped early by user" in tail
                # Did finetune.py actually finish saving the adapter
                # before the process died? If yes, the run succeeded
                # regardless of the exit code. The trainer prints this
                # exact line at the end of save_pretrained — and the
                # adapter dir is on disk by that point. A subsequent
                # CUDA-teardown crash (Windows-specific exit code
                # 0xC0000005 / -1073741819 is the canonical example)
                # affects the process, not the artefact. Treating it
                # as a failure scares users off perfectly good adapters.
                if "Finetuning complete!" in tail or "LoRA adapter saved successfully" in tail:
                    adapter_saved = True
            except Exception:
                pass

            # Cross-check on disk: if any adapter directory under
            # ``train_out_dir`` was modified within the last 60 seconds
            # AND has the required PEFT files, treat as saved.
            if not adapter_saved:
                try:
                    out_dir = Path(self.train_out_dir.text().strip())
                    if out_dir.exists():
                        import time as _time
                        cutoff = _time.time() - 60
                        for d in out_dir.iterdir():
                            if not d.is_dir() or d.name.startswith("checkpoint-"):
                                continue
                            cfg = d / "adapter_config.json"
                            saf = d / "adapter_model.safetensors"
                            binf = d / "adapter_model.bin"
                            if cfg.exists() and (saf.exists() or binf.exists()):
                                try:
                                    if (saf if saf.exists() else binf).stat().st_mtime >= cutoff:
                                        adapter_saved = True
                                        break
                                except Exception:
                                    pass
                except Exception:
                    pass

            if adapter_saved and (exit_status != QProcess.NormalExit or exit_code != 0):
                # The artefact is fine; only teardown crashed. Tell the
                # user the truth: it succeeded. Add a short note so the
                # log search ('exit code -1073741819') still reaches the
                # explanation.
                self.train_status_pill.set_state(
                    "done", "saved (Windows teardown crash — harmless)"
                )
                self.train_log.appendPlainText(
                    f"[INFO] Adapter saved successfully BEFORE the cleanup crash "
                    f"(exit {exit_code}). The crash happened during CUDA context "
                    "teardown and does not affect the saved adapter — it is on "
                    "disk and ready to use."
                )
            elif exit_status != QProcess.NormalExit or exit_code != 0:
                self.train_status_pill.set_state(
                    "failed", f"exit code {exit_code}"
                )
            elif stopped_by_user:
                self.train_status_pill.set_state(
                    "stopped", "Resume picks up from the saved checkpoint"
                )
            else:
                self.train_status_pill.set_state("done", "")
        except Exception:
            pass

        # Clear stale stop-file state and refresh resume / continue
        # selectors so a freshly written checkpoint or adapter shows up
        # for the next run.
        try:
            if getattr(self, "_active_stop_file", None) is not None:
                sf = Path(self._active_stop_file)
                if sf.exists():
                    sf.unlink()
        except Exception:
            pass
        self._active_stop_file = None
        self._stop_force_armed = False
        try:
            self.train_stop.setText("⏹  Stop")
        except Exception:
            pass
        try:
            self._refresh_resume_state()
        except Exception:
            pass

        self.train_proc = None
        self.train_start.setEnabled(True)
        self.train_stop.setEnabled(False)
        try:
            self.train_start_panel.set_running(False)
        except Exception:
            pass
        self._refresh_locals()

        # Post-training: offer to convert the freshly-saved adapter to
        # GGUF. The Transformers backend is 3-8x slower than llama.cpp
        # for the same weights — a one-time conversion turns "test in
        # the GUI" speeds into "production chat" speeds. We only ask
        # when the run actually saved an adapter and the run wasn't a
        # user-stopped checkpoint (those are still incomplete).
        try:
            if adapter_saved and not stopped_by_user:
                self._maybe_offer_gguf_conversion()
        except Exception:
            logger.exception("could not offer GGUF conversion after training")

    def _maybe_offer_gguf_conversion(self) -> None:
        """Prompt the user to convert the just-trained adapter to GGUF.

        Locates the most recently saved adapter under the trainer's
        output dir and asks whether to convert. Skipped silently when
        we can't find an adapter so the prompt never appears spuriously.
        """
        try:
            out_dir = Path(self.train_out_dir.text().strip())
            if not out_dir.exists():
                return
            adapters = []
            for d in out_dir.iterdir():
                if not d.is_dir() or d.name.startswith("checkpoint-"):
                    continue
                cfg = d / "adapter_config.json"
                saf = d / "adapter_model.safetensors"
                binf = d / "adapter_model.bin"
                if cfg.exists() and (saf.exists() or binf.exists()):
                    adapters.append((d.stat().st_mtime, d))
            if not adapters:
                return
            adapters.sort(reverse=True)
            adapter_dir = adapters[0][1]
        except Exception:
            return

        # Resolve the base model path the adapter was trained against.
        base_path = ""
        try:
            ti = adapter_dir / "training_info.json"
            if ti.exists():
                meta = json.loads(ti.read_text(encoding="utf-8"))
                base_path = (meta or {}).get("base_model_path") or (meta or {}).get("model_name") or ""
        except Exception:
            pass
        if not base_path:
            try:
                base_path = self.train_base_model.currentText().strip()
                if base_path and not Path(base_path).exists():
                    base_path = str((self.root / "models" / base_path).resolve())
            except Exception:
                base_path = ""
        if not base_path or not Path(base_path).exists():
            return

        from PySide6.QtWidgets import QMessageBox
        msg = QMessageBox(self)
        msg.setWindowTitle("Convert to GGUF?")
        msg.setIcon(QMessageBox.Question)
        msg.setTextFormat(Qt.RichText)
        msg.setText(
            f"<b>Adapter saved:</b> {adapter_dir.name}<br><br>"
            "Convert it to <b>GGUF</b> for 3–8× faster chat / agent / "
            "Telegram inference?"
        )
        msg.setInformativeText(
            "<p>The Transformers backend is slow because it runs in pure "
            "PyTorch. GGUF runs on llama.cpp with fused CUDA kernels and "
            "quantised weights.</p>"
            "<p>Conversion happens in the background:<br>"
            "&nbsp;&nbsp;1. merge LoRA into base (~30 s)<br>"
            "&nbsp;&nbsp;2. convert HF → GGUF fp16 (~1–2 min)<br>"
            "&nbsp;&nbsp;3. quantise to <b>Q5_K_M</b> (~30 s)</p>"
            "<p>The result lands in <code>models/&lt;adapter&gt;__gguf/</code> "
            "and shows up in every model dropdown automatically.</p>"
        )
        btn_yes = msg.addButton("Convert now (Q5_K_M)", QMessageBox.AcceptRole)
        msg.addButton("Skip", QMessageBox.RejectRole)
        msg.exec()
        if msg.clickedButton() is not btn_yes:
            return

        self._convert_adapter_to_gguf_async(
            adapter_dir=adapter_dir,
            base_model_path=Path(base_path),
            quant="Q5_K_M",
        )

    def _convert_adapter_to_gguf_async(
        self,
        adapter_dir: "Path",
        base_model_path: "Path",
        quant: str = "Q5_K_M",
    ) -> None:
        """Spawn the adapter→GGUF pipeline as a subprocess and stream
        progress into the train log.

        Runs against the training env's Python so PEFT, torch, and bf16
        are all available. The llama.cpp converter and quantizer are
        auto-discovered inside the script.
        """
        out_root = self.root / "models" / f"{adapter_dir.name}__gguf"
        out_root.mkdir(parents=True, exist_ok=True)

        # The training env is the only one with PEFT + torch + bf16
        # support. Falls back to sys.executable defensively.
        train_python = self.root / ".envs" / "tf-cu121-t25-base-stable" / ".venv" / "Scripts" / "python.exe"
        if not train_python.exists():
            train_python = Path(sys.executable)

        script = self.root / "core" / "adapter_to_gguf.py"
        cmd = [
            str(train_python), "-u", str(script),
            "--base-model", str(base_model_path),
            "--adapter-dir", str(adapter_dir),
            "--output-dir", str(out_root),
            "--quant", quant,
            "--register",
        ]

        self.train_log.appendPlainText("\n=== Converting adapter to GGUF ===")
        self.train_log.appendPlainText("Command: " + " ".join(cmd))
        self.train_log.appendPlainText("=" * 50)
        try:
            self.train_status_pill.set_state("converting", "merging + quantising → GGUF")
        except Exception:
            pass

        proc = QProcess(self)
        proc.setProcessChannelMode(QProcess.MergedChannels)
        proc.setWorkingDirectory(str(self.root))

        def _on_out():
            try:
                data = bytes(proc.readAllStandardOutput()).decode("utf-8", errors="replace")
                if data:
                    self.train_log.appendPlainText(data.rstrip())
            except Exception:
                pass

        def _on_done(exit_code: int, _exit_status):
            self.train_log.appendPlainText(
                f"\n[adapter-to-gguf] process finished. exit_code={exit_code}"
            )
            if exit_code == 0:
                try:
                    self.train_status_pill.set_state("done", "GGUF ready — picker refreshed")
                except Exception:
                    pass
                try:
                    self._refresh_locals()
                except Exception:
                    pass
            else:
                try:
                    self.train_status_pill.set_state("failed", f"GGUF convert exit {exit_code}")
                except Exception:
                    pass

        proc.readyReadStandardOutput.connect(_on_out)
        proc.finished.connect(_on_done)
        proc.start(cmd[0], cmd[1:])
        self._gguf_convert_proc = proc

    def _render_training_summary(self) -> None:
        """Append a plain-language quality summary to the training log.

        Goal: a user who's never trained an LLM should be able to look
        at this and know whether their adapter is worth keeping.
        """
        history = list(getattr(self, "loss_history", []) or [])
        if not history:
            self.train_log.appendPlainText(
                "\n┌─ TRAINING SUMMARY ───────────────────────────────────"
            )
            self.train_log.appendPlainText(
                "│ No loss data captured. The run completed but the dashboard"
            )
            self.train_log.appendPlainText(
                "│ never received a metrics line — try increasing the dataset"
            )
            self.train_log.appendPlainText(
                "│ size or check the Training Logs tab for warnings."
            )
            self.train_log.appendPlainText(
                "└──────────────────────────────────────────────────────\n"
            )
            return

        # Sort by step in case parser inserted out-of-order entries.
        history.sort(key=lambda x: x[0])
        first_step, first_loss = history[0]
        last_step, _last_raw = history[-1]
        steps_logged = len(history)

        # Use a smoothed tail (mean of last 10% or last 10 steps, whichever
        # is larger) for the verdict. Training loss spikes hard step-to-step
        # — judging convergence on a single noisy point is misleading.
        tail_n = max(10, steps_logged // 10)
        tail = [l for (_s, l) in history[-tail_n:]]
        last_loss = sum(tail) / len(tail) if tail else _last_raw

        # Detect NaN/Inf — the loss tracker stores floats parsed from
        # stdout, so they can carry through.
        import math as _math
        if (
            _math.isnan(first_loss) or _math.isinf(first_loss)
            or _math.isnan(last_loss) or _math.isinf(last_loss)
        ):
            verdict = "❌ FAILED"
            verdict_detail = (
                "The training loss became NaN or infinite — the optimizer "
                "diverged. Try lowering the learning rate (e.g. 1e-4 → 5e-5) "
                "or reducing LoRA r/alpha."
            )
            drop = 0.0
            drop_pct = 0.0
        else:
            drop = first_loss - last_loss
            drop_pct = (drop / first_loss * 100.0) if first_loss > 0 else 0.0

            # Verdict thresholds. These are heuristic — calibrated for
            # 1-3 epoch SFT runs on small instruction datasets.
            if last_loss > 5.0 or drop_pct < 5.0:
                verdict = "⚠️  POOR"
                verdict_detail = (
                    "The loss barely moved. The model didn't really learn "
                    "from your data. Common causes: dataset too small "
                    "(<200 examples), wrong format, or the base model is "
                    "already fluent in this domain. Try more epochs (3-5) "
                    "or a higher learning rate (4e-4)."
                )
            elif drop_pct < 20.0:
                verdict = "🟡 OK-ISH"
                verdict_detail = (
                    "Some learning happened but the convergence is weak. "
                    "The adapter may help slightly. Consider another epoch "
                    "or doubling the LoRA rank to give the adapter more "
                    "capacity."
                )
            elif drop_pct < 50.0:
                verdict = "🟢 GOOD"
                verdict_detail = (
                    "Solid convergence. The adapter has clearly absorbed "
                    "your dataset. Test it on held-out prompts before "
                    "trusting it in production."
                )
            else:
                verdict = "🌟 EXCELLENT"
                verdict_detail = (
                    "Very strong convergence. Watch out for overfitting "
                    "on small datasets — test on prompts NOT in your "
                    "training set to make sure it still generalises."
                )

        # Pretty print to the log.
        bar = "═" * 56
        self.train_log.appendPlainText(f"\n┌─ TRAINING SUMMARY {bar[:38]}")
        self.train_log.appendPlainText(f"│  Verdict:        {verdict}")
        self.train_log.appendPlainText(
            f"│  Loss:           {first_loss:.4f}  →  {last_loss:.4f}"
        )
        sign = "↓" if drop >= 0 else "↑"
        self.train_log.appendPlainText(
            f"│  Reduction:      {sign} {abs(drop):.4f}  ({drop_pct:+.1f}%)"
        )
        self.train_log.appendPlainText(
            f"│  Steps logged:   {steps_logged} (step {first_step} → {last_step})"
        )

        # Wrap the verdict_detail to fit nicely under the bar.
        words = verdict_detail.split()
        line, lines = "", []
        for w in words:
            if len(line) + len(w) + 1 > 64:
                lines.append(line)
                line = w
            else:
                line = (line + " " + w).strip()
        if line:
            lines.append(line)
        self.train_log.appendPlainText("│")
        for ln in lines:
            self.train_log.appendPlainText(f"│  {ln}")
        self.train_log.appendPlainText(
            "└──────────────────────────────────────────────────────────\n"
        )

    # ---------------- Test tab ----------------
    def _build_test_tab(self) -> QWidget:
        """
        Build test page with sub-tabs for:
        - 🧪 Test (regular side-by-side inference)
        - 🔧 Tool Chat (tool-enabled side-by-side inference)
        
        NOTE: These sub-pages are created eagerly (not lazy-loaded) to ensure
        any startup refresh routines (e.g. `_refresh_locals`) can safely access
        widgets like `test_model_a` without crashing the launcher.
        """
        from PySide6.QtWidgets import QTabWidget
        
        w = QWidget()
        layout = QVBoxLayout(w)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(0)
        
        # Sub-tabs
        sub_tabs = QTabWidget()
        sub_tabs.setStyleSheet("""
            QTabWidget::pane {
                border: none;
                background: transparent;
            }
            QTabBar::tab {
                background: rgba(30, 30, 40, 0.8);
                color: white;
                padding: 10px 20px;
                border: none;
                border-top-left-radius: 6px;
                border-top-right-radius: 6px;
                font-size: 12pt;
                font-weight: 600;
                min-height: 22px;
            }
            QTabBar::tab:selected {
                background: rgba(102, 126, 234, 0.8);
            }
            QTabBar::tab:hover {
                background: rgba(102, 126, 234, 0.6);
            }
        """)
        
        # Store reference so other code can navigate sub-tabs
        self.test_sub_tabs = sub_tabs
        self._test_sub_pages_created = {}  # kept for backward-compat, not used for eager pages
        
        # Eagerly create all test sub-pages to avoid startup crashes
        test_page = self._build_test_sub_tab()
        tool_chat_page = self._build_tool_chat_sub_tab()
        model_to_model_page = self._build_model_to_model_sub_tab()
        arena_page = self._build_arena_sub_tab()
        sub_tabs.addTab(test_page, "🧪 Test")
        sub_tabs.addTab(tool_chat_page, "🔧 Tool Chat")
        sub_tabs.addTab(model_to_model_page, "Model To Model")
        # Arena was built above so all its widget references still
        # resolve, but the sub-tab is reachable only via the Gamify
        # header group's "Arena" navbar button. Stash the widget so
        # the top-level Arena tab can adopt it on first open.
        self._arena_built_widget = arena_page
        sub_tabs.currentChanged.connect(self._on_test_sub_tab_changed)

        layout.addWidget(sub_tabs)

        return w

    def _on_test_sub_tab_changed(self, index: int) -> None:
        """Ensure settings stacks are built when opening advanced test sub-tabs."""
        if index == 2:
            self._ensure_m2m_settings_built()
        elif index == 3:
            self._ensure_arena_settings_built()
    
    def _lazy_load_test_sub_page(self, index: int):
        """Lazy-load test sub-page when tab is first accessed"""
        # Safety check: ensure _test_sub_pages_created exists
        if not hasattr(self, '_test_sub_pages_created'):
            self._test_sub_pages_created = {}
        
        if index in self._test_sub_pages_created:
            return  # Already created

        try:
            if index == 0:  # Test sub-tab
                page = self._build_test_sub_tab()
                tab_text = "🧪 Test"
            elif index == 1:  # Tool Chat sub-tab
                page = self._build_tool_chat_sub_tab()
                tab_text = "🔧 Tool Chat"
            else:
                return

            # Replace placeholder with actual page
            if hasattr(self, 'test_sub_tabs') and self.test_sub_tabs:
                self.test_sub_tabs.removeTab(index)
                self.test_sub_tabs.insertTab(index, page, tab_text)
                self.test_sub_tabs.setCurrentIndex(index)
                self._test_sub_pages_created[index] = page
        except Exception as e:
            import traceback
            error_msg = f"Error loading test sub-page {index}: {e}"
            print(error_msg)
            traceback.print_exc()
            # Write to log file for debugging
            try:
                from core.inference import get_app_root
                log_path = get_app_root() / "logs" / "app.log"
                with open(log_path, "a", encoding="utf-8") as f:
                    f.write(f"\n{error_msg}\n{traceback.format_exc()}\n")
            except:
                pass
    
    def _build_test_sub_tab(self) -> QWidget:
        """Build the regular test sub-tab (non-tool inference)"""
        w = QWidget()
        main_layout = QHBoxLayout(w)
        main_layout.setContentsMargins(15, 15, 15, 15)
        main_layout.setSpacing(15)

        # LEFT COLUMN (3/4 width) - Main test interface
        left_widget = QWidget()
        left_layout = QVBoxLayout(left_widget)
        left_layout.setContentsMargins(0, 0, 0, 0)
        left_layout.setSpacing(15)
        # Store reference to layout for chat display replacement
        self.test_left_layout = left_layout

        # Title and model count selector
        title_row = QHBoxLayout()
        test_title = QLabel("🧪 Test Models - Side-by-Side Chat")
        test_title.setStyleSheet("font-size: 18pt; font-weight: bold; text-decoration: none;")
        title_row.addWidget(test_title)
        title_row.addStretch(1)
        
        # Model count selector (two round checkboxes)
        title_row.addWidget(QLabel("Number of models:"))
        
        # Checkbox for 2 models
        self.test_model_count_2 = QCheckBox("2")
        self.test_model_count_2.setChecked(True)  # Default to 2 models
        self.test_model_count_2.setTristate(False)
        self.test_model_count_2.toggled.connect(self._on_model_count_2_toggled)
        title_row.addWidget(self.test_model_count_2)
        
        # Checkbox for 3 models
        self.test_model_count_3 = QCheckBox("3")
        self.test_model_count_3.setChecked(False)  # Default to 2 models
        self.test_model_count_3.setTristate(False)
        self.test_model_count_3.toggled.connect(self._on_model_count_3_toggled)
        title_row.addWidget(self.test_model_count_3)
        left_layout.addLayout(title_row)

        # Hardware Settings and Tool Calling side by side
        settings_row = QHBoxLayout()
        settings_row.setSpacing(15)

        # GPU selection for inference
        gpu_frame = QGroupBox("⚙️ Hardware Settings")
        gpu_layout = QVBoxLayout(gpu_frame)
        
        # GPU selection dropdown for test tab (filtered by selection)
        gpus = self._get_filtered_gpus()
        gpus = self._sort_gpus_by_memory(gpus)
        
        gpu_row = QHBoxLayout()
        gpu_row.addWidget(QLabel("GPU for Inference:"))
        self.test_gpu_select = QComboBox()
        self.test_gpu_index_map = []
        
        if gpus:
            for idx, gpu in enumerate(gpus):
                gpu_name = gpu.get("name", f"GPU {idx}")
                vram = gpu.get("memory", "N/A")
                orig_idx = gpu.get("_orig_index", idx)
                self.test_gpu_select.addItem(f"GPU {orig_idx}: {gpu_name} ({vram})")
                self.test_gpu_index_map.append(orig_idx)
            info_text = f"✅ {len(gpus)} GPU(s) detected - select one for inference"
        else:
            self.test_gpu_select.addItem("No GPUs available - CPU mode")
            self.test_gpu_select.setEnabled(False)
            info_text = "⚠️ No GPUs detected (CPU mode)"
        
        gpu_row.addWidget(self.test_gpu_select, 1)
        gpu_layout.addLayout(gpu_row)
        
        self.test_gpu_info = QLabel(info_text)
        self.test_gpu_info.setStyleSheet("color: #888; padding: 5px; font-size: 10pt;")
        self.test_gpu_info.setWordWrap(True)
        gpu_layout.addWidget(self.test_gpu_info)
        
        settings_row.addWidget(gpu_frame, 2)  # 2/3 of space
        
        # Tool calling is enabled in Test chat (always on).
        # Use the "🔧 Tool Chat" sub-tab for a dedicated tool-log view.
        tool_frame = QGroupBox("🔧 Tool Calling")
        tool_layout = QVBoxLayout(tool_frame)
        tool_info = QLabel("Tool calling is enabled in this chat. For a dedicated tool log, open the '🔧 Tool Chat' sub-tab above.")
        tool_info.setStyleSheet("color: #888; padding: 5px; font-size: 9pt;")
