    def _log_to_env_terminal(self, message: str):
        """Log a message to the environment terminal"""
        if hasattr(self, 'env_terminal'):
            from datetime import datetime
            timestamp = datetime.now().strftime("%H:%M:%S")
            # Remove emojis for Windows compatibility
            safe_message = message.encode('ascii', errors='ignore').decode('ascii')
            if not safe_message.strip():
                safe_message = message  # Keep original if nothing left
            self.env_terminal.append(f"[{timestamp}] {safe_message}")
            # Auto-scroll to bottom
            self.env_terminal.verticalScrollBar().setValue(
                self.env_terminal.verticalScrollBar().maximum()
            )
    
    def _clear_env_terminal(self):
        """Clear the environment terminal"""
        if hasattr(self, 'env_terminal'):
            self.env_terminal.clear()
            self._log_to_env_terminal("Terminal cleared.")
    
    def _refresh_environment_list(self):
        """Refresh the environment list with modern cards"""
        # Environment Manager page is lazy-loaded; ignore refresh requests
        # until its widgets/layout are initialized.
        if not hasattr(self, "env_cards_layout") or self.env_cards_layout is None:
            return
        self._log_to_env_terminal("🔄 Refreshing environment list...")
        
        # Clear existing cards
        while self.env_cards_layout.count() > 1:  # Keep the stretch
            item = self.env_cards_layout.takeAt(0)
            if item.widget():
                item.widget().deleteLater()
        
        try:
            # Use EnvRegistry to list environments from .envs/ directory (PHASE 2 shared envs)
            from core.envs.env_registry import EnvRegistry
            env_registry = EnvRegistry()
            
            envs = []
            envs_dir = env_registry.envs_dir
            
            if envs_dir.exists():
                for env_dir in sorted(envs_dir.iterdir()):
                    if not env_dir.is_dir() or env_dir.name.startswith('.'):
                        continue
                    
                    env_key = env_dir.name
                    venv_path = env_dir / ".venv"
                    
                    if not venv_path.exists():
                        continue
                    
                    # Get Python version (fast path: parse pyvenv.cfg, avoid spawning subprocess)
                    python_exe = env_registry._get_env_python_executable(env_key)
                    python_version = "Unknown"
                    try:
                        pyvenv_cfg = venv_path / "pyvenv.cfg"
                        if pyvenv_cfg.exists():
                            for line in pyvenv_cfg.read_text(encoding="utf-8", errors="replace").splitlines():
                                if line.lower().startswith("version"):
                                    _, _, val = line.partition("=")
                                    val = val.strip()
                                    if val:
                                        python_version = f"Python {val}"
                                        break
                    except Exception:
                        pass
                    if python_version == "Unknown" and python_exe and python_exe.exists():
                        try:
                            result = subprocess.run(
                                [str(python_exe), "--version"],
                                capture_output=True,
                                text=True,
                                timeout=3,
                                **env_registry.subprocess_flags
                            )
                            if result.returncode == 0:
                                python_version = result.stdout.strip()
                        except Exception:
                            pass
                    
                    # Get package count (estimate from site-packages)
                    package_count = 0
                    if python_exe and python_exe.exists():
                        try:
                            site_packages = venv_path / ("Lib" if sys.platform == "win32" else "lib") / "site-packages"
                            if site_packages.exists():
                                # Count directories in site-packages (rough estimate)
                                package_count = len([d for d in site_packages.iterdir() if d.is_dir() and not d.name.endswith('.dist-info')])
                        except Exception:
                            pass
                    
                    # Disk usage deep scans can be very slow for large envs; compute lazily elsewhere.
                    disk_usage_mb = 0
                    
                    # Get associated models from StateStore (source of truth)
                    from core.state_store import get_state_store
                    state_store = get_state_store()
                    associated_models = []
                    try:
                        onboarding_entries = state_store.list_onboarding_by_env_key(env_key)
                        associated_models = [entry.get("model_id", "") for entry in onboarding_entries if entry.get("model_id")]
                    except Exception as e:
                        self._log_to_env_terminal(f"⚠️ Could not load associated models for {env_key}: {e}")
                    
                    env_info = {
                        "env_id": env_key,
                        "path": str(env_dir),
                        "python_version": python_version,
                        "package_count": package_count,
                        "disk_usage_mb": disk_usage_mb,
                        "associated_models": associated_models,  # Source of truth from StateStore
                    }
                    envs.append(env_info)
            
            # Also check old environments/ directory for backward compatibility
            old_envs = self.env_manager.list_all_environments()
            for old_env in old_envs:
                # Only add if not already in list (avoid duplicates)
                if not any(e["env_id"] == old_env.get("env_id") for e in envs):
                    envs.append(old_env)
            
            if not envs:
                # Empty state card
                empty_card = self._create_empty_state_card()
                self.env_cards_layout.insertWidget(0, empty_card)
                self._log_to_env_terminal("ℹ️ No environments found.")
                return
            
            self._log_to_env_terminal(f"✅ Found {len(envs)} environment(s)")
            
            for env_info in envs:
                card = self._create_environment_card(env_info)
                self.env_cards_layout.insertWidget(self.env_cards_layout.count() - 1, card)
                
        except Exception as e:
            import traceback
            self._log_to_env_terminal(f"❌ Error: {str(e)}")
            self._log_to_env_terminal(traceback.format_exc())
            error_label = QLabel(f"Error loading environments:\n{str(e)}")
            error_label.setStyleSheet("""
                color: #ff6b6b;
                background: rgba(255, 107, 107, 0.1);
                border: 1px solid rgba(255, 107, 107, 0.3);
                border-radius: 8px;
                padding: 15px;
                font-size: 10pt;
            """)
            self.env_cards_layout.insertWidget(0, error_label)
    
